window.SDG4_GRADES = {"1": [{"ch": 0, "q": "Tentang apa Tujuan 4?", "options": ["Sekolah yang baik untuk semua orang", "Mobil cepat", "Kota-kota besar", "Hanya olahraga"], "answer": 0, "explain": "Tujuan 4 bernama Pendidikan Berkualitas. Tujuan ini ingin setiap anak belajar di sekolah yang baik.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Ada berapa tujuan di dunia?", "options": ["5", "17", "10", "50"], "answer": 1, "explain": "Dunia memiliki 17 Tujuan Pembangunan Berkelanjutan. Tujuan 4 membahas pendidikan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Siapa yang menyepakati tujuan-tujuan itu?", "options": ["Satu guru", "Hanya anak-anak", "Negara-negara di dunia, bersama-sama", "Sebuah perusahaan besar"], "answer": 2, "explain": "Semua negara anggota PBB bersama-sama menyepakati tujuan-tujuan itu. PBB adalah kelompok negara-negara.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Apakah setiap anak bisa pergi ke sekolah?", "options": ["Ya, setiap anak bisa", "Hanya di kota", "Hanya saat musim panas", "Tidak, jutaan anak tidak bisa"], "answer": 3, "explain": "Jutaan anak dan remaja tidak bisa pergi ke sekolah. Tujuan 4 ingin setiap anak punya tempat di sekolah.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Mengapa sebagian anak tidak bisa bersekolah?", "options": ["Mereka tinggal jauh atau keluarganya miskin", "Mereka terlalu tinggi", "Sekolah selalu tutup", "Mereka tidak suka belajar"], "answer": 0, "explain": "Jalan kaki yang jauh, biaya, dan kemiskinan membuat sebagian anak tidak bisa bersekolah. Tujuan 4 ingin menghapus hambatan ini.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa yang seharusnya dimiliki setiap anak?", "options": ["Sebuah mobil", "Tempat di sekolah yang baik dekat rumah", "Sebuah ponsel", "Rumah di atas langit"], "answer": 1, "explain": "Setiap anak seharusnya punya tempat di sekolah yang baik, yang dekat dengan rumah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apa artinya menyelesaikan sekolah?", "options": ["Pergi pada hari pertama", "Membolos setiap pelajaran", "Melewati semua kelas dan belajar", "Tidak pernah kembali"], "answer": 2, "explain": "Menyelesaikan sekolah berarti menempuh semua kelas sampai akhir. Banyak anak keluar sebelum selesai.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Mengapa baik jika anak menyelesaikan sekolah?", "options": ["Membuat mereka lelah", "Tidak penting", "Menghentikan pelajaran mereka", "Membantu mereka belajar dan mendapat pekerjaan nanti"], "answer": 3, "explain": "Menyelesaikan sekolah memberi anak lebih banyak keterampilan dan lebih banyak kesempatan dalam hidup.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apakah kebanyakan anak menyelesaikan sekolah di setiap negara?", "options": ["Tidak, banyak yang keluar lebih awal", "Ya, semuanya menyelesaikan", "Tidak ada yang sekolah", "Hanya anak perempuan yang menyelesaikan"], "answer": 0, "explain": "Banyak anak tidak menyelesaikan sekolah, jadi Tujuan 4 ingin lebih banyak anak bertahan sampai akhir.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa yang dipelajari anak di sekolah?", "options": ["Hanya tidur", "Membaca, menulis, dan berhitung", "Hanya bermain game", "Tidak ada yang berguna"], "answer": 1, "explain": "Di sekolah anak belajar membaca, menulis, dan berhitung. Keterampilan ini berguna sepanjang hidup mereka.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Apakah cukup bagi anak untuk sekadar hadir di sekolah?", "options": ["Ya, hadir saja sudah cukup", "Hanya guru yang perlu belajar", "Tidak, mereka harus benar-benar belajar", "Tidak masalah"], "answer": 2, "explain": "Hadir di sekolah tidak cukup. Anak harus benar-benar mempelajari hal-hal yang berguna.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa yang membantu anak belajar membaca?", "options": ["Musik keras saja", "Menonton TV seharian", "Tinggal di rumah", "Buku dan guru yang baik"], "answer": 3, "explain": "Buku, guru yang baik, dan latihan membantu anak belajar membaca.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu keterampilan?", "options": ["Hal-hal yang bisa kamu lakukan dengan baik, seperti menggambar atau berhitung", "Tempat kamu bermain bersama teman sepulang sekolah", "Aturan yang ditulis guru di papan tulis setiap pagi", "Toko yang menjual permen dan mainan dekat rumahmu"], "answer": 0, "explain": "Keterampilan adalah hal-hal yang kita pelajari agar bisa melakukannya dengan baik. Tujuan 4 ingin kaum muda belajar keterampilan untuk pekerjaan dan kehidupan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Mengapa kaum muda membutuhkan keterampilan?", "options": ["Untuk berhenti sekolah", "Untuk mendapat pekerjaan dan membantu komunitas mereka", "Untuk merasa bosan", "Mereka tidak membutuhkannya"], "answer": 1, "explain": "Keterampilan membantu kaum muda mendapatkan pekerjaan dan membantu keluarga serta komunitas mereka.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Manakah yang merupakan keterampilan berguna?", "options": ["Merusak barang", "Bersembunyi dari teman", "Menggunakan komputer dengan aman", "Mengabaikan aturan"], "answer": 2, "explain": "Belajar komputer dan keterampilan berguna lainnya membantu kaum muda dalam pekerjaan dan kehidupan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apakah anak perempuan dan laki-laki harus punya kesempatan yang sama untuk bersekolah?", "options": ["Tidak, hanya laki-laki", "Tidak, hanya perempuan", "Hanya di beberapa negara", "Ya, keduanya harus"], "answer": 3, "explain": "Anak perempuan dan laki-laki harus punya kesempatan belajar yang sama. Tujuan 4 ingin mengakhiri perbedaan yang tidak adil di antara keduanya.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa arti adil bagi sekolah?", "options": ["Setiap orang mendapat kesempatan belajar", "Hanya anak kaya yang belajar", "Ada anak yang tidak mendapat apa-apa", "Hanya sebagian anak yang diterima"], "answer": 0, "explain": "Adil berarti setiap anak mendapat kesempatan belajar, apa pun keluarga, rumah, atau latar belakangnya.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Siapa yang seharusnya bisa bersekolah?", "options": ["Hanya anak yang punya uang", "Setiap anak, apa pun keadaan keluarganya", "Hanya anak yang tinggal di kota", "Tidak ada anak"], "answer": 1, "explain": "Tujuan 4 menyatakan bahwa pendidikan berkualitas harus untuk semua orang, termasuk anak-anak yang miskin atau tinggal jauh.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Apa yang paling membantu sebuah sekolah?", "options": ["Kolam renang besar", "Mobil mewah di tempat parkir", "Guru yang baik dan terlatih", "Ruang kelas kosong"], "answer": 2, "explain": "Guru yang baik membantu anak belajar. Tujuan 4 menginginkan lebih banyak guru yang terlatih.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Apa yang dibutuhkan guru untuk membantu anak belajar?", "options": ["Tidak ada bantuan sama sekali", "Bekerja tanpa dibayar", "Menjauh dari kelas", "Pelatihan dan dukungan"], "answer": 3, "explain": "Guru membutuhkan pelatihan dan dukungan yang baik untuk membantu setiap anak belajar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "Apakah SD dan SMP seharusnya gratis?", "options": ["Ya, Tujuan 4 menginginkan sekolah gratis", "Tidak, sekolah harus mahal", "Hanya untuk anak laki-laki", "Hanya di kota"], "answer": 0, "explain": "Tujuan 4 menginginkan SD dan SMP gratis untuk semua orang.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "Siapa yang membuat sekolah mungkin bagi setiap anak?", "options": ["Hanya orang tua yang punya uang", "Pemerintah dan komunitas", "Tidak ada", "Hanya anak-anak"], "answer": 1, "explain": "Pemerintah dan komunitas membantu membangun sekolah dan membayar guru, agar setiap anak bisa bersekolah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Kapan negara-negara menyepakati tujuan-tujuan itu?", "options": ["1900", "1950", "2015", "2050"], "answer": 2, "explain": "Negara-negara menyepakati tujuan-tujuan itu pada 2015. Mereka menetapkan 2030 sebagai tahun untuk mencapainya.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Pada tahun berapa tujuan-tujuan itu harus tercapai?", "options": ["2010", "1990", "2100", "2030"], "answer": 3, "explain": "Negara-negara menetapkan 2030 sebagai tahun untuk mencapai tujuan-tujuan itu.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Mengapa anak kecil sebaiknya pergi ke prasekolah?", "options": ["Untuk bersiap masuk SD", "Karena sedang libur", "Untuk berhenti belajar", "Tidak berguna"], "answer": 0, "explain": "Belajar sejak dini membantu anak kecil bersiap masuk SD dan tumbuh.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Kapan belajar sejak dini terjadi?", "options": ["Hanya pada usia 15 tahun", "Sebelum SD", "Hanya pada usia 30 tahun", "Tidak pernah"], "answer": 1, "explain": "Pendidikan anak usia dini adalah untuk tahun-tahun sebelum SD.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "Apa itu literasi?", "options": ["Mampu berenang", "Mampu menggambar", "Mampu membaca dan menulis", "Mampu berlari cepat"], "answer": 2, "explain": "Literasi berarti membaca dan menulis. Tujuan 4 ingin semua kaum muda menjadi melek huruf.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "Apa itu numerasi?", "options": ["Mampu bernyanyi", "Mampu memasak", "Mampu melukis", "Mampu berhitung dan menghitung"], "answer": 3, "explain": "Numerasi berarti menggunakan angka, seperti berhitung dan menjumlahkan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Apakah anak penyandang disabilitas harus bersekolah bersama anak lain?", "options": ["Ya, sekolah harus menerima mereka", "Tidak, mereka harus tinggal di rumah", "Hanya pada akhir pekan", "Hanya di tempat khusus"], "answer": 0, "explain": "Tujuan 4 menginginkan sekolah yang menyambut dan mengikutsertakan setiap anak, termasuk anak penyandang disabilitas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Apa yang membuat sekolah inklusif?", "options": ["Hanya sebagian anak yang diizinkan", "Semua orang diterima dan bisa belajar", "Anak-anak dipisahkan", "Tidak ada yang boleh masuk"], "answer": 1, "explain": "Sekolah inklusif menerima setiap anak, sehingga semua orang bisa belajar bersama.", "src": "UN 2030 Agenda (2015)"}], "2": [{"ch": 0, "q": "Berapa nomor untuk Pendidikan Berkualitas?", "options": ["4", "2", "9", "12"], "answer": 0, "explain": "Pendidikan Berkualitas adalah Tujuan 4 dari 17 Tujuan Global.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Tujuan 4 membahas tentang apa?", "options": ["Hanya olahraga", "Pembelajaran yang baik untuk semua orang", "Hanya liburan", "Hanya kota-kota besar"], "answer": 1, "explain": "Tujuan 4 ingin setiap anak dan orang dewasa mendapat pendidikan yang baik.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Pada tahun berapa negara-negara menyepakati Tujuan Global?", "options": ["1945", "2001", "2015", "2040"], "answer": 2, "explain": "Pada 2015 para pemimpin dunia menyepakati 17 Tujuan Global yang harus dicapai pada 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Mengapa anak-anak harus bersekolah?", "options": ["Untuk tidur", "Untuk terlambat", "Untuk sendirian", "Untuk belajar dan tumbuh"], "answer": 3, "explain": "Sekolah membantu anak belajar membaca, berhitung, dan mendapat teman.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "Apakah setiap anak berhak untuk bersekolah?", "options": ["Ya", "Tidak", "Hanya anak laki-laki", "Hanya di kota"], "answer": 0, "explain": "Setiap anak berhak mendapat pendidikan.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "Seorang anak tidak bisa sampai ke sekolah karena terlalu jauh. Ini adalah masalah:", "options": ["Warna", "Akses", "Tidur", "Musik"], "answer": 1, "explain": "Akses berarti bisa menjangkau sekolah dan masuk ke dalamnya.", "src": "UNESCO"}, {"ch": 1, "q": "Tempat apa yang membantu anak-anak belajar bersama?", "options": ["Toko sepatu", "Tempat parkir", "Sebuah sekolah", "Rak toko kelontong"], "answer": 2, "explain": "Sekolah adalah tempat anak-anak belajar bersama guru.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa orang tua ingin anak mereka menyelesaikan sekolah?", "options": ["Membuat anak tidak suka membaca buku di rumah", "Berarti uang sekolah tidak perlu dibayar lagi", "Menghilangkan kebutuhan untuk belajar setelah sekolah", "Menyelesaikan sekolah memperbaiki pekerjaan dan kesehatan anak di masa depan"], "answer": 3, "explain": "Menyelesaikan sekolah terkait dengan pekerjaan, penghasilan, dan kesehatan yang lebih baik di kemudian hari.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Mengapa sebagian anak putus sekolah lebih awal?", "options": ["Uang, jarak, atau sakit bisa menghalangi mereka", "Mereka tidak suka belajar", "Sekolah terlalu singkat", "Mereka punya terlalu banyak buku"], "answer": 0, "explain": "Banyak anak keluar lebih awal karena uang, perjalanan, atau sakit.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa baik untuk tetap bersekolah?", "options": ["Kamu jadi bosan", "Kamu belajar lebih banyak setiap tahun", "Kamu kehilangan teman", "Kamu berhenti belajar"], "answer": 1, "explain": "Setiap tahun di sekolah membantumu belajar lebih banyak dan membangun keterampilan.", "src": "UNESCO"}, {"ch": 2, "q": "Manakah dari ini yang membantu siswa menyelesaikan sekolah?", "options": ["Membolos setiap kelas", "Melewatkan makan", "Dukungan dari keluarga dan guru", "Tidak pernah bertanya"], "answer": 2, "explain": "Dukungan dari keluarga dan guru membantu siswa terus maju.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu membaca?", "options": ["Memakan kata-kata", "Hanya menggambar", "Berlari cepat", "Memahami kata-kata di halaman"], "answer": 3, "explain": "Membaca berarti memahami kata-kata dan maknanya.", "src": "UNESCO"}, {"ch": 3, "q": "Keterampilan apa yang membantu kamu menjumlahkan 2 dan 3?", "options": ["Berhitung", "Berenang", "Hanya bernyanyi", "Memasak"], "answer": 0, "explain": "Berhitung membantu kita mengetahui berapa banyak benda secara keseluruhan.", "src": "UNESCO"}, {"ch": 3, "q": "Kegiatan apa yang membantu anak kecil membangun keterampilan membaca awal?", "options": ["Menonton televisi berjam-jam setiap hari", "Membacakan cerita dengan keras dan membicarakan gambarnya", "Menyalin daftar panjang kata acak dalam diam", "Hanya membaca soal matematika dan tidak pernah cerita"], "answer": 1, "explain": "Membaca bersama dan mengobrol membangun kosakata dan literasi awal.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu perpustakaan?", "options": ["Tempat untuk menjual mobil", "Tempat yang hanya berisi mainan", "Tempat dengan banyak buku", "Tempat untuk berenang"], "answer": 2, "explain": "Perpustakaan adalah tempat orang bisa membaca dan meminjam buku.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu kerja tim?", "options": ["Selalu bekerja sendirian", "Memenangkan setiap permainan sendirian", "Bersembunyi dari teman", "Bekerja sama dengan orang lain"], "answer": 3, "explain": "Kerja tim berarti bekerja sama untuk mencapai tujuan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Keterampilan apa yang membantu kamu mengungkapkan perasaan?", "options": ["Komunikasi", "Melompat-lompat", "Tidur", "Mengecat dinding"], "answer": 0, "explain": "Komunikasi berarti menyampaikan pikiran dan mendengarkan orang lain.", "src": "UNESCO"}, {"ch": 4, "q": "Apa artinya menjadi kreatif?", "options": ["Menyalin persis", "Membuat ide atau benda baru", "Tidak pernah mencoba", "Hanya menggunakan uang"], "answer": 1, "explain": "Kreatif berarti membuat sesuatu yang baru, seperti gambar atau cerita.", "src": "UNESCO"}, {"ch": 4, "q": "Keterampilan apa yang membantu kamu memecahkan masalah?", "options": ["Menutup mata", "Lari", "Berpikir dengan cermat", "Mengabaikannya"], "answer": 2, "explain": "Berpikir dengan cermat membantu kita menemukan solusi untuk masalah.", "src": "UNESCO"}, {"ch": 5, "q": "Haruskah anak perempuan dan laki-laki sama-sama bersekolah?", "options": ["Hanya laki-laki", "Hanya perempuan", "Tidak keduanya", "Ya, keduanya harus"], "answer": 3, "explain": "Anak perempuan dan laki-laki harus punya kesempatan yang sama untuk bersekolah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa arti sama dalam pendidikan?", "options": ["Semua orang mendapat kesempatan yang adil", "Semua orang memakai sepatu yang sama", "Ada anak yang tidak punya guru", "Hanya anak kaya yang belajar"], "answer": 0, "explain": "Pendidikan yang setara berarti semua orang mendapat kesempatan yang adil untuk belajar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Manakah cara yang adil untuk berbagi buku di sekolah?", "options": ["Hanya anak tercepat yang mendapat buku", "Setiap orang mendapat giliran", "Hanya guru yang menyimpannya", "Hanya anak tertinggi"], "answer": 1, "explain": "Berbagi secara adil berarti setiap anak mendapat kesempatan menggunakan buku.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Anak-anak mana yang berhak bersekolah?", "options": ["Hanya anak yang orang tuanya membayar biaya tertinggi", "Hanya anak laki-laki yang tinggal di ibu kota", "Setiap anak, apa pun keluarga atau latar belakangnya", "Hanya anak yang sudah bisa membaca dengan sangat baik"], "answer": 2, "explain": "Setiap anak berhak mendapat pendidikan, tanpa memandang latar belakang.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 6, "q": "Apa tugas seorang guru?", "options": ["Hanya menjual makanan", "Hanya mengemudikan bus", "Membersihkan langit", "Membantu anak belajar"], "answer": 3, "explain": "Guru membantu anak mempelajari hal baru dan tumbuh.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa sekolah membutuhkan guru yang baik?", "options": ["Guru membantu anak belajar dengan baik", "Guru menghentikan semua pelajaran", "Guru hanya memberi pekerjaan rumah", "Guru tidak diperlukan"], "answer": 0, "explain": "Guru yang baik membantu anak belajar dan merasa aman di sekolah.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa yang membantu guru menjadi lebih baik dalam mengajar?", "options": ["Gaji lebih kecil untuk semua orang", "Pelatihan dan dukungan", "Menutup semua sekolah", "Mengabaikan anak-anak"], "answer": 1, "explain": "Pelatihan membantu guru belajar cara baru untuk mengajar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa yang bisa ditunjukkan guru yang baik kepada anak-anak?", "options": ["Cara bersikap kejam", "Cara bersikap malas", "Cara bersikap baik dan penuh rasa ingin tahu", "Cara bersembunyi"], "answer": 2, "explain": "Guru yang baik membantu anak menjadi baik hati, ingin tahu, dan berani.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Apa yang dibutuhkan sekolah agar berjalan dengan baik?", "options": ["Hanya komputer", "Hanya musik keras", "Hanya kolam renang", "Buku, meja, dan guru"], "answer": 3, "explain": "Sekolah membutuhkan banyak hal, termasuk buku, meja, dan guru.", "src": "UNESCO"}, {"ch": 7, "q": "Apa yang membantu menjaga anak tetap aman dan sehat di sekolah?", "options": ["Air bersih dan toilet", "Mobil besar", "Tanpa atap", "Hanya pengeras suara yang bising"], "answer": 0, "explain": "Air bersih dan toilet membantu anak tetap sehat di sekolah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "Mengapa beberapa sekolah tidak punya buku?", "options": ["Buku tidak diperlukan", "Mereka tidak punya cukup uang", "Anak-anak tidak membaca", "Buku terlalu berat"], "answer": 1, "explain": "Uang dibutuhkan untuk membeli buku dan perlengkapan sekolah lainnya.", "src": "UNESCO"}, {"ch": 7, "q": "Mengapa sekolah membutuhkan uang?", "options": ["Hanya untuk membeli mobil", "Hanya untuk membayar liburan", "Untuk membeli barang untuk belajar", "Sekolah tidak membutuhkan uang"], "answer": 2, "explain": "Uang membayar buku, guru, meja, dan perlengkapan sekolah lainnya.", "src": "UNESCO"}, {"ch": 8, "q": "Dokumen apa yang menyatakan bahwa setiap orang berhak atas pendidikan?", "options": ["Buku masak dengan resep untuk makan keluarga", "Peta kawah dan laut di Bulan", "Jadwal pelajaran untuk satu semester", "Deklarasi Universal Hak Asasi Manusia"], "answer": 3, "explain": "Deklarasi Universal Hak Asasi Manusia menyatakan bahwa setiap orang berhak atas pendidikan.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Pada tahun berapa Deklarasi Universal Hak Asasi Manusia disepakati?", "options": ["1948", "1900", "1975", "2030"], "answer": 0, "explain": "Deklarasi ini disepakati pada 1948 oleh Majelis Umum PBB.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Organisasi apa yang dibentuk untuk membantu negara-negara bekerja sama demi perdamaian dan pendidikan?", "options": ["Sirkus", "Perserikatan Bangsa-Bangsa", "Klub olahraga", "Perusahaan mobil"], "answer": 1, "explain": "PBB dibentuk setelah Perang Dunia Kedua untuk membantu negara-negara bekerja sama.", "src": "United Nations"}, {"ch": 9, "q": "Apa cara yang baik bagi anak kecil untuk belajar?", "options": ["Duduk diam sepanjang hari", "Diam saja", "Bermain dan berbicara", "Bekerja di malam hari"], "answer": 2, "explain": "Anak kecil banyak belajar melalui bermain dan berbicara dengan orang dewasa.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa yang membantu bayi belajar?", "options": ["Membiarkan mereka dalam gelap", "Tidak pernah menggendong mereka", "Hanya memberi permen", "Mengajak mereka bicara dan bernyanyi"], "answer": 3, "explain": "Berbicara, bernyanyi, dan bermain bersama bayi membantu mereka belajar bahasa.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa yang membantu anak tumbuh dengan baik sebelum sekolah?", "options": ["Kasih sayang dan perhatian dari orang dewasa", "Dibiarkan sendirian", "Terlalu banyak permen", "Tidak tidur"], "answer": 0, "explain": "Kasih sayang, perhatian, dan bermain di masa kecil membantu anak tumbuh kuat dan siap belajar.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Apa arti literasi?", "options": ["Mampu menari", "Mampu membaca dan menulis", "Mampu berenang", "Hanya mampu menggambar"], "answer": 1, "explain": "Literasi berarti mampu membaca dan menulis.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Huruf apa yang datang setelah A dalam abjad?", "options": ["Z", "D", "B", "Q"], "answer": 2, "explain": "B datang setelah A dalam abjad.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Manakah dari ini yang membantu orang menjadi lebih baik dalam membaca?", "options": ["Tidak pernah membuka buku", "Hanya menonton video", "Melupakan huruf", "Membaca sedikit setiap hari"], "answer": 3, "explain": "Membaca sedikit setiap hari membantu orang menjadi lebih baik dalam membaca.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "Apa arti inklusi di sekolah?", "options": ["Semua orang diterima dan bisa belajar", "Hanya sebagian anak yang boleh bergabung", "Semua anak harus sama", "Anak-anak harus tinggal di rumah"], "answer": 0, "explain": "Inklusi berarti setiap anak bisa belajar di sekolah, termasuk anak penyandang disabilitas.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apakah anak penyandang disabilitas harus bisa bersekolah?", "options": ["Tidak", "Ya", "Hanya pada hari Minggu", "Hanya jika mereka tidak punya teman"], "answer": 1, "explain": "Anak penyandang disabilitas berhak bersekolah bersama yang lain.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa yang membantu anak pengguna kursi roda untuk belajar di sekolah?", "options": ["Sekolah tanpa pintu", "Sekolah yang hanya punya tangga", "Sekolah dengan jalur landai", "Sekolah yang sangat jauh"], "answer": 2, "explain": "Jalur landai dan ruang tanpa anak tangga membantu anak pengguna kursi roda bergerak di sekolah.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa cara yang baik untuk memperlakukan teman sekelas yang berbeda?", "options": ["Mengucilkannya", "Memanggilnya dengan nama buruk", "Mengabaikannya", "Mengajaknya bermain"], "answer": 3, "explain": "Melibatkan teman sekelas membantu semua orang merasa diterima.", "src": "UN CRPD (2006), Article 24"}, {"ch": 0, "q": "Pada tahun berapa Tujuan Global seharusnya tercapai?", "options": ["2030", "1990", "2000", "2060"], "answer": 0, "explain": "Tujuan Global ditargetkan tercapai pada 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Apa yang membantu anak-anak sampai ke sekolah dengan aman?", "options": ["Jalan yang ditutup", "Jalan dan jalur yang aman", "Menyeberangi jalan ramai sendirian", "Tinggal di rumah"], "answer": 1, "explain": "Jalan dan jalur yang aman membantu anak-anak mencapai sekolah dengan selamat.", "src": "UNESCO"}, {"ch": 2, "q": "Apa alasan yang baik untuk terus maju ketika sekolah terasa sulit?", "options": ["Tidak ada yang akan memperhatikan", "Sekolah tidak pernah membantu", "Kamu bisa belajar dan mencapai tujuanmu", "Belajar tidak berguna"], "answer": 2, "explain": "Terus maju membantumu mencapai tujuan dan mempelajari hal baru.", "src": "UNESCO"}, {"ch": 8, "q": "Apa kepanjangan dari singkatan PBB?", "options": ["Perawat Bersatu", "Catatan Unik", "Nama di Bawah", "Perserikatan Bangsa-Bangsa"], "answer": 3, "explain": "PBB adalah singkatan dari Perserikatan Bangsa-Bangsa, atau United Nations.", "src": "United Nations"}, {"ch": 9, "q": "Mengapa bermain baik untuk anak kecil?", "options": ["Membantu mereka belajar dan tumbuh", "Membuang waktu", "Hanya membuat mereka lelah", "Tidak diperbolehkan"], "answer": 0, "explain": "Bermain membangun kemampuan berpikir, bahasa, dan keterampilan sosial.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Apa huruf pertama dalam abjad?", "options": ["Z", "A", "M", "K"], "answer": 1, "explain": "A adalah huruf pertama dalam abjad.", "src": "UNESCO, International Literacy Day"}], "3": [{"ch": 0, "q": "Apa arti SDG?", "options": ["Tujuan Pembangunan Berkelanjutan", "Super Game Anjing", "Panduan Meja Sederhana", "Grup Makan Malam Manis"], "answer": 0, "explain": "SDG berarti Tujuan Pembangunan Berkelanjutan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Ada berapa Tujuan Global?", "options": ["7", "17", "12", "27"], "answer": 1, "explain": "Ada 17 Tujuan Global, dan Tujuan 4 membahas tentang pendidikan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Kata apa yang paling tepat menggambarkan Tujuan 4?", "options": ["Kecepatan", "Keheningan", "Kualitas", "Harga"], "answer": 2, "explain": "Tujuan 4 disebut Pendidikan Berkualitas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Tujuan nomor berapa yang membahas air bersih dan sanitasi?", "options": ["2", "9", "15", "6"], "answer": 3, "explain": "Tujuan 6 adalah Air Bersih dan Sanitasi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa itu target dalam Tujuan Global?", "options": ["Sasaran khusus yang ingin dicapai", "Jenis kertas", "Jenis olahraga", "Jenis makanan"], "answer": 0, "explain": "Setiap tujuan memiliki target yang menjelaskan dengan tepat apa yang harus dicapai.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Apa hambatan yang bisa membuat anak perempuan tidak pergi ke sekolah?", "options": ["Terlalu banyak buku", "Jalan kaki jauh di jalan yang tidak aman", "Terlalu banyak sinar matahari", "Terlalu banyak guru"], "answer": 1, "explain": "Jarak dan jalan yang tidak aman bisa membuat anak tidak sampai ke sekolah.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "Apa artinya sekolah gratis?", "options": ["Anak-anak harus membayar untuk masuk", "Anak-anak harus membawa uang ke setiap pelajaran", "Anak-anak tidak membayar biaya untuk masuk", "Anak-anak hanya bisa datang pada akhir pekan"], "answer": 2, "explain": "Sekolah gratis berarti anak-anak tidak perlu membayar biaya untuk bersekolah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Hak apa yang menyatakan bahwa setiap anak harus bisa bersekolah?", "options": ["Hak atas mobil", "Hak atas liburan", "Hak atas tim olahraga", "Hak atas pendidikan"], "answer": 3, "explain": "Hak atas pendidikan berarti setiap anak bisa bersekolah.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "Apa itu daerah terpencil?", "options": ["Tempat yang jauh dari kota dan desa", "Tempat tanpa langit", "Tempat di bawah laut", "Tempat tanpa penduduk sama sekali"], "answer": 0, "explain": "Daerah terpencil jauh dari kota sehingga anak-anak mungkin kesulitan mencapai sekolah.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu putus sekolah?", "options": ["Siswa yang selesai lebih awal", "Siswa yang meninggalkan sekolah sebelum selesai", "Guru yang keluar", "Siswa yang membaca cepat"], "answer": 1, "explain": "Putus sekolah berarti meninggalkan sekolah sebelum menyelesaikannya.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa penting bagi anak untuk menyelesaikan sekolah dasar?", "options": ["Berarti tidak ada lagi belajar selamanya", "Hanya untuk bersenang-senang", "Memberi mereka kemampuan dasar membaca, menulis, dan berhitung", "Menghilangkan kebutuhan akan pekerjaan rumah"], "answer": 2, "explain": "Menyelesaikan sekolah dasar membangun keterampilan dasar untuk kehidupan.", "src": "UNESCO"}, {"ch": 2, "q": "Apa yang bisa membantu siswa tetap bersekolah?", "options": ["Membolos pelajaran", "Pergi lebih awal", "Mengabaikan guru", "Bimbingan dan dukungan"], "answer": 3, "explain": "Bimbingan dan dukungan membantu siswa tetap bersekolah dan terus belajar.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu kehadiran?", "options": ["Hadir di sekolah", "Memenangkan hadiah", "Menulis surat", "Membeli buku"], "answer": 0, "explain": "Kehadiran berarti berada di sekolah untuk mengikuti pelajaran.", "src": "UNESCO"}, {"ch": 2, "q": "Apa yang harus dilakukan sekolah ketika seorang anak absen selama banyak hari?", "options": ["Melupakannya", "Mencari tahu alasannya dan membantunya kembali", "Mengeluarkannya dari daftar tanpa alasan", "Memintanya membayar denda"], "answer": 1, "explain": "Sekolah dapat mendukung keluarga untuk membantu anak kembali bersekolah.", "src": "UNESCO"}, {"ch": 3, "q": "Keterampilan apa yang terutama berkaitan dengan numerasi?", "options": ["Melukis gambar dengan warna cerah dan kuas", "Menyanyikan lagu tentang hewan dan musim", "Menggunakan angka dan matematika dasar dalam kehidupan sehari-hari", "Menghafal nama-nama negara di dunia"], "answer": 2, "explain": "Numerasi berarti menggunakan angka dengan percaya diri dalam kehidupan sehari-hari.", "src": "UNESCO"}, {"ch": 3, "q": "Apa cara yang baik untuk memeriksa pembelajaranmu?", "options": ["Tidak pernah mencoba lagi", "Menyalin tanpa berpikir", "Tidur selama pelajaran", "Bertanya dan berlatih"], "answer": 3, "explain": "Berlatih dan bertanya membantumu memahami hal baru.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu hasil belajar?", "options": ["Apa yang bisa dilakukan pelajar setelah belajar", "Harga sekolah", "Cuaca pada hari ujian", "Jumlah meja"], "answer": 0, "explain": "Hasil belajar adalah keterampilan atau pengetahuan yang diperoleh pelajar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Untuk apa tes digunakan?", "options": ["Menentukan cuaca", "Memeriksa apa yang sudah dipelajari seseorang", "Membuat matahari terbit", "Memilih menu makan siang"], "answer": 1, "explain": "Tes membantu guru dan pelajar melihat apa yang sudah dipelajari.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Apa itu pemahaman bacaan?", "options": ["Membaca sangat cepat", "Membaca dengan suara keras", "Memahami apa yang kamu baca", "Hanya membaca gambar"], "answer": 2, "explain": "Pemahaman bacaan berarti memahami makna sebuah teks.", "src": "UNESCO"}, {"ch": 4, "q": "Keterampilan apa yang membantumu bekerja dengan baik bersama orang dari tempat lain?", "options": ["Mengabaikan orang lain", "Berteriak kepada orang lain", "Bersembunyi dari orang lain", "Menghargai orang lain"], "answer": 3, "explain": "Rasa hormat membantu orang dari latar belakang berbeda untuk bekerja dan belajar bersama.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu berpikir kritis?", "options": ["Memeriksa apakah sebuah gagasan masuk akal", "Percaya pada semua gagasan sekaligus", "Tidak pernah bertanya", "Melupakan apa yang dibaca"], "answer": 0, "explain": "Berpikir kritis berarti bertanya dan memeriksa fakta.", "src": "UNESCO"}, {"ch": 4, "q": "Keterampilan apa yang bisa membantumu mendapat pekerjaan suatu hari nanti?", "options": ["Tidur lama pada jam sekolah", "Keterampilan praktis seperti komputer atau memperbaiki", "Menghindari semua pelajaran dan latihan di rumah", "Menolak belajar hal baru sama sekali"], "answer": 1, "explain": "Keterampilan praktis dan kerja membantu orang bekerja dan menghidupi diri sendiri.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Keterampilan apa yang membantu tim mengambil keputusan?", "options": ["Berteriak paling keras", "Mengabaikan tim", "Mendengarkan setiap orang", "Meninggalkan ruangan"], "answer": 2, "explain": "Mendengarkan semua orang membantu tim memilih dengan baik.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu keterampilan digital?", "options": ["Hanya menggunakan pensil", "Merusak komputer", "Tidak pernah menggunakan internet", "Menggunakan komputer dan internet dengan aman"], "answer": 3, "explain": "Keterampilan digital membantu orang menggunakan teknologi dengan aman dan baik.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa arti kesetaraan dalam pendidikan?", "options": ["Dukungan yang adil agar setiap anak bisa belajar", "Setiap anak mendapat hal yang persis sama", "Hanya siswa terbaik yang mendapat bantuan", "Sekolah tidak perlu membantu"], "answer": 0, "explain": "Kesetaraan berarti memberi setiap anak dukungan yang dibutuhkan untuk belajar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Kelompok anak mana yang sering tertinggal dari sekolah?", "options": ["Anak yang senang bermain sepak bola saat istirahat", "Anak dari keluarga miskin atau daerah terpencil", "Anak yang suka bernyanyi di paduan suara sekolah", "Anak yang selalu duduk di barisan depan"], "answer": 1, "explain": "Anak dari keluarga miskin dan daerah terpencil lebih mungkin tidak bersekolah.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Apa itu kesenjangan gender di sekolah?", "options": ["Celah di lapangan tempat anak bermain", "Jeda singkat antara dua pelajaran setiap hari", "Perbedaan antara anak perempuan dan laki-laki di sekolah", "Lubang di dinding sekolah yang perlu diperbaiki"], "answer": 2, "explain": "Kesenjangan gender adalah perbedaan antara anak perempuan dan laki-laki dalam pendidikan atau pembelajaran.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Mengapa sekolah harus menerima anak dari setiap bahasa dan latar belakang?", "options": ["Hanya satu bahasa yang boleh digunakan", "Hanya satu latar belakang yang boleh diterima", "Anak-anak harus dikirim pergi", "Setiap orang berhak mendapat kesempatan belajar yang adil"], "answer": 3, "explain": "Pendidikan harus mencakup semua anak secara adil, apa pun latar belakangnya.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Kelompok pelajar mana yang mungkin membutuhkan bantuan tambahan agar aman di sekolah?", "options": ["Anak-anak rentan", "Anak-anak yang selalu bahagia", "Anak-anak yang bisa terbang", "Anak-anak yang tidak pernah absen"], "answer": 0, "explain": "Anak-anak rentan mungkin lebih berisiko terabaikan atau terluka, sehingga mereka membutuhkan bantuan tambahan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Apa itu kekurangan guru?", "options": ["Terlalu banyak guru untuk anak-anak", "Tidak cukup guru terlatih untuk anak-anak", "Guru yang tidak pernah bekerja", "Guru yang terlalu banyak libur"], "answer": 1, "explain": "Kekurangan berarti tidak ada cukup guru terlatih.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa yang membantu guru baru untuk berhasil?", "options": ["Tidak ada dukungan sama sekali", "Dikirim ke negara lain", "Bimbingan dan pelatihan", "Jeda panjang tanpa bayaran"], "answer": 2, "explain": "Bimbingan dan pelatihan membantu guru baru berkembang.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa kondisi kerja guru penting?", "options": ["Tidak berpengaruh sama sekali", "Hanya penting untuk mobil guru", "Hanya penting di kota", "Memengaruhi seberapa baik anak-anak belajar"], "answer": 3, "explain": "Kondisi yang baik membantu guru bertahan dan mengajar dengan baik.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa yang dibutuhkan guru untuk merencanakan pelajaran?", "options": ["Tujuan yang jelas dan rencana yang baik", "Tidak tahu apa-apa tentang mata pelajaran", "Kursi yang rusak", "Liburan"], "answer": 0, "explain": "Tujuan yang jelas dan rencana membantu guru mengajar dengan baik.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa yang dibutuhkan guru untuk terus belajar?", "options": ["Tidak perlu belajar lagi", "Pelatihan berkelanjutan", "Hanya liburan", "Hanya uang"], "answer": 1, "explain": "Guru terus belajar melalui pelatihan berkelanjutan.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Apa itu biaya sekolah?", "options": ["Hadiah untuk nilai bagus", "Hadiah dari guru", "Uang yang dibayarkan untuk bersekolah", "Denda karena terlambat"], "answer": 2, "explain": "Biaya sekolah adalah uang yang kadang dibayarkan keluarga untuk bersekolah.", "src": "UNESCO"}, {"ch": 7, "q": "Mengapa pemerintah membelanjakan uang untuk sekolah?", "options": ["Hanya untuk membeli lebih banyak liburan", "Hanya untuk membangun lebih banyak jalan", "Untuk mengurangi hari sekolah", "Untuk membantu anak belajar dan tumbuh"], "answer": 3, "explain": "Uang publik membayar guru, gedung, dan buku agar anak-anak bisa belajar.", "src": "UNESCO"}, {"ch": 7, "q": "Apa yang dibutuhkan ruang kelas agar menjadi tempat belajar yang aman?", "options": ["Pencahayaan yang baik, udara segar, dan atap yang kokoh", "Tidak ada jendela sama sekali, sehingga ruangan tetap gelap", "Suara bising dari jalan sepanjang pelajaran", "Kursi rusak dan atap bocor setiap minggu"], "answer": 0, "explain": "Gedung yang baik membantu anak belajar dengan nyaman dan aman.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "Apa yang bisa terjadi jika sekolah tidak punya uang untuk buku?", "options": ["Anak-anak belajar lebih cepat", "Anak-anak punya lebih sedikit kesempatan belajar", "Anak-anak tidak lagi membutuhkan sekolah", "Anak-anak mendapat liburan tambahan"], "answer": 1, "explain": "Tanpa buku, anak-anak mungkin lebih sulit belajar.", "src": "UNESCO"}, {"ch": 8, "q": "Pada tahun berapa Konvensi PBB tentang Hak-Hak Anak disepakati?", "options": ["1948", "1990", "1989", "2015"], "answer": 2, "explain": "Konvensi ini disepakati pada 1989 oleh Majelis Umum PBB.", "src": "UN Convention on the Rights of the Child, 1989"}, {"ch": 8, "q": "Apa itu Tujuan Pembangunan Milenium?", "options": ["Sekumpulan tujuan dari tahun 1900", "Sekumpulan tujuan untuk Bulan", "Sekumpulan tujuan untuk olahraga", "Sekumpulan tujuan dari 2000 hingga 2015"], "answer": 3, "explain": "MDG berlangsung dari 2000 hingga 2015, sebelum Tujuan Global.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "Pertemuan apa pada 1990 yang berfokus pada Pendidikan untuk Semua?", "options": ["Konferensi Dunia tentang Pendidikan untuk Semua di Jomtien", "Pameran dagang internasional yang digelar di New York pada tahun itu", "Festival film dunia yang digelar di Cannes pada musim panas itu", "Pertemuan dunia tentang aturan sepak bola di Brasil"], "answer": 0, "explain": "Negara-negara bertemu di Jomtien, Thailand, pada 1990 untuk berkomitmen pada pendidikan untuk semua.", "src": "UNESCO"}, {"ch": 8, "q": "Hari apa yang setiap tahun merayakan guru?", "options": ["1 Januari", "Hari Guru Sedunia, 5 Oktober", "25 Desember", "8 September"], "answer": 1, "explain": "UNESCO merayakan Hari Guru Sedunia setiap tahun pada 5 Oktober.", "src": "UNESCO"}, {"ch": 9, "q": "Apa itu anak usia dini?", "options": ["Hanya tahun-tahun remaja", "Hanya tahun-tahun kuliah", "Tahun dari lahir hingga sekitar usia delapan tahun", "Hanya tahun terakhir sekolah"], "answer": 2, "explain": "Anak usia dini biasanya merujuk pada tahun dari lahir hingga sekitar delapan tahun.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa pembelajaran sejak dini itu penting?", "options": ["Tahun-tahun awal tidak penting", "Hanya tahun-tahun berikutnya yang penting", "Pembelajaran dini hanya membantu olahraga", "Pengalaman di masa awal membentuk cara otak berkembang"], "answer": 3, "explain": "Pengalaman di masa awal membentuk cara otak tumbuh dan belajar.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa kegiatan pembelajaran dini yang baik?", "options": ["Membaca buku bergambar bersama", "Menonton TV sepanjang hari", "Membiarkan anak sendirian berjam-jam", "Hanya makan permen"], "answer": 0, "explain": "Membaca bersama membangun bahasa dan pembelajaran dini.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu pembelajaran berbasis bermain?", "options": ["Belajar dengan duduk diam", "Belajar melalui bermain", "Belajar hanya dengan menyalin", "Belajar tanpa pernah bertanya"], "answer": 1, "explain": "Pembelajaran berbasis bermain membantu anak kecil belajar dengan melakukan sesuatu.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Kapan Hari Literasi Internasional?", "options": ["1 Januari", "25 Desember", "8 September", "30 April"], "answer": 2, "explain": "UNESCO memperingati Hari Literasi Internasional setiap tahun pada 8 September.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Apa yang membantu orang dewasa belajar membaca?", "options": ["Dipaksa berhenti membaca", "Tidur lebih banyak", "Menghindari buku", "Kelas literasi untuk orang dewasa"], "answer": 3, "explain": "Kelas literasi untuk orang dewasa membantu mereka belajar membaca dan menulis.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Mengapa sebagian orang kesulitan membaca?", "options": ["Mereka tidak mendapat kesempatan untuk belajar", "Membaca itu ilegal", "Buku itu beracun", "Huruf-hurufnya terlalu besar"], "answer": 0, "explain": "Banyak orang tidak belajar membaca ketika mereka tidak mendapat kesempatan di sekolah.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Kapan Hari Bahasa Ibu Internasional?", "options": ["1 Mei", "21 Februari", "31 Oktober", "14 Juli"], "answer": 1, "explain": "UNESCO memperingati Hari Bahasa Ibu Internasional setiap 21 Februari.", "src": "UNESCO, International Mother Language Day"}, {"ch": 11, "q": "Apa yang harus dilakukan sekolah untuk anak penyandang disabilitas?", "options": ["Memisahkan mereka dari yang lain", "Menolak mereka masuk", "Menerima mereka dan memberi dukungan", "Mengirim mereka pulang"], "answer": 2, "explain": "Sekolah inklusif menerima anak penyandang disabilitas dan memberi mereka dukungan.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu akomodasi yang wajar di sekolah?", "options": ["Cara untuk menghindari mengajar", "Bus khusus ke kota", "Sejenis biaya ujian", "Penyesuaian yang membantu anak ikut serta"], "answer": 3, "explain": "Akomodasi yang wajar adalah penyesuaian yang membantu anak ikut serta di sekolah.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Manakah dari ini yang merupakan contoh inklusi?", "options": ["Buku braille di perpustakaan", "Sekolah tanpa pintu masuk", "Guru yang mengabaikan semua siswa", "Ruangan yang hanya bisa dimasuki sebagian anak"], "answer": 0, "explain": "Buku braille membantu anak tunanetra membaca di kelas.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa arti inklusif?", "options": ["Membiarkan sebagian orang di luar", "Menyambut semua orang", "Menyambut hanya satu kelompok", "Membuat orang pergi"], "answer": 1, "explain": "Inklusif berarti menyambut semua orang dan memberi ruang bagi setiap orang.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu tempat sekolah?", "options": ["Kursi di dalam mobil", "Tempat untuk tidur", "Kursi untuk seorang anak di sekolah", "Toko buku"], "answer": 2, "explain": "Tempat sekolah adalah kursi bagi anak untuk belajar.", "src": "UNESCO"}], "4": [{"ch": 0, "q": "Apa tujuan dari Tujuan 4?", "options": ["Kualitas dan pembelajaran sepanjang hayat untuk semua", "Hanya olahraga untuk anak-anak", "Hanya pekerjaan untuk orang dewasa", "Sekolah yang lebih sedikit untuk semua"], "answer": 0, "explain": "Tujuan 4 bertujuan untuk pembelajaran yang inklusif, berkualitas, dan sepanjang hayat bagi semua.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Berapa target yang dimiliki Tujuan 4?", "options": ["5", "10", "17", "169"], "answer": 1, "explain": "Tujuan 4 memiliki 10 target: tujuh target hasil dan tiga cara pelaksanaan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Berapa target di seluruh 17 Tujuan Global?", "options": ["17", "50", "169", "300"], "answer": 2, "explain": "Ke-17 Tujuan Global memiliki 169 target secara keseluruhan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Tujuan mana yang membahas tentang tanpa kemiskinan?", "options": ["Tujuan 4", "Tujuan 9", "Tujuan 12", "Tujuan 1"], "answer": 3, "explain": "Tujuan 1 adalah Tanpa Kemiskinan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Apa alasan umum mengapa anak di desa tidak bersekolah?", "options": ["Sekolahnya terlalu jauh", "Sekolahnya terlalu dekat", "Terlalu banyak bus", "Terlalu banyak teman"], "answer": 0, "explain": "Jarak yang jauh adalah hambatan umum bagi sekolah.", "src": "UNESCO"}, {"ch": 1, "q": "Mengapa beberapa keluarga menahan anak di rumah?", "options": ["Mereka tidak menginginkan pendidikan", "Mereka butuh bantuan untuk pekerjaan atau uang", "Sekolah itu ilegal", "Mereka punya terlalu banyak mobil"], "answer": 1, "explain": "Beberapa keluarga membutuhkan anak untuk membantu mencari uang atau bekerja di rumah.", "src": "UNESCO"}, {"ch": 1, "q": "Manakah dari ini yang membantu anak di daerah pedesaan mencapai sekolah?", "options": ["Menutup jalan", "Menyeberangi sungai sendirian tanpa bantuan", "Bus sekolah atau jalur yang aman", "Tinggal di rumah"], "answer": 2, "explain": "Transportasi dan jalur yang aman memudahkan anak-anak pedesaan untuk bersekolah.", "src": "UNESCO"}, {"ch": 1, "q": "Apa itu pendidikan prasekolah?", "options": ["Belajar setelah universitas", "Belajar hanya pada akhir pekan", "Belajar hanya di tempat kerja", "Belajar sebelum sekolah dasar"], "answer": 3, "explain": "Pendidikan prasekolah adalah pembelajaran untuk anak kecil sebelum sekolah dasar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Mengapa gedung sekolah yang aman itu penting?", "options": ["Melindungi anak dari bahaya", "Membuat sekolah lebih lama", "Menghentikan anak untuk belajar", "Hanya untuk hiasan"], "answer": 0, "explain": "Gedung yang aman melindungi anak dan membuat pembelajaran menjadi mungkin.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apa itu sekolah dasar?", "options": ["Tahap terakhir universitas", "Tahap utama pertama dari persekolahan", "Hanya untuk guru", "Sejenis perkemahan liburan"], "answer": 1, "explain": "Sekolah dasar biasanya merupakan tahap utama pertama pendidikan formal.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu sekolah menengah?", "options": ["Tahap sebelum taman kanak-kanak", "Sejenis perkemahan olahraga", "Tahap setelah sekolah dasar", "Tempat khusus untuk orang dewasa"], "answer": 2, "explain": "Sekolah menengah mengikuti sekolah dasar.", "src": "UNESCO"}, {"ch": 2, "q": "Faktor apa yang sering meningkatkan angka putus sekolah dini?", "options": ["Cuaca yang baik", "Terlalu banyak buku", "Memenangkan hadiah", "Kemiskinan"], "answer": 3, "explain": "Kemiskinan adalah salah satu alasan terbesar anak meninggalkan sekolah lebih awal.", "src": "UNESCO"}, {"ch": 2, "q": "Apa arti angka penyelesaian?", "options": ["Proporsi anak yang menyelesaikan satu jenjang sekolah", "Proporsi guru yang tidur", "Jumlah bel sekolah", "Harga tas sekolah"], "answer": 0, "explain": "Angka penyelesaian adalah proporsi anak yang menyelesaikan satu jenjang sekolah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apa yang membantu anak menyelesaikan sekolah?", "options": ["Menutup sekolah lebih awal", "Membantu keluarga dengan biaya dan transportasi", "Menghilangkan buku", "Memperpanjang ujian setiap hari"], "answer": 1, "explain": "Dukungan untuk biaya dan transportasi membantu anak tetap bersekolah.", "src": "UNESCO"}, {"ch": 2, "q": "Apa yang bisa dilakukan sekolah agar siswa tetap hadir?", "options": ["Mengabaikan siswa yang absen dan menunggu mereka kembali", "Memberi lebih sedikit pelajaran kepada siswa yang sering absen", "Memantau kehadiran dan menjangkau keluarga", "Menutup sekolah lebih awal setiap hari Jumat"], "answer": 2, "explain": "Sekolah dapat memantau kehadiran dan bekerja sama dengan keluarga untuk mendukung siswa.", "src": "UNESCO"}, {"ch": 3, "q": "Apa arti tingkat membaca yang baik?", "options": ["Hanya membaca angka", "Tidak pernah membaca dengan keras", "Membaca lebih cepat dari mobil", "Membaca dan memahami teks sesuai usia"], "answer": 3, "explain": "Tingkat membaca yang baik berarti memahami teks sederhana sesuai usia.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Mata pelajaran apa yang membahas angka, pola, dan bentuk?", "options": ["Matematika", "Musik", "Drama", "Sejarah seni"], "answer": 0, "explain": "Matematika adalah mata pelajaran tentang angka, pola, dan bentuk.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu kurikulum?", "options": ["Sejenis seragam sekolah", "Kumpulan mata pelajaran dan apa yang dipelajari siswa", "Tempat parkir sekolah", "Daftar hari libur"], "answer": 1, "explain": "Kurikulum memuat apa yang harus dipelajari siswa di setiap mata pelajaran.", "src": "UNESCO"}, {"ch": 3, "q": "Mengapa belajar dalam bahasa ibu itu membantu?", "options": ["Tidak pernah membantu", "Berarti belajar lebih sedikit", "Anak lebih memahami pelajaran", "Membuat sekolah lebih singkat"], "answer": 2, "explain": "Anak belajar lebih mudah ketika mereka memahami bahasa yang digunakan di kelas.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "Apa itu keterampilan dalam pendidikan?", "options": ["Sesuatu yang hilang", "Sejenis makanan", "Hanya satu mata pelajaran", "Sesuatu yang bisa dilakukan seseorang dengan baik"], "answer": 3, "explain": "Keterampilan adalah kemampuan yang bisa dilatih dan ditingkatkan.", "src": "UNESCO"}, {"ch": 4, "q": "Apa arti pemecahan masalah?", "options": ["Menemukan cara untuk menyelesaikan pertanyaan yang sulit", "Mengabaikan masalah", "Membuat masalah menjadi lebih besar", "Menunggu orang lain selamanya"], "answer": 0, "explain": "Pemecahan masalah berarti mencari cara untuk menjawab atau memperbaiki sesuatu.", "src": "UNESCO"}, {"ch": 4, "q": "Keterampilan apa yang membantumu menyampaikan ide dengan jelas kepada sebuah kelompok?", "options": ["Menyembunyikan suaramu", "Berbicara dengan jelas di depan kelompok", "Berbicara sangat pelan", "Tidak pernah berbicara"], "answer": 1, "explain": "Presentasi membantumu menyampaikan ide dengan jelas kepada orang lain.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu kepemimpinan?", "options": ["Menyuruh orang lain diam", "Mengambil semua pujian", "Membimbing orang lain dengan cara yang membantu", "Menghindari tanggung jawab"], "answer": 2, "explain": "Kepemimpinan adalah membantu dan membimbing orang lain menuju suatu tujuan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu literasi digital?", "options": ["Menggunakan teknologi untuk merusak sesuatu", "Tidak pernah menggunakan komputer", "Hanya menulis surat", "Menggunakan teknologi untuk mencari dan membagikan informasi"], "answer": 3, "explain": "Literasi digital berarti menggunakan alat digital dengan aman untuk belajar dan berkomunikasi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu keterampilan vokasi?", "options": ["Keterampilan kerja praktis seperti pertukangan", "Keterampilan untuk tidur", "Keterampilan untuk menghindari pekerjaan", "Keterampilan untuk bersembunyi"], "answer": 0, "explain": "Keterampilan vokasi adalah keterampilan praktis yang digunakan dalam pekerjaan atau profesi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa arti kesetaraan gender di sekolah?", "options": ["Hanya anak laki-laki yang bisa belajar", "Anak perempuan dan laki-laki memiliki kesempatan yang sama", "Hanya anak perempuan yang bisa belajar", "Anak perempuan harus tinggal di rumah"], "answer": 1, "explain": "Kesetaraan gender berarti anak perempuan dan laki-laki memiliki hak dan kesempatan yang sama dalam pendidikan.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Kelompok mana yang disebut Tujuan 4 untuk akses yang setara?", "options": ["Hanya orang yang tinggi", "Hanya orang kota", "Penyandang disabilitas", "Hanya orang yang suka olahraga"], "answer": 2, "explain": "Tujuan 4 menyebut penyandang disabilitas sebagai salah satu kelompok yang membutuhkan akses setara.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Mengapa anak perempuan kadang tidak masuk sekolah?", "options": ["Anak perempuan tidak suka belajar", "Sekolahnya terlalu singkat", "Anak perempuan punya terlalu banyak buku", "Pernikahan dini, pekerjaan rumah, atau perjalanan yang tidak aman"], "answer": 3, "explain": "Pernikahan dini, pekerjaan rumah tangga, dan perjalanan yang tidak aman dapat menghalangi anak perempuan untuk bersekolah.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa itu kelompok rentan dalam pendidikan?", "options": ["Kelompok yang menghadapi lebih banyak hambatan untuk belajar", "Kelompok yang tidak pernah belajar", "Kelompok yang hanya membaca", "Kelompok yang sangat kaya"], "answer": 0, "explain": "Kelompok rentan menghadapi lebih banyak rintangan sehingga mungkin membutuhkan dukungan tambahan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa itu komunitas adat?", "options": ["Sejenis gedung sekolah", "Orang pertama yang tinggal di suatu tempat", "Sejenis guru", "Sejenis tas sekolah"], "answer": 1, "explain": "Masyarakat adat adalah penduduk asli suatu wilayah, sering kali dengan bahasa dan budaya mereka sendiri.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa itu sekolah ramah anak perempuan?", "options": ["Sekolah khusus anak perempuan di kota", "Sekolah yang tidak mengizinkan anak perempuan masuk", "Sekolah dengan toilet yang aman dan tanpa pelecehan", "Sekolah yang hanya mengajarkan tari"], "answer": 2, "explain": "Sekolah ramah anak perempuan aman, memiliki fasilitas yang baik, dan guru yang menghormati siswa.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "Mengapa sekolah membutuhkan guru yang cukup?", "options": ["Guru tidak diperlukan", "Agar anak-anak berhenti belajar", "Agar sekolah bisa selesai lebih awal", "Agar setiap kelas ada yang mengajar"], "answer": 3, "explain": "Guru yang cukup berarti setiap kelas bisa diajar dengan baik.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu guru yang berkualifikasi?", "options": ["Guru yang sudah dilatih untuk mengajar", "Guru yang tidak punya pelatihan", "Guru yang hanya menceritakan lelucon", "Guru yang tidak pernah mengajar"], "answer": 0, "explain": "Guru berkualifikasi memiliki pelatihan yang dibutuhkan untuk pekerjaannya.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa yang dapat membantu guru tetap bertahan dalam pekerjaannya?", "options": ["Jam kerja panjang tanpa istirahat", "Gaji yang adil dan kondisi kerja yang baik", "Tidak ada dukungan sama sekali", "Dipindahkan jauh setiap hari"], "answer": 1, "explain": "Gaji yang adil dan kondisi kerja yang baik membantu guru tetap berada dalam profesinya.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu guru pembimbing?", "options": ["Guru yang kabur", "Guru yang hanya duduk", "Guru berpengalaman yang membantu guru yang lebih baru", "Guru yang hanya menulis puisi"], "answer": 2, "explain": "Pembimbing membimbing guru baru dan membantu mereka berkembang.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa guru perlu memahami murid mereka?", "options": ["Agar bisa memberi lebih banyak pekerjaan rumah", "Agar bisa berhenti mengajar", "Agar bisa menghindari orang tua", "Agar bisa mengajar dengan cara yang membantu setiap anak"], "answer": 3, "explain": "Memahami murid membantu guru merencanakan pelajaran yang sesuai untuk mereka.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Apa itu sekolah negeri?", "options": ["Sekolah yang dibiayai dengan uang pemerintah", "Sekolah yang hanya menjual makanan", "Sekolah yang dikelola oleh satu keluarga saja", "Sekolah tanpa murid"], "answer": 0, "explain": "Sekolah negeri terutama dibiayai oleh dana publik.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu anggaran pendidikan?", "options": ["Daftar tanggal libur", "Uang yang direncanakan untuk pendidikan", "Permainan tentang uang", "Harga seragam sekolah"], "answer": 1, "explain": "Anggaran pendidikan adalah uang yang direncanakan pemerintah untuk dibelanjakan di sekolah.", "src": "UNESCO"}, {"ch": 7, "q": "Apa yang bisa terjadi ketika sebuah sekolah kekurangan uang?", "options": ["Lebih banyak guru muncul", "Buku menjadi lebih murah", "Lebih sedikit guru dan lebih sedikit buku", "Sekolah menjadi lebih besar"], "answer": 2, "explain": "Uang yang terbatas bisa berarti lebih sedikit guru dan bahan belajar.", "src": "UNESCO"}, {"ch": 7, "q": "Biaya apa yang masih bisa ditanggung keluarga meskipun biaya sekolah gratis?", "options": ["Tidak ada sama sekali", "Hanya udara", "Hanya sinar matahari", "Seragam, transportasi, dan perlengkapan"], "answer": 3, "explain": "Keluarga tetap bisa membayar seragam, transportasi, dan perlengkapan sekolah meskipun biaya sekolah gratis.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu beasiswa sekolah?", "options": ["Uang yang diberikan untuk membantu sekolah atau siswa", "Denda untuk pekerjaan rumah yang terlambat", "Sejenis ujian", "Hanya tiket bus sekolah"], "answer": 0, "explain": "Beasiswa adalah uang yang diberikan untuk membantu sekolah atau siswa, sering kali tanpa harus dikembalikan.", "src": "UNESCO"}, {"ch": 8, "q": "Tahun berapa Tujuan Pembangunan Milenium dimulai?", "options": ["1948", "2000", "1990", "2015"], "answer": 1, "explain": "MDG dimulai pada tahun 2000.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "Di mana negara-negara bertemu pada 1990 untuk memulai gerakan Pendidikan untuk Semua?", "options": ["Paris, Prancis", "Kairo, Mesir", "Jomtien, Thailand", "Tokyo, Jepang"], "answer": 2, "explain": "Negara-negara bertemu di Jomtien, Thailand, pada 1990 untuk Pendidikan untuk Semua.", "src": "UNESCO"}, {"ch": 8, "q": "Kerangka kerja apa yang menetapkan tujuan pendidikan di Dakar pada 2000?", "options": ["Aturan Sepak Bola Dakar", "Peta Jalan Dakar", "Rencana Pangan Dakar", "Kerangka Aksi Dakar"], "answer": 3, "explain": "Kerangka Aksi Dakar disepakati pada 2000 di Forum Pendidikan Dunia.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Dokumen mana yang menyatakan bahwa pendidikan dasar harus wajib dan gratis?", "options": ["Konvensi PBB tentang Hak-Hak Anak", "Menu sekolah yang mencantumkan pilihan makan siang untuk seminggu", "Panduan wisata pantai terbaik di Bali", "Aturan olahraga untuk pertandingan sepak bola sekolah"], "answer": 0, "explain": "Pasal 28 menyatakan bahwa pendidikan dasar harus wajib dan gratis bagi semua.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "Apa nama kesepakatan pendidikan tahun 2015?", "options": ["Deklarasi Tokyo", "Deklarasi Incheon", "Pakta Kairo", "Rencana Lima"], "answer": 1, "explain": "Deklarasi Incheon pada 2015 menetapkan tujuan pendidikan untuk 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 9, "q": "Bagaimana anak kecil sering belajar?", "options": ["Melalui ujian panjang", "Melalui berjam-jam dalam keheningan", "Melalui bermain, lagu, dan cerita", "Melalui shift malam"], "answer": 2, "explain": "Pembelajaran dini sering terjadi melalui bermain, lagu, dan cerita.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa tahun-tahun pertama kehidupan penting bagi otak?", "options": ["Otak berhenti tumbuh", "Otak tidak berubah", "Otak hanya tumbuh pada malam hari", "Otak tumbuh sangat cepat"], "answer": 3, "explain": "Otak berkembang sangat cepat pada tahun-tahun awal.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa saja yang termasuk dalam perawatan anak usia dini?", "options": ["Kesehatan, gizi, dan pembelajaran", "Hanya tidur", "Hanya olahraga", "Hanya uang"], "answer": 0, "explain": "Perawatan anak usia dini mendukung kesehatan, makanan, dan pembelajaran secara bersamaan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Apa itu tempat penitipan anak?", "options": ["Tempat khusus menanam pohon", "Tempat untuk merawat anak yang sangat kecil", "Tempat untuk mengirim surat", "Tempat untuk membuat mobil"], "answer": 1, "explain": "Tempat penitipan anak merawat anak yang sangat kecil dan membantu mereka belajar.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Aktivitas apa yang membantu balita belajar kata-kata?", "options": ["Diam sepanjang hari", "Hanya menonton iklan", "Menyebutkan nama benda dan berbicara dengannya", "Dikurung di ruangan gelap"], "answer": 2, "explain": "Berbicara dan menyebutkan nama benda membantu balita membangun bahasa.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Apa itu angka melek huruf?", "options": ["Harga buku", "Jumlah perpustakaan", "Jumlah guru", "Proporsi orang yang bisa membaca dan menulis"], "answer": 3, "explain": "Angka melek huruf menunjukkan proporsi orang yang bisa membaca dan menulis.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Mengapa orang dewasa perlu melek huruf?", "options": ["Untuk membaca petunjuk kerja dan informasi kesehatan", "Untuk tidak bekerja sama sekali di pabrik", "Untuk memenangkan semua pertandingan di kompetisi sekolah", "Untuk berhenti belajar hal baru setelah sekolah"], "answer": 0, "explain": "Membaca membantu orang dewasa bekerja, tetap sehat, dan berpartisipasi dalam kehidupan.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Apa itu pojok baca di kelas?", "options": ["Tempat untuk menyimpan sepatu", "Ruang dengan buku untuk dibaca", "Tempat khusus untuk makan siang", "Tempat untuk menyimpan sepeda"], "answer": 1, "explain": "Pojok baca memberi anak tempat untuk membaca dan menikmati buku.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Apa yang membantu anak yang kesulitan membaca?", "options": ["Lebih sedikit waktu membaca", "Diberitahu bahwa mereka tidak pintar", "Bantuan dan latihan membaca tambahan", "Tidak pernah diberi buku"], "answer": 2, "explain": "Bantuan dan latihan tambahan dapat membantu anak mengejar ketertinggalan.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "Apa arti pendidikan inklusif?", "options": ["Pendidikan hanya untuk siswa terbaik", "Pendidikan hanya untuk satu kelompok", "Pendidikan tanpa guru", "Pendidikan yang menyambut semua peserta didik"], "answer": 3, "explain": "Pendidikan inklusif menyambut dan mendukung semua peserta didik.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Mengapa sekolah harus memiliki jalur landai dan toilet yang mudah diakses?", "options": ["Agar semua orang dapat menggunakan sekolah", "Agar anak-anak bisa berlari lebih cepat", "Agar sekolah terlihat lebih tinggi", "Agar kelas menjadi lebih pendek"], "answer": 0, "explain": "Gedung yang mudah diakses memungkinkan semua orang menggunakan fasilitas sekolah.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Untuk apa bahasa isyarat digunakan di sekolah?", "options": ["Hanya untuk menari", "Berkomunikasi dengan siswa tuli", "Hanya untuk memasak", "Hanya untuk ujian matematika"], "answer": 1, "explain": "Bahasa isyarat membantu siswa tuli berkomunikasi dan belajar.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Siapa yang diuntungkan dari sekolah inklusif?", "options": ["Hanya guru", "Hanya orang tua", "Semua orang di sekolah", "Hanya kepala sekolah"], "answer": 2, "explain": "Sekolah inklusif membantu setiap anak belajar dan tumbuh bersama.", "src": "UN CRPD (2006), Article 24"}, {"ch": 3, "q": "Apa itu rencana pembelajaran?", "options": ["Rencana liburan keluarga di musim panas", "Daftar camilan yang dijual di kantin sekolah", "Peta yang menunjukkan ruangan dan koridor sekolah", "Rencana yang menunjukkan apa yang akan diajarkan dan caranya"], "answer": 3, "explain": "Rencana pembelajaran menetapkan tujuan dan langkah-langkah untuk sebuah pelajaran.", "src": "UNESCO Global Report on Teachers (2024)"}], "5": [{"ch": 0, "q": "Ada berapa target hasil di bawah Tujuan 4?", "options": ["Tujuh", "Tiga", "Sepuluh", "Tujuh belas"], "answer": 0, "explain": "Tujuan 4 memiliki tujuh target hasil, bernomor 4.1 hingga 4.7.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa nama tiga target \"cara pelaksanaan\" untuk Tujuan 4?", "options": ["4.1, 4.2, dan 4.3", "4.a, 4.b, dan 4.c", "4.5, 4.6, dan 4.7", "4.8, 4.9, dan 4.10"], "answer": 1, "explain": "Target 4.a, 4.b, dan 4.c mencakup fasilitas, beasiswa, dan guru.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Tujuan Global mana yang berisi Kesetaraan Gender?", "options": ["Tujuan 2", "Tujuan 8", "Tujuan 5", "Tujuan 11"], "answer": 2, "explain": "Tujuan 5 adalah Kesetaraan Gender.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa arti tidak meninggalkan siapa pun?", "options": ["Meninggalkan orang yang paling lambat", "Hanya membantu negara kaya", "Mengakhiri semua bantuan", "Mencakup orang-orang yang paling terpinggirkan"], "answer": 3, "explain": "Agenda 2030 berjanji untuk menjangkau yang paling tertinggal terlebih dahulu.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Mengapa Tujuan Global disebut global?", "options": ["Berlaku untuk semua negara", "Hanya untuk satu negara", "Hanya untuk sekolah", "Hanya untuk olahraga"], "answer": 0, "explain": "Tujuan Global berlaku untuk setiap negara, kaya maupun miskin.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa tahun target Tujuan Global?", "options": ["2015", "2030", "2050", "2100"], "answer": 1, "explain": "Tujuan Global ditargetkan tercapai pada 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Kelompok mana yang paling mungkin tidak bersekolah di banyak negara?", "options": ["Anak-anak yang suka membaca", "Anak-anak yang bermain sepak bola", "Anak-anak di daerah konflik", "Anak-anak yang sering ke perpustakaan"], "answer": 2, "explain": "Anak-anak di daerah konflik dan krisis sering kali paling sulit untuk bersekolah.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa arti tidak bersekolah?", "options": ["Belajar di perpustakaan", "Pergi ke sekolah pada hari Minggu", "Memenangkan hadiah sekolah", "Tidak terdaftar di sekolah mana pun"], "answer": 3, "explain": "Anak yang tidak bersekolah adalah mereka yang tidak terdaftar di sekolah mana pun.", "src": "UNESCO"}, {"ch": 1, "q": "Mengapa banyak anak bekerja daripada bersekolah?", "options": ["Keluarga membutuhkan penghasilan mereka", "Mereka lebih suka bekerja", "Sekolah itu gratis", "Pekerjaan diajarkan di sekolah"], "answer": 0, "explain": "Keluarga miskin mungkin membutuhkan anak untuk bekerja demi mendapatkan uang.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa itu pekerja anak?", "options": ["Bermain tenang di rumah bersama teman setelah jam sekolah", "Pekerjaan yang membahayakan kesehatan anak atau menghentikan sekolah mereka", "Membantu orang tua mengerjakan PR dan pekerjaan rumah yang ringan", "Membacakan cerita dengan keras untuk adik laki-laki atau perempuan"], "answer": 1, "explain": "Pekerja anak adalah pekerjaan yang membahayakan anak dan menghentikan mereka belajar.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa itu program pemberian makanan sekolah?", "options": ["Makanan yang dijual di toko", "Sejenis olahraga sekolah", "Makanan yang diberikan kepada anak di sekolah", "Festival makanan"], "answer": 2, "explain": "Makan siang di sekolah dapat mendorong anak untuk hadir dan belajar.", "src": "UNESCO"}, {"ch": 1, "q": "Mengapa makanan sekolah dapat membantu anak?", "options": ["Membuat mereka berhenti belajar", "Mengambil semua uang", "Menggantikan buku", "Mendorong anak untuk hadir"], "answer": 3, "explain": "Makanan dapat memudahkan anak untuk datang ke sekolah dan berkonsentrasi.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu transisi dari SD ke SMP?", "options": ["Pindah dari satu jenjang sekolah ke jenjang berikutnya", "Hanya pindah rumah", "Mengganti tempat duduk di kelas yang sama", "Berhenti sekolah selamanya"], "answer": 0, "explain": "Transisi berarti berpindah dari satu tahap sekolah ke tahap berikutnya.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa sebagian anak tinggal kelas?", "options": ["Tinggal kelas selalu seperti liburan", "Mereka membutuhkan lebih banyak waktu untuk memahami pelajaran", "Tinggal kelas adalah hadiah", "Mereka punya terlalu banyak teman"], "answer": 1, "explain": "Sebagian anak tinggal kelas ketika mereka membutuhkan lebih banyak waktu untuk belajar.", "src": "UNESCO"}, {"ch": 2, "q": "Apa arti lulus?", "options": ["Memulai sekolah baru", "Pindah ke negara lain", "Menyelesaikan satu jenjang pendidikan", "Berhenti menghadiri kelas"], "answer": 2, "explain": "Lulus berarti berhasil menyelesaikan satu jenjang studi.", "src": "UNESCO"}, {"ch": 2, "q": "Apa tujuan menyelesaikan sekolah menengah?", "options": ["Hanya untuk mendapatkan liburan", "Hanya untuk melewatkan ujian", "Hanya untuk berhenti membaca", "Keterampilan untuk bekerja dan studi lanjut"], "answer": 3, "explain": "Pendidikan menengah membangun keterampilan untuk bekerja dan studi lanjut.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apa arti retensi di sekolah?", "options": ["Menjaga siswa tetap bersekolah hingga mereka lulus", "Mengurung siswa di dalam kotak", "Menyimpan buku selamanya", "Membuat sekolah tetap tutup"], "answer": 0, "explain": "Retensi berarti siswa tetap bersekolah sampai mereka menyelesaikan jenjang tersebut.", "src": "UNESCO"}, {"ch": 2, "q": "Faktor apa yang membantu siswa tetap bersekolah?", "options": ["Dipaksa keluar dari sekolah", "Jalur yang aman menuju sekolah", "Tidak punya buku", "Melewatkan setiap ujian"], "answer": 1, "explain": "Jalur yang aman memudahkan anak untuk tetap bersekolah.", "src": "UNESCO"}, {"ch": 3, "q": "Apa arti penilaian pembelajaran?", "options": ["Mengukur gedung sekolah", "Menghitung meja", "Mengukur apa yang sudah dipelajari siswa", "Menghitung mobil guru"], "answer": 2, "explain": "Penilaian pembelajaran memeriksa apa yang siswa ketahui dan mampu lakukan.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu kemiskinan belajar?", "options": ["Tidak punya pensil atau buku catatan untuk tugas kelas", "Tidak punya komputer di rumah untuk mengerjakan PR", "Tinggal jauh dari gedung perpustakaan terdekat", "Tidak mampu membaca teks sederhana pada usia sepuluh tahun"], "answer": 3, "explain": "Kemiskinan belajar berarti seorang anak tidak dapat membaca dan memahami teks sederhana pada usia sepuluh tahun.", "src": "World Bank, learning poverty"}, {"ch": 3, "q": "Apa itu keterampilan dasar?", "options": ["Keterampilan dasar seperti membaca atau berhitung", "Mata pelajaran kuliah yang sulit", "Sejenis olahraga", "Sejenis musik"], "answer": 0, "explain": "Keterampilan dasar seperti membaca dan berhitung mendukung semua pembelajaran berikutnya.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Mengapa membaca sejak dini itu penting?", "options": ["Hanya membantu dalam seni", "Mendukung pembelajaran di setiap mata pelajaran", "Tidak diperlukan di sekolah", "Hanya membantu dalam olahraga"], "answer": 1, "explain": "Anak yang pandai membaca dapat belajar lebih mudah di setiap mata pelajaran.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu penilaian formatif?", "options": ["Hanya ujian akhir", "Tes untuk mengukur tinggi badan siswa", "Memeriksa pembelajaran selama pelajaran", "Tes keterampilan memasak"], "answer": 2, "explain": "Penilaian formatif membantu guru memeriksa kemajuan dan menyesuaikan pelajaran.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu penilaian sumatif?", "options": ["Pertanyaan yang hanya diajukan di awal", "Permainan tanpa nilai", "Tes yang diberikan setiap pagi", "Tes di akhir satu unit atau tahun"], "answer": 3, "explain": "Penilaian sumatif mengukur pembelajaran di akhir suatu periode.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "Apa itu kreativitas dalam belajar?", "options": ["Menemukan ide baru yang berguna", "Menyalin persis", "Hanya menggunakan ide lama", "Menghindari semua ide"], "answer": 0, "explain": "Kreativitas berarti menemukan cara berpikir dan berbuat yang baru dan berguna.", "src": "UNESCO"}, {"ch": 4, "q": "Keterampilan apa yang membantumu bekerja dengan orang dari budaya yang berbeda?", "options": ["Bersembunyi dari perbedaan", "Pemahaman antarbudaya", "Menolak berbicara", "Mengabaikan bahasa lain"], "answer": 1, "explain": "Pemahaman antarbudaya membantu orang menghargai dan bekerja dengan orang lain.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu ketahanan (resiliensi)?", "options": ["Menyerah pada tantangan pertama", "Tidak pernah menghadapi masalah", "Bangkit kembali setelah kesulitan", "Menghindari semua hal baru"], "answer": 2, "explain": "Ketahanan berarti pulih dan belajar dari saat-saat sulit.", "src": "UNESCO"}, {"ch": 4, "q": "Mengapa keterampilan hidup diajarkan di beberapa sekolah?", "options": ["Untuk mengganti semua pelajaran matematika dengan kelas seni", "Untuk memperpanjang hari sekolah bagi semua orang", "Untuk menghapus semua ujian dalam tahun ajaran", "Untuk membantu siswa menghadapi tantangan sehari-hari"], "answer": 3, "explain": "Keterampilan hidup membantu siswa membuat keputusan yang baik dan mengatasi masalah sehari-hari.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu literasi keuangan?", "options": ["Memahami uang dan cara mengelolanya", "Mengumpulkan koin hanya untuk bersenang-senang", "Mengabaikan harga", "Menghabiskan semua uang sekaligus"], "answer": 0, "explain": "Literasi keuangan berarti tahu cara menggunakan dan menabung uang dengan bijak.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Keterampilan apa yang membantumu menggunakan informasi dari banyak sumber?", "options": ["Bernyanyi", "Keterampilan riset", "Bermain akrobat", "Hanya berkebun"], "answer": 1, "explain": "Keterampilan riset membantu siswa menemukan dan memeriksa informasi.", "src": "UNESCO"}, {"ch": 5, "q": "Apa itu indeks paritas gender?", "options": ["Ukuran tinggi sekolah", "Hitungan hewan peliharaan guru", "Angka yang membandingkan pendaftaran anak perempuan dan laki-laki", "Daftar warna sekolah"], "answer": 2, "explain": "Indeks paritas mendekati 1 berarti anak perempuan dan laki-laki terdaftar secara setara.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa arti indeks paritas 1?", "options": ["Tidak ada anak perempuan di sekolah", "Hanya anak perempuan di sekolah", "Ada dua kali lebih banyak anak laki-laki", "Jumlah anak perempuan dan laki-laki yang sama"], "answer": 3, "explain": "Nilai 1 menunjukkan anak perempuan dan laki-laki terdaftar dalam jumlah yang sama.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Kelompok mana yang mungkin menghadapi hambatan tambahan karena disabilitas?", "options": ["Anak penyandang disabilitas", "Anak yang suka menggambar", "Anak yang bermain game", "Anak yang memakai kacamata"], "answer": 0, "explain": "Anak penyandang disabilitas mungkin menghadapi hambatan tambahan tanpa dukungan.", "src": "UN CRPD (2006), Article 24"}, {"ch": 5, "q": "Apa itu diskriminasi di sekolah?", "options": ["Perlakuan adil untuk semua orang", "Perlakuan tidak adil karena siapa seseorang", "Memilih buku berdasarkan warna", "Memberikan PR yang sama kepada semua orang"], "answer": 1, "explain": "Diskriminasi adalah perlakuan tidak adil berdasarkan kelompok atau latar belakang seseorang.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Mengapa sekolah harus bebas dari kekerasan?", "options": ["Kekerasan membantu anak fokus", "Kekerasan adalah bagian normal dari sekolah", "Kekerasan menghentikan anak untuk belajar", "Kekerasan membuat anak lebih kuat"], "answer": 2, "explain": "Anak tidak dapat belajar dengan baik ketika mereka merasa tidak aman.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa yang dilakukan kebijakan inklusif?", "options": ["Menutup sekolah untuk kelompok tertentu", "Membuat sekolah hanya untuk orang kaya", "Menghapus semua guru", "Membuat pendidikan terbuka untuk semua kelompok"], "answer": 3, "explain": "Kebijakan inklusif membantu semua kelompok mengakses dan memperoleh manfaat dari pendidikan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Apa itu rasio guru-murid?", "options": ["Berapa banyak murid yang diajar setiap guru", "Berapa banyak guru yang digaji", "Berapa banyak meja di dalam ruangan", "Berapa banyak sekolah yang dikunjungi seorang guru"], "answer": 0, "explain": "Rasio guru-murid menunjukkan berapa banyak pelajar berbagi satu guru.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa rasio guru-murid yang rendah itu penting?", "options": ["Guru tidak punya pekerjaan", "Guru bisa memberi perhatian lebih kepada setiap anak", "Artinya kelas lebih berisik", "Membuat guru lebih kaya"], "answer": 1, "explain": "Kelas yang lebih kecil memungkinkan guru membantu setiap anak dengan lebih baik.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu motivasi guru?", "options": ["Dibayar untuk tidur", "Bekerja sesedikit mungkin", "Dorongan dan semangat untuk mengajar dengan baik", "Menghindari murid"], "answer": 2, "explain": "Guru yang termotivasi lebih cenderung bertahan dan mengajar dengan baik.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa pelatihan guru itu penting?", "options": ["Menggantikan pelajaran", "Menghilangkan kebutuhan akan murid", "Hanya menambah hari libur", "Meningkatkan kualitas pengajaran"], "answer": 3, "explain": "Pelatihan yang baik membantu guru mengajar dengan cara yang efektif.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu perguruan tinggi pendidikan guru?", "options": ["Tempat guru dilatih", "Tempat untuk menjual bahan ajar saja", "Sekolah untuk hewan peliharaan", "Tempat untuk membangun jalan"], "answer": 0, "explain": "Perguruan tinggi pendidikan guru mempersiapkan orang untuk menjadi guru.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa yang dapat mendukung guru di daerah pedesaan?", "options": ["Tidak ada dukungan sama sekali", "Perumahan, transportasi, dan pelatihan", "Dipindahkan setiap hari", "Gaji lebih kecil dan kerja lebih banyak"], "answer": 1, "explain": "Dukungan seperti perumahan dan transportasi membantu guru melayani masyarakat pedesaan.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Apa itu belanja publik untuk pendidikan?", "options": ["Uang yang dibelanjakan keluarga untuk mainan", "Uang yang dibelanjakan hanya untuk olahraga", "Uang yang dibelanjakan pemerintah untuk sekolah", "Uang yang dibelanjakan hanya untuk jalan"], "answer": 2, "explain": "Belanja publik untuk pendidikan adalah uang yang digunakan pemerintah untuk menjalankan sekolah.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu voucher sekolah?", "options": ["Sejenis seragam sekolah", "Tiket ke museum", "Peta rute bus", "Bentuk bantuan yang membayar biaya sekolah"], "answer": 3, "explain": "Voucher dapat membantu keluarga membayar biaya sekolah di beberapa negara.", "src": "UNESCO"}, {"ch": 7, "q": "Biaya apa yang bisa membuat anak miskin tidak bersekolah?", "options": ["Biaya sekolah dan seragam", "Buku gratis", "Makanan gratis", "Transportasi gratis"], "answer": 0, "explain": "Biaya sekolah dan seragam bisa terlalu mahal bagi sebagian keluarga.", "src": "UNESCO"}, {"ch": 7, "q": "Apa arti pendidikan gratis biasanya?", "options": ["Liburan gratis", "Tidak ada biaya sekolah", "Mobil gratis", "Permen gratis"], "answer": 1, "explain": "Pendidikan gratis biasanya berarti tidak ada biaya sekolah, meskipun biaya lain mungkin tetap berlaku.", "src": "UNESCO"}, {"ch": 8, "q": "Tahun berapa Pendidikan untuk Semua disepakati di Jomtien?", "options": ["1948", "1989", "1990", "2000"], "answer": 2, "explain": "Pendidikan untuk Semua disepakati di Jomtien pada 1990.", "src": "UNESCO"}, {"ch": 8, "q": "Apa tujuan Kerangka Dakar pada 2000?", "options": ["Pendidikan hanya untuk orang dewasa", "Tidak ada sekolah sama sekali", "Pendidikan hanya di kota", "Pendidikan untuk Semua pada 2015"], "answer": 3, "explain": "Kerangka Dakar menetapkan tujuan untuk mencapai Pendidikan untuk Semua pada 2015.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Tujuan Pembangunan Milenium mana yang membahas pendidikan dasar universal?", "options": ["Tujuan 2", "Tujuan 1", "Tujuan 5", "Tujuan 8"], "answer": 0, "explain": "MDG 2 bertujuan mencapai pendidikan dasar universal.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "Apa itu Forum Pendidikan Dunia?", "options": ["Pertandingan sepak bola antara dua tim nasional di Asia", "Pertemuan negara-negara dan mitra tentang pendidikan", "Kompetisi memasak untuk siswa dan keluarga", "Festival film untuk sutradara dan aktor muda"], "answer": 1, "explain": "Forum Pendidikan Dunia mempertemukan negara-negara dan mitra untuk membahas pendidikan.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Kerangka kerja apa yang mendukung Deklarasi Incheon?", "options": ["Kerangka Olahraga 2030", "Rencana Memasak 2030", "Kerangka Aksi Pendidikan 2030", "Rencana Musik 2030"], "answer": 2, "explain": "Kerangka Aksi Pendidikan 2030 memandu negara-negara untuk mencapai TPB 4.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "Tahun berapa Tujuan Pembangunan Milenium berakhir?", "options": ["2000", "2030", "2010", "2015"], "answer": 3, "explain": "MDG berakhir pada 2015 dan digantikan oleh Tujuan Global.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "Apa itu perkembangan anak usia dini?", "options": ["Pertumbuhan dalam kesehatan, pembelajaran, dan kesejahteraan sejak lahir", "Pertumbuhan tinggi dan berat badan saja, tahun demi tahun", "Belajar hanya di universitas setelah bertahun-tahun", "Hanya bermain di luar ruangan setiap hari"], "answer": 0, "explain": "Perkembangan anak usia dini mencakup kesehatan, pembelajaran, dan kesejahteraan sejak lahir.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu \"serve and return\" pada anak usia dini?", "options": ["Sejenis permainan tenis di lapangan rumput saat musim panas", "Interaksi bolak-balik antara anak dan orang dewasa", "Cara mengembalikan mainan ke toko amal setempat", "Sejenis tidur panjang yang dialami bayi setiap sore"], "answer": 1, "explain": "Serve and return adalah interaksi bolak-balik yang membangun otak.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa anak kecil membutuhkan orang dewasa yang responsif?", "options": ["Orang dewasa tidak diperlukan", "Orang dewasa hanya memberi perintah", "Mereka belajar bahasa dan emosi dari orang dewasa", "Orang dewasa harus diam"], "answer": 2, "explain": "Orang dewasa yang responsif membantu anak membangun bahasa, perasaan, dan kemampuan berpikir.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Target TPB 4 mana yang membahas tentang anak usia dini?", "options": ["Target 4.1", "Target 4.6", "Target 4.c", "Target 4.2"], "answer": 3, "explain": "Target 4.2 membahas perkembangan, perawatan, dan pendidikan prasekolah anak usia dini.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Untuk apa pendidikan prasekolah?", "options": ["Mempersiapkan anak kecil untuk sekolah dasar", "Mempersiapkan mereka untuk universitas", "Menggantikan sekolah dasar", "Membuat anak bekerja"], "answer": 0, "explain": "Pendidikan prasekolah memberi anak kecil keterampilan sebelum sekolah dasar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Mengapa gizi penting pada anak usia dini?", "options": ["Makanan tidak memengaruhi otak", "Makanan yang baik mendukung pertumbuhan otak yang sehat", "Anak hanya butuh permen", "Anak hanya boleh makan seminggu sekali"], "answer": 1, "explain": "Makanan sehat mendukung otak dan tubuh selama masa pertumbuhan yang pesat.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "Apa itu literasi fungsional?", "options": ["Hanya membaca majalah dan komik untuk bersenang-senang", "Hanya menulis puisi dan lagu untuk pertunjukan sekolah", "Membaca dan menulis cukup baik untuk kehidupan sehari-hari", "Hanya membaca angka yang tercetak di tagihan dan tiket"], "answer": 2, "explain": "Literasi fungsional berarti membaca dan menulis cukup untuk menyelesaikan tugas sehari-hari.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Dua keterampilan dasar apa yang menjadi inti Target 4.6?", "options": ["Bernyanyi dan menggambar", "Memasak dan mengemudi", "Berjalan dan berlari", "Literasi dan numerasi"], "answer": 3, "explain": "Target 4.6 membahas tentang pemuda dan orang dewasa yang mencapai literasi dan numerasi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "Mengapa perpustakaan membantu literasi?", "options": ["Memberi akses gratis ke buku", "Hanya menjual buku mahal", "Tertutup bagi anak-anak", "Hanya menyimpan perabot"], "answer": 0, "explain": "Perpustakaan memberi orang akses gratis ke buku dan tempat membaca.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Apa itu kelancaran membaca?", "options": ["Membaca tanpa memahami", "Membaca dengan lancar dan akurat", "Membaca terbalik", "Membaca hanya dalam hati"], "answer": 1, "explain": "Kelancaran berarti membaca dengan lancar, akurat, dan ekspresif.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "Apa itu ruang sumber di sekolah?", "options": ["Ruangan yang hanya menyimpan perabot lama", "Ruangan yang menjual seragam sekolah", "Ruangan yang memberi bantuan tambahan kepada siswa yang membutuhkan", "Ruangan yang menyimpan piala olahraga"], "answer": 2, "explain": "Ruang sumber memberi dukungan ekstra kepada siswa dengan kebutuhan belajar atau disabilitas.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa arti desain universal untuk sekolah?", "options": ["Hanya satu jenis gedung untuk sebuah kota", "Gedung tanpa pintu", "Gedung khusus untuk hewan", "Gedung dan alat yang berfungsi untuk semua orang"], "answer": 3, "explain": "Desain universal membuat gedung dan alat dapat digunakan oleh sebanyak mungkin orang.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Mengapa anak penyandang disabilitas kadang membutuhkan alat bantu?", "options": ["Membantu anak mendengar, melihat, atau bergerak", "Membuat anak tertidur", "Menggantikan guru", "Menghentikan anak untuk belajar"], "answer": 0, "explain": "Alat bantu seperti alat bantu dengar atau kursi roda membantu anak berpartisipasi di sekolah.", "src": "UN CRPD (2006), Article 24"}], "6": [{"ch": 0, "q": "Target SDG 4 manakah yang membahas pendidikan dasar dan menengah yang gratis, setara, dan berkualitas?", "options": ["Target 4.1", "Target 4.2", "Target 4.4", "Target 4.7"], "answer": 0, "explain": "Target 4.1 bertujuan memberikan pendidikan dasar dan menengah yang gratis, setara, dan berkualitas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Target manakah yang menyebutkan keterampilan teknis dan vokasi untuk pekerjaan?", "options": ["Target 4.1", "Target 4.4", "Target 4.5", "Target 4.b"], "answer": 1, "explain": "Target 4.4 berfokus pada keterampilan, termasuk keterampilan teknis dan vokasi, untuk pekerjaan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Target manakah yang membahas beasiswa untuk pelajar dari negara berkembang?", "options": ["Target 4.a", "Target 4.c", "Target 4.b", "Target 4.6"], "answer": 2, "explain": "Target 4.b menyerukan lebih banyak beasiswa bagi pelajar dari negara berkembang.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Target manakah yang membahas ketersediaan guru yang berkualifikasi?", "options": ["Target 4.b", "Target 4.2", "Target 4.7", "Target 4.c"], "answer": 3, "explain": "Target 4.c bertujuan meningkatkan ketersediaan guru yang berkualifikasi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Target manakah yang membahas pembangunan dan peningkatan fasilitas pendidikan?", "options": ["Target 4.a", "Target 4.1", "Target 4.3", "Target 4.5"], "answer": 0, "explain": "Target 4.a menyerukan fasilitas belajar yang aman, inklusif, dan efektif.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa isi Target 4.7?", "options": ["Hanya olahraga, permainan, dan kebugaran jasmani sepanjang tahun ajaran", "Pengetahuan dan keterampilan untuk pembangunan berkelanjutan dan kewarganegaraan global", "Hanya uang, perbankan, dan rekening bisnis untuk orang dewasa", "Hanya memasak, makanan, dan gizi untuk ruang makan sekolah"], "answer": 1, "explain": "Target 4.7 mencakup pembangunan berkelanjutan, hak asasi manusia, kesetaraan gender, dan kewarganegaraan global.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Target manakah yang berfokus pada perkembangan anak usia dini dan pendidikan prasekolah?", "options": ["Target 4.1", "Target 4.6", "Target 4.2", "Target 4.c"], "answer": 2, "explain": "Target 4.2 membahas perkembangan anak usia dini, pengasuhan, dan pendidikan prasekolah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Apa arti setara dalam Target 4.1?", "options": ["Hanya untuk keluarga terkaya di negara itu", "Hanya untuk mereka yang tinggal di kota besar", "Hanya untuk orang dewasa yang sudah selesai sekolah", "Adil bagi semua orang, termasuk mereka yang paling dirugikan"], "answer": 3, "explain": "Pendidikan yang setara menjangkau semua orang secara adil, termasuk mereka yang dirugikan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Kelompok mana yang disebut dalam Target 4.5 sebagai pihak yang membutuhkan akses setara?", "options": ["Masyarakat adat", "Hanya orang yang punya uang", "Hanya orang di kota besar", "Hanya orang yang berbicara satu bahasa"], "answer": 0, "explain": "Target 4.5 menyebut penyandang disabilitas, masyarakat adat, dan anak-anak dalam situasi rentan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Mengapa pendidikan dasar gratis itu penting?", "options": ["Menaikkan biaya sekolah", "Menghilangkan hambatan besar bagi keluarga miskin", "Membuat anak-anak berhenti belajar", "Membuat sekolah kurang bermanfaat"], "answer": 1, "explain": "Pendidikan dasar gratis membantu keluarga yang tidak mampu membayar biaya.", "src": "UNESCO"}, {"ch": 1, "q": "Apa arti pendidikan dasar universal?", "options": ["Hanya sebagian anak yang bersekolah di sekolah dasar", "Hanya orang dewasa yang bersekolah di sekolah dasar", "Setiap anak dapat bersekolah di sekolah dasar", "Sekolah dasar bersifat opsional bagi semua orang"], "answer": 2, "explain": "Pendidikan dasar universal berarti setiap anak memiliki tempat di sekolah dasar.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 1, "q": "Anak mana yang masih bisa tidak bersekolah meskipun biaya dihapus?", "options": ["Anak yang sangat tinggi", "Anak yang suka membaca", "Anak yang tidak pernah makan", "Anak dengan disabilitas atau yang tinggal di daerah terpencil"], "answer": 3, "explain": "Biaya bukan satu-satunya hambatan; disabilitas, jarak, dan diskriminasi juga membuat anak tidak bersekolah.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Apa tujuan memantau angka penyelesaian sekolah?", "options": ["Untuk melihat apakah anak-anak menyelesaikan sekolah", "Untuk memilih tempat liburan terbaik untuk karyawisata sekolah", "Untuk menjual lebih banyak buku sekolah di toko setempat", "Untuk mengukur ukuran meja di setiap kelas"], "answer": 0, "explain": "Angka penyelesaian menunjukkan apakah anak mencapai akhir setiap jenjang.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Mengapa angka penyelesaian pendidikan menengah penting?", "options": ["Menunjukkan berapa banyak guru yang tidur", "Menunjukkan kemajuan menuju Target 4.1", "Menunjukkan harga tas sekolah", "Menunjukkan cuaca"], "answer": 1, "explain": "Angka penyelesaian membantu melacak kemajuan menuju Tujuan 4.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apa itu pendidikan kesempatan kedua?", "options": ["Belajar hanya setelah menyelesaikan gelar universitas", "Belajar hanya melalui olahraga dan permainan di lapangan", "Kesempatan belajar bagi orang yang pernah tidak bersekolah", "Pembelajaran yang kini dilarang di sebagian besar negara"], "answer": 2, "explain": "Pendidikan kesempatan kedua membantu orang mengejar pelajaran yang terlewat.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu program jembatan?", "options": ["Program untuk membangun jembatan di atas sungai dan jalan", "Program yang menutup sekolah di desa terpencil setiap tahun", "Program olahraga dan permainan akhir pekan untuk semua orang", "Program yang membantu peserta didik berpindah antarjenjang atau sistem"], "answer": 3, "explain": "Program jembatan membantu peserta didik berpindah dengan lancar antara sekolah dan pelatihan.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa siswa putus sekolah di jenjang menengah pertama?", "options": ["Biaya, bekerja, dan jarak", "Mereka selesai terlalu cepat", "Mereka mendapat terlalu banyak hadiah", "Mereka tidak punya pekerjaan rumah"], "answer": 0, "explain": "Biaya, pekerjaan, dan jarak adalah alasan umum siswa meninggalkan sekolah lebih awal.", "src": "UNESCO"}, {"ch": 2, "q": "Apa yang dapat membantu siswa kembali bersekolah setelah berhenti?", "options": ["Dikeluarkan secara permanen", "Program yang fleksibel dan dukungan", "Dipaksa mengulang tahun yang sama", "Hukuman dari guru"], "answer": 1, "explain": "Program fleksibel dan dukungan membantu siswa kembali belajar.", "src": "UNESCO"}, {"ch": 3, "q": "Jenis pembelajaran apa yang ingin dicapai Target 4.1?", "options": ["Hanya tulisan tangan yang rapi", "Hanya nilai tinggi dalam olahraga", "Pembelajaran yang relevan dan efektif", "Hanya membaca lebih cepat"], "answer": 2, "explain": "Target 4.1 bertujuan pada hasil belajar yang relevan dan efektif, bukan sekadar kehadiran.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Mengapa mengukur pembelajaran lebih sulit daripada menghitung kehadiran?", "options": ["Pembelajaran selalu mudah dihitung", "Kehadiran tidak pernah bisa dihitung", "Pembelajaran hanya diukur dari tinggi badan", "Pembelajaran harus dinilai, bukan hanya dihitung"], "answer": 3, "explain": "Kehadiran menunjukkan keberadaan, tetapi pembelajaran perlu penilaian keterampilan dan pemahaman.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu tingkat kemahiran minimum?", "options": ["Tingkat terendah yang sebaiknya dicapai peserta didik", "Tingkat pembelajaran tertinggi", "Tingkat khusus untuk guru saja", "Tingkat untuk bangunan sekolah"], "answer": 0, "explain": "Kemahiran minimum adalah keterampilan dasar yang harus dicapai semua peserta didik.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Mengapa banyak negara menguji membaca dan matematika?", "options": ["Untuk memilih makan siang", "Untuk melihat apakah peserta didik mencapai keterampilan dasar", "Untuk memeriksa cuaca", "Untuk memutuskan liburan"], "answer": 1, "explain": "Ujian menunjukkan apakah peserta didik mencapai keterampilan dasar yang penting.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu kesetaraan dalam pembelajaran?", "options": ["Hanya siswa terbaik yang belajar", "Semua orang mendapat dukungan yang sama persis apa pun kebutuhannya", "Setiap peserta didik mendapat kesempatan yang adil untuk belajar dengan baik", "Pembelajaran hanya terjadi di sebagian sekolah"], "answer": 2, "explain": "Kesetaraan dalam pembelajaran berarti memberi dukungan lebih di tempat yang membutuhkannya.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Keterampilan apa yang menghubungkan huruf dengan bunyi untuk membantu anak membaca?", "options": ["Bermain akrobat", "Melukis", "Hanya menari", "Fonik"], "answer": 3, "explain": "Fonik menghubungkan huruf dengan bunyi dan membantu anak membaca.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "Apa itu berpikir komputasional?", "options": ["Memecah masalah menjadi langkah-langkah untuk menyelesaikannya", "Menggunakan kalkulator untuk segala hal", "Menebak jawaban", "Menghindari teka-teki"], "answer": 0, "explain": "Berpikir komputasional memecah masalah menjadi langkah, keterampilan yang berguna dalam pemrograman dan di luar itu.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu pendidikan kewirausahaan?", "options": ["Belajar tidur nyenyak dan beristirahat di siang hari", "Belajar memulai dan menjalankan usaha atau gagasan", "Belajar menghindari pekerjaan dan tetap di rumah", "Belajar bernyanyi dalam paduan suara setiap minggu"], "answer": 1, "explain": "Pendidikan kewirausahaan membantu peserta didik menciptakan dan mengelola gagasan mereka sendiri.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu kewarganegaraan global?", "options": ["Hanya tinggal di satu kota", "Menolak belajar tentang negara lain", "Memahami dan peduli pada dunia yang lebih luas", "Mengabaikan orang lain"], "answer": 2, "explain": "Kewarganegaraan global mendorong orang memahami dan menghormati dunia yang lebih luas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Keterampilan apa yang membantu seseorang menilai apakah berita itu benar?", "options": ["Bermain akrobat", "Berkebun", "Memasak", "Literasi media"], "answer": 3, "explain": "Literasi media membantu orang memeriksa informasi dari berbagai sumber.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu kolaborasi dalam pembelajaran?", "options": ["Bekerja sama untuk mencapai tujuan bersama", "Bekerja sendiri untuk mengalahkan orang lain", "Menyontek dari teman sekelas", "Menghindari tugas kelompok"], "answer": 0, "explain": "Kolaborasi berarti peserta didik bekerja bersama dan berbagi tanggung jawab.", "src": "UNESCO"}, {"ch": 4, "q": "Apa arti budaya damai dalam Target 4.7?", "options": ["Hidup terpisah dari orang lain", "Hidup berdampingan tanpa kekerasan", "Memenangkan setiap perdebatan", "Mengabaikan budaya lain"], "answer": 1, "explain": "Budaya damai mendorong tanpa kekerasan, rasa hormat, dan saling pengertian.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Faktor apa yang dapat membuat anak perempuan tidak bersekolah di pendidikan menengah?", "options": ["Cuaca yang bagus", "Buku gratis", "Pernikahan dini dan tugas rumah tangga", "Terlalu banyak guru"], "answer": 2, "explain": "Pernikahan dini dan tugas rumah tangga dapat menghalangi anak perempuan menyelesaikan pendidikan menengah.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa itu data terpilah?", "options": ["Data yang dirahasiakan dari publik selamanya", "Data yang tidak pernah digunakan untuk mengambil keputusan", "Data tentang cuaca di wilayah setiap hari", "Data yang dibagi menurut kelompok, seperti gender atau disabilitas"], "answer": 3, "explain": "Data terpilah membantu mengungkap siapa yang tertinggal.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Mengapa data terpilah berguna?", "options": ["Data itu menunjukkan kelompok mana yang membutuhkan bantuan", "Data itu menyembunyikan masalah", "Data itu tidak pernah akurat", "Data itu hanya membantu perusahaan"], "answer": 0, "explain": "Membagi data menurut kelompok menunjukkan di mana dukungan dibutuhkan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa itu kekerasan berbasis gender terkait sekolah?", "options": ["Aturan olahraga tentang cara menjatuhkan lawan", "Kekerasan yang berkaitan dengan gender di dalam atau di sekitar sekolah", "Jenis ujian yang diambil pada akhir tahun", "Libur sekolah yang berlangsung dua minggu penuh"], "answer": 1, "explain": "Kekerasan ini berkaitan dengan gender dan merugikan pembelajaran anak.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa yang bisa dilakukan sekolah untuk melindungi anak dari kekerasan?", "options": ["Mengabaikan keluhan dari siswa dan orang tua", "Menghukum anak yang melaporkan masalah kepada staf", "Membuat sistem pelaporan yang aman dan melatih staf", "Menutup sekolah setiap kali ada keluhan"], "answer": 2, "explain": "Sistem pelaporan yang aman dan pelatihan staf membantu melindungi anak.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa itu lingkungan belajar yang aman?", "options": ["Tempat tanpa guru", "Tempat tanpa aturan sama sekali", "Tempat siswa selalu sendirian", "Tempat siswa merasa aman untuk belajar"], "answer": 3, "explain": "Lingkungan belajar yang aman memungkinkan siswa belajar tanpa rasa takut.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Mengapa penting membayar guru dengan adil?", "options": ["Itu membantu menjaga guru yang berkualifikasi tetap di sekolah", "Itu membuat sekolah makin miskin", "Itu mengurangi pembelajaran", "Itu membuat guru berhenti peduli"], "answer": 0, "explain": "Gaji yang adil membantu mempertahankan guru terlatih di sekolah.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu keluarnya guru dari profesi (attrition)?", "options": ["Guru yang naik jabatan", "Guru yang meninggalkan profesi", "Guru yang mengambil libur", "Guru yang memenangkan penghargaan"], "answer": 1, "explain": "Attrition berarti guru meninggalkan profesi, yang merugikan pembelajaran.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu jalur karier guru?", "options": ["Jalan hanya sampai gerbang sekolah", "Jalan khusus untuk siswa", "Jalan untuk berkembang dan naik jabatan", "Jalan tanpa gaji"], "answer": 2, "explain": "Jalur karier memberi guru cara untuk berkembang dan maju.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu pengembangan profesional berkelanjutan untuk guru?", "options": ["Satu hari pelatihan seumur hidup", "Tidak ada pelatihan setelah lulus", "Pelatihan hanya untuk kepala sekolah", "Pelatihan berkelanjutan selama karier mengajar"], "answer": 3, "explain": "Pengembangan berkelanjutan menjaga keterampilan guru sepanjang karier mereka.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa kualitas guru itu penting?", "options": ["Ini salah satu faktor kunci dalam seberapa baik anak belajar", "Ini sama sekali tidak berpengaruh pada cara anak belajar", "Ini hanya penting untuk olahraga dan pendidikan jasmani", "Ini hanya penting untuk tampilan gedung sekolah"], "answer": 0, "explain": "Kualitas guru adalah salah satu faktor kunci dalam seberapa baik anak belajar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa daerah terpencil sering kesulitan mempertahankan guru?", "options": ["Daerah terpencil punya terlalu banyak guru", "Terlalu sedikit guru yang mau bekerja di sana", "Guru lebih suka liburan", "Guru tidak pernah bepergian"], "answer": 1, "explain": "Daerah terpencil sering kesulitan menarik dan mempertahankan cukup banyak guru.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Apa itu pembiayaan domestik untuk pendidikan?", "options": ["Uang dari bulan", "Uang hanya dari klub olahraga", "Uang yang dikumpulkan sendiri oleh negara untuk sekolah", "Uang hanya dari seragam sekolah"], "answer": 2, "explain": "Pembiayaan domestik adalah uang yang dikumpulkan negara dari pajak dan pendapatannya sendiri.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Berapa porsi PDB yang disarankan Kerangka Incheon untuk pendidikan?", "options": ["0,5 sampai 1 persen", "20 sampai 30 persen", "50 sampai 60 persen", "4 sampai 6 persen"], "answer": 3, "explain": "Kerangka Incheon menyarankan 4 sampai 6 persen PDB dan/atau 15 sampai 20 persen belanja publik.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Berapa porsi belanja publik yang disarankan Kerangka Incheon untuk pendidikan?", "options": ["15 sampai 20 persen", "1 sampai 2 persen", "40 sampai 50 persen", "90 sampai 100 persen"], "answer": 0, "explain": "Incheon menyarankan 15 sampai 20 persen dari total belanja publik untuk pendidikan.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Apa itu kesenjangan pembiayaan pendidikan?", "options": ["Uang yang ditabung untuk liburan keluarga dan perjalanan musim panas", "Selisih antara uang yang dibutuhkan dan uang yang tersedia", "Jarak antara dua gedung sekolah di kota", "Uang yang tidak punya kegunaan nyata di sekolah mana pun saat ini"], "answer": 1, "explain": "Kesenjangan pembiayaan adalah jumlah yang masih dibutuhkan untuk mendanai tujuan pendidikan.", "src": "UNESCO"}, {"ch": 7, "q": "Mengapa sekolah di daerah miskin sering kekurangan dana?", "options": ["Mereka punya terlalu banyak siswa", "Mereka memilih untuk tidak menerima uang", "Pendapatan pajak lebih kecil dan pendanaan yang tidak merata", "Mereka tidak membutuhkan buku"], "answer": 2, "explain": "Pendanaan yang tidak merata dapat membuat daerah miskin kekurangan sumber daya.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "Apa itu pendanaan kapitasi?", "options": ["Uang yang diberikan untuk mobil setiap guru", "Uang yang diberikan untuk setiap bus sekolah", "Uang yang diberikan untuk setiap piala olahraga", "Uang yang diberikan kepada sekolah untuk setiap siswa"], "answer": 3, "explain": "Pendanaan kapitasi membayar sekolah berdasarkan jumlah siswa.", "src": "UNESCO"}, {"ch": 8, "q": "Tujuan apa yang menggantikan Tujuan Pembangunan Milenium?", "options": ["Tujuan Pembangunan Berkelanjutan", "Tujuan Olimpiade", "Tujuan Perdagangan", "Tujuan Antariksa"], "answer": 0, "explain": "SDG (Tujuan Global) menggantikan MDG pada tahun 2015.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Pada tahun berapa Kerangka Aksi Pendidikan 2030 diadopsi?", "options": ["1990", "2015", "2000", "2030"], "answer": 1, "explain": "Kerangka Aksi Pendidikan 2030 diadopsi pada tahun 2015.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "Apa yang dikatakan deklarasi 1948 tentang pendidikan?", "options": ["Sekolah harus ditutup", "Pendidikan hanya untuk orang dewasa", "Setiap orang berhak atas pendidikan", "Pendidikan adalah barang mewah"], "answer": 2, "explain": "Deklarasi Universal Hak Asasi Manusia menyatakan pendidikan sebagai hak asasi manusia.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Apa yang dikatakan Pasal 26 Deklarasi Universal tentang pendidikan dasar?", "options": ["Harus mahal", "Harus bersifat opsional bagi semua orang", "Harus hanya untuk anak laki-laki", "Harus gratis dan wajib"], "answer": 3, "explain": "Pasal 26 menyatakan pendidikan dasar harus wajib dan gratis.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Apa yang terjadi pada Forum Pendidikan Dunia 2015 di Incheon?", "options": ["Negara-negara menyepakati tujuan pendidikan untuk 2030", "Negara-negara menutup semua sekolah", "Negara-negara menyepakati olahraga baru", "Negara-negara mengakhiri program literasi"], "answer": 0, "explain": "Deklarasi Incheon menetapkan tujuan pendidikan untuk 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Apa yang diserukan konferensi Jomtien tahun 1990?", "options": ["Pendidikan hanya untuk orang kaya", "Pendidikan untuk semua", "Pendidikan hanya dalam bahasa Inggris", "Sekolah tanpa guru"], "answer": 1, "explain": "Konferensi Jomtien 1990 menyerukan pendidikan untuk semua.", "src": "UNESCO"}, {"ch": 9, "q": "Mengapa pengasuhan anak usia dini dikaitkan dengan pembelajaran di kemudian hari?", "options": ["Tahun-tahun awal tidak ada kaitannya", "Hanya pembelajaran orang dewasa yang penting", "Keterampilan awal mendukung keberhasilan sekolah di kemudian hari", "Pembelajaran di kemudian hari tidak ada hubungannya"], "answer": 2, "explain": "Fondasi awal yang kuat membuat pembelajaran selanjutnya lebih mudah.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu kesiapan sekolah?", "options": ["Siap untuk meninggalkan sekolah", "Cukup tinggi untuk meja belajar", "Bisa mengendarai kendaraan", "Siap untuk belajar saat mulai sekolah"], "answer": 3, "explain": "Kesiapan sekolah berarti anak memiliki keterampilan dan kesehatan untuk mulai sekolah.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa peran bermain dalam pembelajaran awal?", "options": ["Membangun kemampuan berpikir, bahasa, dan sosial", "Tidak punya peran", "Menggantikan semua pembelajaran selamanya", "Hanya membuang waktu"], "answer": 0, "explain": "Bermain membantu anak membangun kemampuan berpikir, bahasa, dan sosial.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa bayi membutuhkan pengasuhan yang responsif?", "options": ["Itu memanjakan mereka", "Itu membantu perkembangan otak dan emosi mereka", "Itu tidak diperlukan", "Itu hanya membuat mereka tertidur"], "answer": 1, "explain": "Pengasuhan responsif mendukung perkembangan otak dan emosi yang sehat.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa yang dimaksud dengan seribu hari pertama?", "options": ["Hari pertama sekolah", "Minggu pertama liburan", "Masa dari kehamilan hingga usia dua tahun", "Tahun pertama di universitas"], "answer": 2, "explain": "Seribu hari pertama, dari kehamilan hingga usia dua tahun, sangat penting bagi perkembangan.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Kegiatan anak usia dini apa yang mendukung pertumbuhan otak?", "options": ["Keheningan total", "Hanya layar gawai terus-menerus", "Dibiarkan sendirian berjam-jam", "Berbicara dan membaca bersama anak"], "answer": 3, "explain": "Berbicara dan membaca bersama anak mendukung bahasa dan pertumbuhan otak.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Apa itu pascaliterasi?", "options": ["Pembelajaran yang dibangun di atas literasi dasar", "Hanya membaca komik", "Literasi hanya untuk guru", "Hanya membaca majalah"], "answer": 0, "explain": "Pascaliterasi membantu orang mempertahankan dan mengembangkan kemampuan membaca dan menulis dasar.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Apa itu literasi untuk semua?", "options": ["Literasi hanya untuk anak-anak", "Kesempatan literasi untuk setiap orang", "Literasi hanya untuk orang kaya", "Literasi hanya dalam satu bahasa"], "answer": 1, "explain": "Literasi untuk semua bertujuan memberi setiap orang kesempatan untuk membaca dan menulis.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Mengapa program literasi multibahasa itu berguna?", "options": ["Mereka mencegah belajar bahasa kedua", "Mereka menghilangkan kebutuhan akan buku", "Mereka membantu peserta didik membaca dalam bahasa ibu mereka terlebih dahulu", "Mereka hanya berhasil dalam olahraga"], "answer": 2, "explain": "Belajar membaca dalam bahasa yang dipahami anak mendukung pembelajaran di kemudian hari.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Apa hubungan antara literasi dan kesehatan?", "options": ["Membaca membuat orang sakit", "Tidak ada hubungannya", "Kesehatan hanya bergantung pada olahraga", "Membaca membantu orang memahami saran kesehatan"], "answer": 3, "explain": "Literasi membantu orang membaca label obat dan panduan kesehatan.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Apa tujuan kampanye literasi?", "options": ["Mengajarkan membaca dan menulis kepada banyak orang", "Menjual lebih banyak koran kepada keluarga sibuk setiap minggu", "Menghentikan orang membaca buku dan majalah", "Membangun lebih banyak jalan dan jembatan di seluruh negeri"], "answer": 0, "explain": "Kampanye literasi berupaya mengurangi buta huruf di seluruh masyarakat.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Keterampilan apa yang mendasar bagi literasi?", "options": ["Melempar-tangkap bola", "Mengenali huruf dan bunyinya", "Mengemudikan bus", "Memasak nasi"], "answer": 1, "explain": "Mengenali huruf dan bunyinya adalah keterampilan literasi dasar.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "Apa yang dijamin Target 4.5 untuk kelompok rentan?", "options": ["Akses hanya untuk siswa terbaik", "Akses hanya untuk keluarga kaya", "Akses yang setara terhadap pendidikan", "Akses hanya di kota besar"], "answer": 2, "explain": "Target 4.5 menjamin akses yang setara bagi kelompok rentan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Apa itu rencana pendidikan individual bagi siswa?", "options": ["Rencana untuk liburan", "Rencana untuk menghindari kelas", "Rencana untuk memindahkan siswa ke sekolah lain", "Rencana yang disesuaikan dengan kebutuhan peserta didik"], "answer": 3, "explain": "Rencana pendidikan individual membantu guru memenuhi kebutuhan khusus setiap siswa.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa yang dituntut akomodasi yang layak dari sekolah?", "options": ["Penyesuaian yang membantu peserta didik ikut serta", "Mengabaikan kebutuhan peserta didik", "Memungut biaya tambahan", "Menghapus semua dukungan"], "answer": 0, "explain": "Sekolah harus melakukan penyesuaian yang wajar agar peserta didik penyandang disabilitas dapat ikut serta.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Mengapa materi yang mudah diakses itu penting?", "options": ["Itu membuat belajar makin sulit bagi semua orang", "Itu memungkinkan semua peserta didik menggunakan materi yang sama", "Itu hanya untuk guru", "Itu menggantikan guru"], "answer": 1, "explain": "Materi yang mudah diakses, seperti huruf besar atau braille, membantu peserta didik mengikuti pelajaran.", "src": "UN CRPD (2006), Article 24"}], "7": [{"ch": 0, "q": "Tujuan Global manakah yang berkaitan dengan aksi iklim?", "options": ["Tujuan 13", "Tujuan 3", "Tujuan 14", "Tujuan 10"], "answer": 0, "explain": "Tujuan 13 adalah Aksi Iklim.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Target manakah yang bertujuan menghapus kesenjangan gender dalam pendidikan?", "options": ["Target 4.1", "Target 4.5", "Target 4.4", "Target 4.a"], "answer": 1, "explain": "Target 4.5 bertujuan menghapus kesenjangan gender dan menjamin akses yang setara.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Mengapa mengukur capaian pembelajaran itu penting?", "options": ["Itu hanya menghitung berapa banyak gedung sekolah di kota", "Itu menentukan harga buku sekolah di setiap toko", "Itu menunjukkan apa yang benar-benar dipelajari anak, bukan hanya jumlah pendaftar", "Itu mengukur tinggi dan berat setiap murid"], "answer": 2, "explain": "Memantau capaian pembelajaran menunjukkan apakah anak-anak benar-benar belajar.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "Apa tujuan indikator SDG 4?", "options": ["Memilih warna sekolah", "Memeringkat guru berdasarkan tinggi badan", "Menentukan tanggal libur", "Mengukur kemajuan pada setiap target"], "answer": 3, "explain": "Indikator mengukur kemajuan menuju setiap target.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Mengapa Tujuan 4 terkait dengan Tujuan Global lainnya?", "options": ["Pendidikan mendukung kesehatan, pekerjaan, dan kesetaraan", "Pendidikan tidak punya kaitan dengan tujuan lain", "Pendidikan hanya penting untuk olahraga", "Pendidikan hanya untuk kota-kota"], "answer": 0, "explain": "Pendidikan mendukung kemajuan di banyak tujuan, seperti kesehatan, pekerjaan, dan kesetaraan gender.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Target manakah yang bertujuan literasi dan numerasi bagi generasi muda dan orang dewasa?", "options": ["Target 4.1", "Target 4.6", "Target 4.5", "Target 4.c"], "answer": 1, "explain": "Target 4.6 bertujuan literasi dan numerasi bagi seluruh generasi muda dan sebagian besar orang dewasa.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa yang dilacak indikator 4.1.1?", "options": ["Jumlah bus sekolah yang beroperasi di setiap jalan utama", "Rata-rata harga seragam sekolah di setiap kota", "Anak-anak yang mencapai tingkat kemahiran minimum dalam membaca dan matematika", "Rata-rata tinggi setiap ruang kelas di sekolah"], "answer": 2, "explain": "Indikator 4.1.1 melacak proporsi anak yang mencapai tingkat kemahiran minimum.", "src": "UN SDG Report 2026"}, {"ch": 1, "q": "Apa itu kesenjangan digital?", "options": ["Jurang antara dua ruang kelas di gedung sekolah yang sama", "Jeda di antara dua pelajaran panjang pada hari sekolah yang sibuk", "Pemisah antara dua bahasa yang hanya digunakan di rumah", "Jurang antara orang yang punya akses internet dan yang tidak"], "answer": 3, "explain": "Kesenjangan digital adalah jurang dalam akses ke perangkat dan internet.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Mengapa pendidikan jarak jauh dapat membantu sebagian peserta didik?", "options": ["Menjangkau peserta didik di daerah terpencil", "Menggantikan semua guru", "Menghentikan pembelajaran", "Hanya untuk orang dewasa"], "answer": 0, "explain": "Pembelajaran jarak jauh dan daring dapat menjangkau orang yang tinggal jauh dari sekolah.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa itu pusat belajar di komunitas terpencil?", "options": ["Pusat perbelanjaan dengan banyak toko dan kafe", "Ruang tempat peserta didik dapat belajar dengan dukungan", "Bangsal rumah sakit tempat pasien beristirahat dan pulih", "Stadion olahraga untuk pertandingan sepak bola besar"], "answer": 1, "explain": "Pusat belajar memberi peserta didik terpencil tempat untuk belajar dan mendapatkan bantuan.", "src": "UNESCO"}, {"ch": 1, "q": "Apa itu pemetaan sekolah?", "options": ["Menggambar peta rute liburan untuk perjalanan keluarga ke luar negeri", "Memetakan lapangan olahraga yang dipakai untuk pertandingan sekolah", "Mencari tahu di mana sekolah dibutuhkan dan siapa yang dapat menjangkaunya", "Merancang logo dan poster baru untuk setiap sekolah"], "answer": 2, "explain": "Pemetaan sekolah membantu pemerintah merencanakan di mana sekolah dan transportasi baru dibutuhkan.", "src": "UNESCO"}, {"ch": 1, "q": "Apa hambatan umum untuk bersekolah di kota?", "options": ["Terlalu banyak ruang hijau", "Terlalu banyak perpustakaan", "Terlalu banyak guru", "Biaya hidup yang tinggi bagi keluarga miskin"], "answer": 3, "explain": "Di kota, keluarga miskin dapat kesulitan dengan biaya transportasi dan hidup.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa arti akses bagi peserta didik penyandang disabilitas?", "options": ["Dapat masuk dan menggunakan fasilitas sekolah", "Dapat meninggalkan sekolah kapan saja", "Dapat membolos pelajaran", "Dapat menghindari ujian"], "answer": 0, "explain": "Akses berarti peserta didik penyandang disabilitas dapat masuk dan menggunakan ruang sekolah serta bahan belajar.", "src": "UN CRPD (2006), Article 24"}, {"ch": 2, "q": "Apa itu kesenjangan penyelesaian?", "options": ["Celah di dinding sekolah yang perlu segera diperbaiki", "Perbedaan dalam menyelesaikan sekolah antarkelompok", "Ruang di antara dua meja di kelas yang penuh sesak", "Celah dalam jadwal sekolah setiap Jumat siang"], "answer": 1, "explain": "Kesenjangan penyelesaian menunjukkan bahwa sebagian kelompok lebih jarang menyelesaikan sekolah dibanding yang lain.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Mengapa anak dari keluarga berpenghasilan tinggi lebih sering menyelesaikan sekolah?", "options": ["Anak-anak mereka kurang cerdas", "Anak-anak mereka tidak pernah mengikuti ujian", "Keluarga mereka mampu menanggung biaya dan transportasi", "Anak-anak mereka menghindari pekerjaan rumah"], "answer": 2, "explain": "Penghasilan membantu keluarga menanggung biaya dan transportasi, sehingga penyelesaian sekolah lebih mungkin terjadi.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Apa yang diukur oleh angka bertahan hingga kelas terakhir?", "options": ["Proporsi yang memenangkan perlombaan", "Proporsi yang memiliki sepeda", "Proporsi yang berbicara dua bahasa", "Proporsi anak yang mencapai kelas terakhir"], "answer": 3, "explain": "Angka bertahan mengukur berapa banyak siswa yang mencapai kelas terakhir suatu jenjang.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa pernikahan dini memengaruhi penyelesaian sekolah?", "options": ["Itu dapat mengakhiri sekolah seorang anak perempuan", "Itu meningkatkan kehadiran sekolah", "Itu sama sekali tidak berpengaruh", "Itu hanya memengaruhi anak laki-laki"], "answer": 0, "explain": "Pernikahan dini sering mengakhiri pendidikan anak perempuan sebelum mereka menyelesaikan sekolah.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 2, "q": "Apa itu kembali bersekolah?", "options": ["Masuk sekolah untuk pertama kali", "Kembali ke sekolah setelah berhenti", "Berhenti sekolah selamanya", "Mengganti seragam sekolah"], "answer": 1, "explain": "Kebijakan kembali bersekolah membantu kaum muda kembali ke sekolah setelah putus sekolah.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu transisi dari sekolah ke dunia kerja?", "options": ["Pindah gedung sekolah", "Berganti guru", "Perpindahan dari sekolah ke pekerjaan atau pelatihan", "Hanya pindah ke negara lain"], "answer": 2, "explain": "Transisi dari sekolah ke dunia kerja adalah perpindahan dari pendidikan ke pekerjaan atau pelatihan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Apa itu kehilangan pembelajaran?", "options": ["Kehilangan kotak pensil di bus setiap pagi", "Lupa kata sandi komputer sekolah", "Kalah dalam pertandingan sepak bola melawan sekolah rival", "Hilangnya keterampilan setelah jeda panjang dalam belajar"], "answer": 3, "explain": "Kehilangan pembelajaran berarti keterampilan memudar setelah sekolah tutup atau pembelajaran terganggu.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa yang membantu siswa pulih dari kehilangan pembelajaran?", "options": ["Bimbingan belajar dan kelas pengejaran yang terarah", "Mengurangi pengajaran", "Menghapus semua ujian", "Hanya libur yang lebih panjang"], "answer": 0, "explain": "Dukungan yang terarah membantu peserta didik mengejar ketertinggalan.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu pembelajaran penguasaan?", "options": ["Peserta didik tidak pernah mengulang topik", "Peserta didik berpindah ke materi berikutnya hanya setelah memahami topik", "Peserta didik melewatkan semua topik sulit", "Peserta didik hanya menghafal jawaban"], "answer": 1, "explain": "Pembelajaran penguasaan memastikan peserta didik memahami sebelum melanjutkan.", "src": "UNESCO"}, {"ch": 3, "q": "Mengapa bahasa pengantar itu penting?", "options": ["Itu tidak berpengaruh", "Hanya satu bahasa yang boleh digunakan", "Peserta didik paling memahami pelajaran dalam bahasa yang mereka kuasai", "Itu hanya penting dalam olahraga"], "answer": 2, "explain": "Menggunakan bahasa yang dipahami peserta didik mendukung pembelajaran.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "Apa itu pendidikan dwibahasa?", "options": ["Mengajar hanya melalui permainan", "Mengajar tanpa bahasa apa pun", "Mengajar dalam satu bahasa untuk tari", "Mengajar dalam dua bahasa"], "answer": 3, "explain": "Pendidikan dwibahasa menggunakan dua bahasa untuk membantu peserta didik memahami dan berkembang.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "Apa itu membaca kritis?", "options": ["Mempertanyakan dan menilai sebuah teks", "Membaca tanpa berpikir", "Hanya membaca judulnya", "Hanya membaca gambarnya"], "answer": 0, "explain": "Membaca kritis menanyakan apakah teks itu akurat, adil, dan beralasan dengan baik.", "src": "UNESCO"}, {"ch": 4, "q": "Apa kepanjangan TIK dalam pendidikan?", "options": ["Yayasan Memasak Internasional", "Teknologi Informasi dan Komunikasi", "Tur Kampus yang Menarik", "Tes Kelas yang Penting"], "answer": 1, "explain": "TIK adalah singkatan dari teknologi informasi dan komunikasi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu pendidikan vokasi?", "options": ["Pendidikan tanpa keterampilan praktis atau pelatihan langsung", "Pendidikan hanya untuk mereka yang sudah bekerja sebagai guru", "Pendidikan yang mempersiapkan orang untuk profesi atau pekerjaan tertentu", "Pendidikan hanya untuk siswa yang akan melanjutkan ke universitas"], "answer": 2, "explain": "Pendidikan vokasi membangun keterampilan praktis untuk pekerjaan tertentu.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa kepanjangan TVET?", "options": ["Ujian video guru", "Alat pendidikan visual total", "Tema pendidikan video tersier", "Pendidikan dan pelatihan teknis dan vokasi"], "answer": 3, "explain": "TVET adalah singkatan dari pendidikan dan pelatihan teknis dan vokasi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Mengapa pemrograman diajarkan di beberapa sekolah?", "options": ["Itu membangun kemampuan memecahkan masalah dan keterampilan digital", "Itu menggantikan semua mata pelajaran lain", "Itu hanya untuk permainan", "Itu menghentikan pembelajaran"], "answer": 0, "explain": "Pemrograman mengajarkan logika dan keterampilan digital yang berguna di banyak pekerjaan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu kewargaan digital?", "options": ["Menggunakan teknologi untuk menyakiti orang lain", "Menggunakan teknologi dengan aman, bertanggung jawab, dan penuh hormat", "Menghindari semua teknologi", "Menggunakan teknologi hanya untuk bermain game"], "answer": 1, "explain": "Kewargaan digital berarti berperilaku baik secara daring dan menghormati orang lain.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu keterampilan yang sedang berkembang?", "options": ["Keterampilan yang tidak lagi dibutuhkan", "Keterampilan khusus untuk bahasa kuno", "Keterampilan yang menjadi penting dalam pekerjaan baru", "Keterampilan untuk tidur"], "answer": 2, "explain": "Keterampilan yang sedang berkembang menjadi penting seiring munculnya jenis pekerjaan baru.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa itu kesenjangan gender dalam pendidikan STEM?", "options": ["Anak perempuan belajar matematika lebih banyak daripada anak laki-laki di hampir semua negara saat ini", "Tidak ada kesenjangan apa pun di kelas sains di mana pun", "Hanya anak laki-laki yang boleh belajar mata pelajaran sains di sekolah", "Lebih sedikit anak perempuan daripada laki-laki yang belajar sains, teknologi, teknik, dan matematika"], "answer": 3, "explain": "Banyak negara menunjukkan lebih sedikit anak perempuan dalam mata pelajaran STEM, yang membatasi pilihan mereka.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Mengapa guru perempuan bisa penting di beberapa tempat?", "options": ["Mereka dapat menjadi teladan dan membantu anak perempuan tetap bersekolah", "Mereka tidak dibutuhkan di sekolah mana pun di dunia", "Mereka hanya mengajar olahraga dan aktivitas fisik di luar ruangan", "Mereka mencegah anak-anak mempelajari mata pelajaran baru sama sekali"], "answer": 0, "explain": "Guru perempuan dapat menyemangati anak perempuan dan membantu menciptakan lingkungan yang aman.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa itu sekolah yang responsif gender?", "options": ["Sekolah khusus untuk anak perempuan", "Sekolah yang memenuhi kebutuhan anak perempuan dan laki-laki", "Sekolah yang mengabaikan gender", "Sekolah tanpa toilet"], "answer": 1, "explain": "Sekolah yang responsif gender merencanakan kebutuhan anak perempuan dan laki-laki yang berbeda.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa arti terpinggirkan?", "options": ["Ditempatkan di pusat perhatian", "Otomatis mendapat uang tambahan", "Didorong ke pinggir masyarakat dan dikucilkan", "Diizinkan membuat semua aturan"], "answer": 2, "explain": "Kelompok yang terpinggirkan sering dikecualikan dari pendidikan dan kesempatan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Mengapa penutur bahasa minoritas berisiko tertinggal?", "options": ["Mereka selalu menjadi peserta didik terbaik", "Bahasa mereka tidak pernah digunakan", "Mereka tidak pernah bersekolah", "Sekolah mungkin tidak mengajar dalam bahasa mereka"], "answer": 3, "explain": "Ketika pelajaran menggunakan bahasa yang tidak dikuasai anak, banyak yang tertinggal.", "src": "UNESCO, International Mother Language Day"}, {"ch": 5, "q": "Apa itu tindakan afirmatif dalam pendidikan?", "options": ["Dukungan tambahan bagi kelompok yang menghadapi ketidakuntungan", "Menghukum kelompok yang berprestasi baik", "Mengabaikan semua perbedaan", "Menutup sekolah bagi kelompok tertentu"], "answer": 0, "explain": "Tindakan afirmatif memberi dukungan tambahan untuk membantu kelompok yang kurang beruntung mengejar ketertinggalan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa arti status sosial-ekonomi?", "options": ["Jenis ujian sekolah", "Kedudukan sosial dan ekonomi seseorang", "Warna tas sekolah", "Jumlah kemenangan olahraga"], "answer": 1, "explain": "Status sosial-ekonomi menggambarkan penghasilan, pendidikan, dan kedudukan sosial sebuah keluarga.", "src": "UNESCO GEM Report 2026"}, {"ch": 6, "q": "Apa itu kesenjangan guru?", "options": ["Guru tambahan yang tidak melakukan apa pun", "Guru yang tidak punya jam mengajar", "Jumlah guru tambahan yang dibutuhkan untuk memenuhi permintaan", "Guru yang tidak pernah meninggalkan sekolah"], "answer": 2, "explain": "Kesenjangan guru adalah jumlah guru tambahan yang dibutuhkan untuk mencapai tujuan pendidikan.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa pasokan guru menjadi tantangan di banyak negara?", "options": ["Terlalu banyak orang ingin mengajar", "Guru tidak pernah dibutuhkan", "Guru hanya punya terlalu banyak murid", "Terlalu sedikit orang yang dilatih atau bertahan sebagai guru"], "answer": 3, "explain": "Kekurangan guru disebabkan oleh terlalu sedikit calon yang dilatih, gaji rendah, dan tingginya perputaran.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu status guru?", "options": ["Cara guru dihargai dalam masyarakat", "Tinggi badan seorang guru", "Mobil seorang guru", "Tas sekolah seorang guru"], "answer": 0, "explain": "Status guru memengaruhi apakah orang memilih dan bertahan dalam profesi mengajar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu guru di daerah krisis?", "options": ["Guru yang hanya bekerja di kota", "Guru yang bekerja di tempat yang dilanda konflik atau bencana", "Guru yang tidak pernah mengajar", "Guru yang hanya bekerja saat libur"], "answer": 1, "explain": "Guru di daerah krisis bekerja dalam kondisi sulit agar anak-anak tetap belajar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa sebagian guru meninggalkan profesinya?", "options": ["Gaji terlalu tinggi dan terlalu banyak libur berbayar", "Pekerjaan terlalu sedikit dan terlalu banyak hari bebas", "Gaji rendah, beban kerja berat, atau dukungan yang kurang", "Terlalu banyak penghargaan dan pujian"], "answer": 2, "explain": "Gaji rendah dan beban kerja berat membuat sebagian guru keluar dari profesi.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu beban kerja guru?", "options": ["Berat tas seorang guru", "Jumlah libur guru", "Harga mobil seorang guru", "Jumlah pekerjaan yang harus dilakukan seorang guru"], "answer": 3, "explain": "Beban kerja mencakup mengajar, menyusun rencana, menilai, dan tugas lainnya.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Untuk apa angka kemiskinan belajar digunakan?", "options": ["Melacak anak yang belum bisa membaca pada usia sepuluh tahun", "Melacak gedung sekolah", "Melacak harga pulpen", "Melacak libur guru"], "answer": 0, "explain": "Angka kemiskinan belajar menunjukkan proporsi anak yang tidak bisa membaca teks sederhana pada usia sepuluh tahun.", "src": "World Bank, learning poverty"}, {"ch": 7, "q": "Mengapa belanja publik untuk pendidikan itu penting?", "options": ["Itu tidak punya tujuan", "Itu membiayai guru, gedung, dan bahan ajar", "Itu hanya membiayai libur", "Itu hanya membeli peralatan olahraga"], "answer": 1, "explain": "Uang publik menjaga sekolah tetap berjalan dan membuat pembelajaran tersedia bagi semua orang.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu pelaksanaan anggaran dalam pendidikan?", "options": ["Membatalkan semua pelajaran", "Menghentikan semua kunjungan sekolah", "Membelanjakan uang sesuai rencana", "Menjual gedung sekolah"], "answer": 2, "explain": "Pelaksanaan anggaran memeriksa apakah dana pendidikan yang direncanakan benar-benar dibelanjakan.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu pembagian biaya dalam pendidikan?", "options": ["Sekolah membayar keluarga", "Guru membayar siswa", "Siswa membayar guru", "Keluarga membayar sebagian biaya sekolah"], "answer": 3, "explain": "Pembagian biaya berarti keluarga ikut menanggung, yang dapat membatasi akses bagi anak yang lebih miskin.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu pajak pendidikan?", "options": ["Pajak yang digunakan untuk membiayai sekolah", "Biaya hanya untuk mengikuti ujian", "Pajak hanya untuk buku sekolah", "Denda karena tidak masuk sekolah"], "answer": 0, "explain": "Beberapa negara memungut pajak pendidikan untuk membiayai sekolah.", "src": "UNESCO"}, {"ch": 7, "q": "Mengapa sekolah perlu perbaikan rutin?", "options": ["Gedung baru selalu perlu perbaikan", "Gedung tua bisa menjadi tidak aman", "Perbaikan membuat sekolah lebih besar", "Perbaikan membuat anak berhenti belajar"], "answer": 1, "explain": "Perbaikan rutin menjaga gedung tetap aman dan layak untuk belajar.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu nilai uang dalam belanja pendidikan?", "options": ["Membelanjakan uang sebanyak mungkin setiap tahun", "Membelanjakan uang hanya untuk peralatan olahraga", "Mendapatkan hasil belajar yang baik untuk uang yang dibelanjakan", "Tidak membelanjakan uang sama sekali setiap tahun"], "answer": 2, "explain": "Nilai uang berarti membelanjakan secara bijak untuk memperbaiki pembelajaran.", "src": "UNESCO"}, {"ch": 8, "q": "Konferensi mana yang mengadopsi Agenda 2030?", "options": ["Pertemuan regional di Tokyo, 2005", "Pertemuan di Kairo tentang kependudukan, 1994", "Konferensi di Lima tentang pertanian, 2014", "KTT PBB di New York, 2015"], "answer": 3, "explain": "Para pemimpin dunia mengadopsi Agenda 2030 pada KTT PBB di New York pada 2015.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Kapan Konferensi Dunia tentang Pendidikan untuk Semua di Jomtien diselenggarakan?", "options": ["1990", "1975", "2005", "2020"], "answer": 0, "explain": "Konferensi Jomtien diselenggarakan pada 1990.", "src": "UNESCO"}, {"ch": 8, "q": "Pada tahun berapa Forum Pendidikan Dunia Dakar berlangsung?", "options": ["1995", "2000", "2010", "2015"], "answer": 1, "explain": "Forum Pendidikan Dunia Dakar berlangsung pada tahun 2000.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Apa fokus deklarasi Jomtien 1990?", "options": ["Hanya pembelajaran di universitas", "Hanya olahraga", "Memenuhi kebutuhan belajar dasar semua orang", "Hanya ujian"], "answer": 2, "explain": "Deklarasi 1990 berfokus pada pemenuhan kebutuhan belajar dasar semua orang.", "src": "UNESCO"}, {"ch": 8, "q": "Apa fokus MDG dalam pendidikan?", "options": ["Mobil gratis", "Hanya beasiswa universitas", "Liga olahraga", "Pendidikan dasar universal"], "answer": 3, "explain": "MDG 2 berfokus pada pendidikan dasar universal.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "Apa tujuan laporan global tentang pendidikan?", "options": ["Melacak kemajuan dan membagikan bukti", "Menutup sekolah", "Memilih libur", "Menjual buku teks"], "answer": 0, "explain": "Laporan global melacak kemajuan dan membagikan bukti untuk memandu kebijakan.", "src": "UNESCO GEM Report 2026"}, {"ch": 9, "q": "Apa yang dicakup perkembangan anak pada usia dini?", "options": ["Hanya pertumbuhan ukuran", "Pertumbuhan tubuh, pikiran, dan keterampilan sosial", "Hanya pertumbuhan uang", "Hanya pertumbuhan kecepatan"], "answer": 1, "explain": "Perkembangan anak mencakup pertumbuhan fisik, berpikir, bahasa, dan sosial.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu stres beracun pada masa kanak-kanak usia dini?", "options": ["Sejenis makanan sehat yang dimakan anak setiap hari", "Permainan seru yang sering dimainkan anak di taman", "Stres yang kuat dan berkepanjangan yang dapat merusak perkembangan", "Mata pelajaran sekolah yang diajarkan pada anak usia dini"], "answer": 2, "explain": "Stres beracun dapat merusak otak yang sedang berkembang jika berlangsung lama dan tanpa dukungan.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa program usia dini membantu anak-anak yang kurang beruntung?", "options": ["Mereka menciptakan kesenjangan", "Mereka hanya untuk anak-anak kaya", "Mereka menggantikan keluarga", "Mereka mengurangi kesenjangan sebelum sekolah dimulai"], "answer": 3, "explain": "Program usia dini dapat menyamakan awal bagi anak dari rumah yang kurang beruntung.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa yang diberikan dukungan pengasuhan bagi pembelajaran usia dini?", "options": ["Membantu orang tua mendukung pembelajaran anak mereka", "Sepenuhnya menggantikan orang tua dalam kehidupan anak", "Mencegah anak belajar di rumah dan di sekolah", "Hanya membeli mainan untuk anak bermain"], "answer": 0, "explain": "Dukungan pengasuhan memberi orang dewasa gagasan untuk berbicara, bermain, dan merawat anak kecil.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa yang termasuk lingkungan belajar di rumah?", "options": ["Hanya televisi", "Buku, percakapan, dan permainan di rumah", "Hanya keheningan", "Hanya pekerjaan rumah"], "answer": 1, "explain": "Lingkungan belajar di rumah yang mendukung mendorong membaca, bercakap-cakap, dan bermain.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa pengasuhan anak usia dini penting bagi anak perempuan?", "options": ["Itu tidak diperlukan bagi anak perempuan", "Itu hanya penting setelah sekolah", "Itu membantu mereka mulai sekolah dengan siap belajar", "Itu hanya penting bagi anak laki-laki"], "answer": 2, "explain": "Pengasuhan dini mendukung kesehatan, pembelajaran, dan rasa percaya diri anak perempuan.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 10, "q": "Apa itu literasi keluarga?", "options": ["Literasi hanya untuk kakek-nenek", "Membaca tanpa anak-anak", "Menulis hanya untuk lansia", "Orang tua dan anak belajar membaca bersama"], "answer": 3, "explain": "Literasi keluarga membantu orang tua dan anak mengembangkan keterampilan membaca bersama-sama.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Apa itu kesenjangan membaca antarnegara?", "options": ["Perbedaan tingkat kemampuan membaca antarnegara", "Ruang di antara buku di rak", "Jarak di antara meja sekolah", "Jarak antara dua sekolah"], "answer": 0, "explain": "Kesenjangan membaca menunjukkan seberapa besar perbedaan tingkat membaca antartempat.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Apa itu kelancaran menulis?", "options": ["Menulis tanpa kata-kata", "Menulis dengan jelas dan cepat", "Menulis hanya dengan huruf kapital", "Menulis hanya dengan komputer"], "answer": 1, "explain": "Kelancaran menulis berarti menulis cukup lancar untuk menyampaikan gagasan.", "src": "UNESCO"}, {"ch": 10, "q": "Apa itu bahasa lisan?", "options": ["Bahasa tulis saja", "Bahasa yang hanya digunakan dalam buku", "Bahasa yang diucapkan", "Bahasa yang hanya digunakan oleh hewan"], "answer": 2, "explain": "Bahasa lisan adalah bahasa ucapan yang pertama kali dipelajari anak.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Mengapa bahasa lisan penting sebelum membaca?", "options": ["Itu tidak berhubungan dengan membaca", "Itu menghentikan anak membaca", "Itu hanya untuk bernyanyi", "Itu membangun kosakata yang mendukung membaca"], "answer": 3, "explain": "Bahasa lisan yang kuat membantu anak memahami apa yang mereka baca.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Apa tujuan Hari Literasi Internasional?", "options": ["Meningkatkan kesadaran tentang literasi dan manfaatnya", "Menutup semua perpustakaan di negeri ini", "Menjual lebih banyak buku di toko-toko di seluruh negeri", "Menghentikan semua pelajaran membaca di sekolah dasar"], "answer": 0, "explain": "Hari Literasi Internasional meningkatkan kesadaran tentang literasi dan apa yang dimungkinkannya.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "Apa yang diminta pendidikan inklusif dari guru?", "options": ["Hanya mengajar siswa terbaik", "Menyesuaikan pelajaran bagi peserta didik yang berbeda-beda", "Mengabaikan peserta didik yang butuh bantuan", "Menolak pelatihan tambahan"], "answer": 1, "explain": "Pengajaran inklusif menyesuaikan metode agar setiap peserta didik dapat berpartisipasi.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu desain universal untuk pembelajaran?", "options": ["Desain gedung sekolah tanpa ruang kelas sama sekali", "Pengajaran yang hanya menggunakan satu cara untuk setiap peserta didik", "Pengajaran yang dirancang agar cocok bagi banyak jenis peserta didik", "Jenis seragam sekolah yang dikenakan semua murid setiap hari"], "answer": 2, "explain": "Desain universal untuk pembelajaran menawarkan berbagai cara untuk belajar dan menunjukkan pemahaman.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Mengapa peserta didik penyandang disabilitas memerlukan akomodasi yang layak?", "options": ["Untuk menghindari pekerjaan", "Untuk menghindari ujian", "Untuk berlibur", "Agar dapat berpartisipasi setara dalam pelajaran"], "answer": 3, "explain": "Akomodasi memungkinkan peserta didik penyandang disabilitas berpartisipasi secara setara.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa yang dilakukan juru bahasa isyarat di kelas?", "options": ["Menerjemahkan antara bahasa isyarat dan bahasa lisan", "Mengajarkan tari dan musik kepada seluruh kelas", "Menjual buku dan alat tulis kepada siswa", "Mengemudikan bus sekolah pada rute pagi"], "answer": 0, "explain": "Juru bahasa membantu peserta didik tuli mengikuti pelajaran.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa yang dibantu Braille bagi peserta didik?", "options": ["Mendengar musik", "Membaca dengan sentuhan", "Berenang lebih cepat", "Tumbuh lebih tinggi"], "answer": 1, "explain": "Braille memungkinkan penyandang tunanetra membaca dengan menyentuh titik-titik timbul.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Mengapa inklusi bermanfaat bagi semua orang di sekolah?", "options": ["Itu membuat kelas lebih kecil tanpa alasan", "Itu mengurangi pembelajaran", "Itu membangun pemahaman dan rasa hormat", "Itu menghentikan pertemanan"], "answer": 2, "explain": "Kelas inklusif mengajarkan rasa hormat dan pengertian di antara semua peserta didik.", "src": "UN CRPD (2006), Article 24"}], "8": [{"ch": 0, "q": "Berapa banyak target SDG 4 yang membahas cara pelaksanaan?", "options": ["Tiga", "Tujuh", "Sepuluh", "Empat"], "answer": 0, "explain": "Target 4.a sampai 4.c adalah tiga cara pelaksanaan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa isi Target 4.c?", "options": ["Membangun lapangan olahraga baru", "Meningkatkan ketersediaan guru yang berkualifikasi", "Memberikan buku gratis kepada orang dewasa", "Membuat sekolah lebih kecil"], "answer": 1, "explain": "Target 4.c menyerukan lebih banyak guru yang berkualifikasi, termasuk melalui pelatihan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Target manakah yang berfokus pada pembangunan berkelanjutan dan kewarganegaraan global?", "options": ["Target 4.1", "Target 4.2", "Target 4.7", "Target 4.b"], "answer": 2, "explain": "Target 4.7 mencakup pengetahuan untuk pembangunan berkelanjutan dan kewarganegaraan global.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa yang menjadi fokus indikator kemahiran?", "options": ["Berapa banyak gedung yang dimiliki sekolah", "Berapa banyak libur dalam setahun", "Seberapa tinggi peserta didik", "Apakah peserta didik mencapai tingkat tertentu dalam keterampilan kunci"], "answer": 3, "explain": "Indikator kemahiran memeriksa apakah peserta didik mencapai tingkat tertentu dalam keterampilan seperti membaca dan matematika.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Apa arti memilah data menurut jenis kelamin, usia, dan disabilitas?", "options": ["Memecah data menurut masing-masing kelompok", "Menyimpan data sebagai rahasia", "Mengumpulkan data hanya dari laki-laki", "Mengumpulkan data hanya tentang gedung"], "answer": 0, "explain": "Pemilahan data menunjukkan apakah kemajuan menjangkau setiap kelompok.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Tujuan manakah yang membahas pengurangan ketimpangan?", "options": ["Tujuan 6", "Tujuan 10", "Tujuan 13", "Tujuan 15"], "answer": 1, "explain": "Tujuan 10 adalah Pengurangan Ketimpangan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Apa itu angka anak tidak bersekolah?", "options": ["Proporsi siswa yang melewatkan makan siang", "Proporsi sekolah yang tidak punya atap", "Proporsi anak usia sekolah yang tidak bersekolah", "Proporsi guru yang sedang cuti"], "answer": 2, "explain": "Angka anak tidak bersekolah mengukur anak usia sekolah yang tidak terdaftar.", "src": "UNESCO"}, {"ch": 1, "q": "Apa yang membuat sekolah mudah dijangkau dari segi jarak?", "options": ["Jauh dari semua rumah", "Hanya bisa dicapai dengan pesawat", "Tutup pada hari kerja", "Berada dalam jarak yang aman dari rumah anak-anak"], "answer": 3, "explain": "Mudah dijangkau berarti anak-anak dapat sampai ke sekolah dengan aman dan teratur.", "src": "UNESCO"}, {"ch": 1, "q": "Biaya apa yang sering tersembunyi bagi keluarga miskin?", "options": ["Hilangnya penghasilan dari pekerjaan anak", "Buku latihan gratis", "Makan siang sekolah gratis", "Transportasi gratis"], "answer": 0, "explain": "Keluarga miskin dapat kehilangan penghasilan ketika anak bersekolah dan bukan bekerja.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa itu tantangan jarak terakhir dalam pendidikan?", "options": ["Berlari dalam perlombaan terpanjang", "Menjangkau anak-anak yang paling terpencil", "Mengikuti ujian terakhir", "Menutup sekolah terakhir"], "answer": 1, "explain": "Tantangan jarak terakhir berfokus pada menjangkau anak-anak yang paling sulit dijangkau.", "src": "UNESCO"}, {"ch": 1, "q": "Mengapa pemerintah memantau data pendaftaran?", "options": ["Untuk memilih warna sekolah", "Untuk memeringkat siswa berdasarkan tinggi badan", "Untuk merencanakan guru, gedung, dan tempat belajar", "Untuk memilih tanggal libur"], "answer": 2, "explain": "Data pendaftaran membantu pemerintah merencanakan guru, ruang kelas, dan transportasi.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Apa yang diukur oleh angka transisi?", "options": ["Kecepatan bus sekolah di jalan utama", "Jumlah bel sekolah yang dibunyikan dalam sehari penuh", "Harga buku tulis dan pulpen yang dijual di kantin", "Proporsi siswa yang naik dari satu jenjang ke jenjang berikutnya"], "answer": 3, "explain": "Angka transisi menunjukkan berapa banyak siswa yang naik ke jenjang berikutnya.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa sebagian siswa gagal masuk ke pendidikan menengah?", "options": ["Biaya, jarak, dan lemahnya pembelajaran sebelumnya", "Pendidikan menengah selalu gratis", "Pendidikan menengah tidak punya aturan masuk", "Siswa terlalu tinggi"], "answer": 0, "explain": "Biaya, jarak, dan kesenjangan pembelajaran dasar dapat menghalangi siswa untuk naik jenjang.", "src": "UNESCO"}, {"ch": 2, "q": "Apa arti penyelesaian pendidikan menengah atas?", "options": ["Menyelesaikan tahun pertama taman kanak-kanak", "Menyelesaikan tahap akhir pendidikan menengah", "Menyelesaikan kursus olahraga", "Menyelesaikan perkemahan liburan"], "answer": 1, "explain": "Penyelesaian pendidikan menengah atas berarti menuntaskan tahap akhir pendidikan menengah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Kelompok mana yang paling mungkin menghadapi beberapa hambatan penyelesaian sekaligus?", "options": ["Anak laki-laki dari keluarga kaya di perkotaan", "Anak-anak tanpa hambatan sama sekali", "Anak perempuan dari keluarga miskin dan pedesaan yang penyandang disabilitas", "Hanya orang dewasa"], "answer": 2, "explain": "Kerentanan yang saling tumpang tindih membuat penyelesaian lebih sulit bagi sebagian peserta didik.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apa itu jalur pembelajaran alternatif?", "options": ["Jalan menuju kualifikasi tanpa ujian tertulis sama sekali", "Jalan yang hanya terbuka bagi guru berkualifikasi", "Jalan yang membuat peserta didik berhenti menyelesaikan studi", "Jalan menuju kualifikasi yang sama melalui jalur berbeda"], "answer": 3, "explain": "Jalur alternatif memungkinkan peserta didik meraih kualifikasi dengan cara yang fleksibel.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu sistem peringatan dini di sekolah?", "options": ["Mengenali peserta didik yang berisiko putus sekolah agar bantuan dapat dimulai lebih awal", "Memperingatkan siswa tentang ujian akhir di penghujung tahun", "Membunyikan alarm keras saat makan siang untuk memanggil murid masuk", "Membunyikan bel sekolah lebih keras dan lebih lama untuk upacara"], "answer": 0, "explain": "Sistem peringatan dini menandai masalah kehadiran dan pembelajaran agar sekolah dapat bertindak.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu penilaian pembelajaran internasional?", "options": ["Kompetisi olahraga sekolah", "Tes yang membandingkan pembelajaran antarnegara", "Tes perekrutan guru", "Rencana anggaran pemerintah"], "answer": 1, "explain": "Penilaian internasional seperti PISA, TIMSS, dan PIRLS membandingkan pembelajaran antarnegara.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu PISA?", "options": ["Sistem bus sekolah untuk anak-anak di pedesaan", "Sejenis seragam sekolah yang dipakai murid di kota", "Tes keterampilan membaca, matematika, dan sains bagi anak berusia 15 tahun", "Turnamen olahraga global untuk atlet muda setiap tahun"], "answer": 2, "explain": "PISA adalah tes OECD bagi anak berusia 15 tahun dalam membaca, matematika, dan sains.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Mengapa penilaian pembelajaran perlu dirancang dengan cermat?", "options": ["Agar tes tidak pernah diperlukan", "Agar tesnya lebih panjang", "Agar siswa tidak pernah melihatnya", "Agar pengukurannya adil lintas bahasa dan budaya"], "answer": 3, "explain": "Penilaian yang baik dirancang agar adil dan dapat dibandingkan antarkelompok.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu krisis pembelajaran?", "options": ["Banyak anak bersekolah tetapi tidak belajar", "Anak-anak belajar terlalu cepat", "Sekolah punya terlalu banyak buku", "Anak-anak tidak pernah bersekolah"], "answer": 0, "explain": "Krisis pembelajaran menggambarkan anak yang bersekolah tetapi tidak memperoleh keterampilan dasar.", "src": "World Bank, learning poverty"}, {"ch": 3, "q": "Apa itu penilaian membaca di kelas awal?", "options": ["Tes khusus orang dewasa, digelar setelah jam kerja", "Tes membaca pada tahun-tahun pertama sekolah", "Tes keterampilan olahraga untuk tim sepak bola sekolah", "Tes keterampilan memasak untuk peserta didik muda di rumah"], "answer": 1, "explain": "Penilaian membaca kelas awal memeriksa apakah anak-anak kecil sedang belajar membaca.", "src": "UNESCO"}, {"ch": 3, "q": "Bagaimana pemahaman membantu peserta didik dalam soal cerita matematika?", "options": ["Menebak jawaban tanpa membaca", "Melewati soal", "Memahami apa yang diminta soal", "Menyontek dari teman"], "answer": 2, "explain": "Pemahaman membantu peserta didik memahami soal sebelum menyelesaikannya.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu literasi data?", "options": ["Mengumpulkan data tentang hewan peliharaan", "Menyembunyikan data dari orang lain", "Menyimpan data hanya di atas kertas", "Membaca, memahami, dan menggunakan data"], "answer": 3, "explain": "Literasi data berarti memahami dan menggunakan data untuk mengambil keputusan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Mengapa peserta didik perlu memahami kecerdasan buatan?", "options": ["Untuk menggunakannya dengan bijak dan memahami batasannya", "Untuk menggantikan semua guru", "Untuk berhenti menggunakan komputer", "Untuk menghindari semua teknologi"], "answer": 0, "explain": "Peserta didik perlu menggunakan alat AI secara bertanggung jawab dan memahami apa yang bisa dan tidak bisa dilakukannya.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu pola pikir kewirausahaan?", "options": ["Menghindari semua risiko dan selalu tinggal di satu tempat", "Melihat peluang dan mengambil risiko yang masuk akal", "Hanya bekerja untuk orang lain dan tidak pernah untuk diri sendiri", "Tidak pernah mencoba hal atau gagasan baru dalam hidup"], "answer": 1, "explain": "Pola pikir kewirausahaan berarti menyadari peluang dan bertindak atasnya secara bertanggung jawab.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu keterampilan lunak (soft skills)?", "options": ["Keterampilan mengangkat benda berat", "Keterampilan khusus membuat roti", "Keterampilan seperti kerja sama tim, empati, dan komunikasi", "Keterampilan untuk tidur"], "answer": 2, "explain": "Keterampilan lunak membantu orang bekerja dan hidup dengan baik bersama orang lain.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu pembelajaran sepanjang hayat?", "options": ["Belajar hanya sampai usia sepuluh tahun", "Belajar hanya di universitas", "Belajar hanya pada hari Minggu", "Belajar sepanjang hidup, tidak hanya di sekolah"], "answer": 3, "explain": "Pembelajaran sepanjang hayat berarti terus belajar sepanjang hidup.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Mengapa pembelajaran sepanjang hayat penting untuk pekerjaan?", "options": ["Pekerjaan berubah, jadi orang butuh keterampilan baru", "Pekerjaan tidak pernah berubah", "Belajar tidak berguna setelah sekolah", "Pekerjaan tidak membutuhkan keterampilan"], "answer": 0, "explain": "Teknologi dan industri baru membuat orang terus mempelajari keterampilan baru.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa arti belajar cara belajar?", "options": ["Tidak menghafal apa pun dan berharap tetap lulus", "Mengetahui cara belajar terbaik dan merencanakan pembelajaran", "Menyalin jawaban dengan cepat dari buku teman sekelas", "Tidak pernah bertanya di kelas maupun di rumah"], "answer": 1, "explain": "Belajar cara belajar membantu orang menjadi pembelajar yang mandiri.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa itu interseksionalitas dalam pendidikan?", "options": ["Sejenis gedung sekolah dengan banyak lantai dan ruangan", "Sejenis jadwal sekolah yang dipakai di semua kelas", "Bagaimana identitas yang saling tumpang tindih dapat memperbesar kerugian", "Cara membagi kelas berdasarkan tinggi badan setiap anak"], "answer": 2, "explain": "Interseksionalitas mengakui bahwa gender, kemiskinan, disabilitas, dan faktor lain dapat saling tumpang tindih.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa tujuan pendidikan yang mengubah norma gender?", "options": ["Mempertahankan norma gender tanpa perubahan", "Hanya mengajar satu gender", "Mengabaikan gender dalam setiap mata pelajaran", "Mengubah norma gender yang merugikan"], "answer": 3, "explain": "Pendidikan transformatif gender menantang stereotip dan peran yang tidak setara.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Mengapa sebagian anak perempuan lebih berisiko putus sekolah saat terjadi konflik?", "options": ["Ketidakamanan, pengungsian, dan kekerasan berbasis gender", "Anak perempuan selalu lebih aman", "Konflik tidak berpengaruh pada sekolah", "Anak perempuan lebih menyukai konflik"], "answer": 0, "explain": "Konflik dapat meningkatkan risiko seperti pengungsian dan kekerasan, yang mendorong anak perempuan keluar dari sekolah.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa yang membantu mencegah kekerasan berbasis gender di sekolah?", "options": ["Menyembunyikan insiden dari orang tua dan publik", "Kebijakan, kode etik, dan pelatihan", "Menyalahkan korban atas apa yang menimpa mereka", "Mengabaikan setiap laporan yang diterima sekolah"], "answer": 1, "explain": "Pencegahan mencakup kode etik yang jelas, pelatihan, dan sistem pelaporan.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa itu partisipasi yang setara di dalam kelas?", "options": ["Hanya peserta didik yang paling lantang yang berbicara", "Hanya anak laki-laki yang berbicara di kelas", "Semua peserta didik dapat ikut serta dan didengar", "Hanya guru yang berbicara"], "answer": 2, "explain": "Partisipasi yang setara berarti setiap peserta didik memiliki kesempatan yang adil untuk berkontribusi.", "src": "UNESCO"}, {"ch": 5, "q": "Apa itu bahasa diskriminatif di sekolah?", "options": ["Kata-kata yang memuji kerja keras", "Kata-kata yang menjelaskan pelajaran", "Kata-kata yang menggambarkan cuaca", "Kata-kata yang merendahkan orang berdasarkan siapa mereka"], "answer": 3, "explain": "Bahasa diskriminatif merugikan peserta didik dan menciptakan lingkungan yang tidak aman.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa arti stigma bagi peserta didik?", "options": ["Penilaian negatif yang mengucilkan orang", "Sejenis hadiah sekolah", "Sejenis seragam sekolah", "Bentuk pujian"], "answer": 0, "explain": "Stigma membuat orang diperlakukan tidak adil, yang dapat menghalangi mereka untuk belajar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Apa itu standar profesional guru?", "options": ["Daftar libur guru", "Harapan tentang apa yang harus diketahui dan dilakukan guru", "Daftar camilan sekolah", "Hanya daftar gaji guru"], "answer": 1, "explain": "Standar profesional menggambarkan seperti apa pengajaran yang baik.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa perekrutan guru menjadi tantangan kebijakan?", "options": ["Perlu mempekerjakan hanya kerabat", "Tidak perlu perencanaan sama sekali", "Perlu menarik dan memilih orang yang cakap", "Perlu menutup sekolah"], "answer": 2, "explain": "Perekrutan yang baik menemukan orang yang cakap dan menempatkan mereka di tempat yang dibutuhkan.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu penempatan guru?", "options": ["Mengirim guru berlibur", "Mengirim guru hanya ke negara lain", "Mengeluarkan guru dari sekolah", "Menempatkan guru di tempat yang dibutuhkan"], "answer": 3, "explain": "Penempatan berarti mengalokasikan guru ke sekolah dan wilayah yang paling membutuhkan.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu retensi guru?", "options": ["Mempertahankan guru dalam profesi", "Menjaga guru tetap mengajar tanpa istirahat", "Mencegah peserta didik menjadi guru", "Menjauhkan guru dari anak-anak"], "answer": 0, "explain": "Strategi retensi mempertahankan guru terlatih di pekerjaan mereka.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa guru perlu memiliki otonomi tertentu?", "options": ["Untuk menghindari semua aturan", "Untuk menyesuaikan pelajaran dengan peserta didik mereka", "Untuk tidak mengajar apa pun", "Untuk bekerja tanpa dukungan"], "answer": 1, "explain": "Otonomi tertentu membantu guru menyesuaikan pelajaran dengan kebutuhan nyata di kelas.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu serikat guru?", "options": ["Kelompok yang menutup sekolah", "Kelompok yang menjual buku teks", "Organisasi yang mewakili kepentingan guru", "Kelompok yang menentukan tanggal ujian sendirian"], "answer": 2, "explain": "Serikat guru mewakili guru dalam pembicaraan tentang gaji dan kondisi kerja.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu ketidakhadiran guru?", "options": ["Guru yang mengikuti pelatihan", "Guru yang membantu klub", "Guru yang membaca buku", "Guru yang tidak masuk kerja tanpa alasan yang baik"], "answer": 3, "explain": "Ketidakhadiran mengurangi waktu belajar, sehingga menjadi perhatian kebijakan.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa dampak kesejahteraan guru?", "options": ["Seberapa baik guru mengajar dan bertahan dalam pekerjaannya", "Hanya harga bus sekolah", "Hanya cuaca", "Tidak ada yang penting"], "answer": 0, "explain": "Kesejahteraan guru memengaruhi kualitas pengajaran dan retensi.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Apa itu transparansi anggaran dalam pendidikan?", "options": ["Menyembunyikan pengeluaran dari publik", "Mengumumkan bagaimana dana pendidikan dibelanjakan", "Membelanjakan uang secara diam-diam", "Mengabaikan anggaran"], "answer": 1, "explain": "Transparansi memungkinkan warga memeriksa bagaimana dana pendidikan digunakan.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu pembiayaan terarah untuk pendidikan?", "options": ["Dana yang sama untuk setiap sekolah tanpa memandang kebutuhan", "Dana yang hanya dibelanjakan untuk olahraga, permainan, dan karyawisata sekolah", "Dana tambahan untuk sekolah atau peserta didik dengan kebutuhan terbesar", "Dana yang hanya dikirim ke sekolah yang sudah sangat kaya"], "answer": 2, "explain": "Pembiayaan terarah mengalokasikan lebih banyak sumber daya ke tempat kebutuhannya paling besar.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "Apa itu efisiensi dalam belanja sekolah?", "options": ["Membelanjakan uang sebanyak mungkin", "Membelanjakan untuk hal yang paling kurang berguna", "Hanya membelanjakan untuk gedung", "Mendapatkan pembelajaran terbaik dari uang yang dibelanjakan"], "answer": 3, "explain": "Belanja yang efisien menghasilkan hasil belajar yang lebih baik dengan jumlah uang yang sama.", "src": "UNESCO"}, {"ch": 7, "q": "Mengapa banyak negara membiayai sekolah melalui pajak daerah?", "options": ["Agar masyarakat setempat punya suara dalam belanja", "Pajak daerah itu ilegal", "Pajak daerah menggantikan semua uang pemerintah", "Pajak daerah hanya untuk olahraga"], "answer": 0, "explain": "Pembiayaan daerah dapat membuat sekolah lebih responsif, meski juga dapat memperbesar ketimpangan.", "src": "UNESCO"}, {"ch": 7, "q": "Apa risiko hanya mengandalkan pajak daerah?", "options": ["Daerah yang lebih miskin selalu mendapat lebih banyak uang", "Daerah yang lebih kaya mungkin dapat membiayai sekolahnya lebih baik", "Sekolah tidak pernah membutuhkan uang", "Pajak daerah selalu mengakhiri ketimpangan"], "answer": 1, "explain": "Hanya mengandalkan pajak daerah dapat memperlebar kesenjangan antara daerah kaya dan miskin.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "Apa itu anggaran modal untuk sekolah?", "options": ["Dana hanya untuk gaji guru", "Dana untuk libur", "Dana untuk gedung dan peralatan", "Dana hanya untuk seragam sekolah"], "answer": 2, "explain": "Anggaran modal membiayai aset jangka panjang seperti gedung dan peralatan.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu anggaran rutin untuk sekolah?", "options": ["Dana untuk membangun satu sekolah baru", "Dana untuk satu ujian", "Dana untuk acara olahraga sekali saja", "Dana untuk biaya operasional sehari-hari seperti gaji"], "answer": 3, "explain": "Anggaran rutin menutup biaya berkelanjutan seperti gaji guru dan bahan ajar.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu biaya satuan dalam pendidikan?", "options": ["Biaya untuk mendidik satu siswa selama setahun", "Biaya satu bus sekolah", "Biaya satu seragam sekolah lengkap", "Biaya satu lembar soal ujian saja"], "answer": 0, "explain": "Biaya satuan membantu pemerintah merencanakan berapa banyak uang yang dibutuhkan setiap peserta didik.", "src": "UNESCO"}, {"ch": 8, "q": "Pada tahun berapa Forum Pendidikan Dunia bertemu di Incheon?", "options": ["1990", "2015", "2000", "2030"], "answer": 1, "explain": "Forum Pendidikan Dunia diselenggarakan di Incheon, Republik Korea, pada 2015.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Di mana Forum Pendidikan Dunia 2015 diselenggarakan?", "options": ["Dakar, Senegal", "Jomtien, Thailand", "Incheon, Republik Korea", "Paris, Prancis"], "answer": 2, "explain": "Incheon di Republik Korea menjadi tuan rumah forum 2015.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Di mana Forum Pendidikan Dunia 2000 diselenggarakan?", "options": ["Incheon, Republik Korea", "Jomtien, Thailand", "Nairobi, Kenya", "Dakar, Senegal"], "answer": 3, "explain": "Forum Dakar tahun 2000 mengadopsi Kerangka Aksi Dakar.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Apa yang dicakup Pasal 26 Deklarasi Universal Hak Asasi Manusia?", "options": ["Hak atas pendidikan", "Hak atas mobil", "Hak atas liburan", "Hak untuk memilih di sekolah"], "answer": 0, "explain": "Pasal 26 menetapkan hak atas pendidikan.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Apa yang menjadi landasan Pendidikan 2030?", "options": ["Hanya Olimpiade dan aturan untuk atlet", "Tujuan Pembangunan Milenium dan Pendidikan untuk Semua", "Hanya eksplorasi luar angkasa dan studi roket", "Hanya aturan olahraga dan hasil turnamen sepak bola"], "answer": 1, "explain": "Pendidikan 2030 dibangun di atas komitmen pendidikan global sebelumnya.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "Mengapa dunia beralih dari MDG ke SDG?", "options": ["Untuk membatalkan semua tujuan pendidikan untuk dekade berikutnya", "Untuk fokus pada satu negara dan mengabaikan yang lain", "Untuk mencakup rentang isu yang lebih luas bagi semua negara", "Untuk menghapus setiap target yang telah ditetapkan negara-negara"], "answer": 2, "explain": "SDG bersifat universal dan mencakup lebih banyak isu daripada MDG.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Periode apa yang dicakup MDG?", "options": ["1990 sampai 2000", "2015 sampai 2030", "2000 sampai 2030", "2000 sampai 2015"], "answer": 3, "explain": "MDG berlangsung dari 2000 sampai 2015.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "Apa itu pengasuhan yang responsif?", "options": ["Orang dewasa merespons sinyal anak dengan hangat dan tepat", "Mengabaikan sinyal anak dan membiarkannya menangis", "Hanya memberi perintah dan tidak pernah mendengarkan anak", "Memisahkan anak dari orang dewasa dalam semua keadaan"], "answer": 0, "explain": "Pengasuhan yang responsif membangun kepercayaan dan mendukung pembelajaran.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa kesehatan anak penting bagi pembelajaran?", "options": ["Kesehatan tidak berpengaruh pada pembelajaran", "Penyakit dan kelaparan dapat menghentikan anak belajar", "Hanya olahraga yang membutuhkan kesehatan", "Anak yang sehat tidak pernah membutuhkan sekolah"], "answer": 1, "explain": "Kesehatan dan gizi yang baik membantu anak belajar dan berkonsentrasi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Apa itu stunting?", "options": ["Tumbuh sangat cepat dan menjadi jauh lebih tinggi dari sebagian besar teman sebaya", "Aturan disiplin sekolah tentang seragam, rambut, dan sepatu untuk semua", "Jauh lebih pendek dari yang diharapkan untuk usianya akibat gizi buruk", "Sangat tinggi untuk usianya dan tumbuh lebih cepat dari sebagian besar teman sebaya"], "answer": 2, "explain": "Stunting adalah tanda kekurangan gizi kronis dan dapat memengaruhi pembelajaran.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Apa itu stimulasi dini?", "options": ["Membiarkan bayi dalam keheningan total selama berjam-jam setiap hari", "Hanya memberi balita permen dan camilan di setiap waktu makan", "Membiarkan bayi di ruangan gelap hampir sepanjang hari", "Kegiatan yang merangsang indera dan daya pikir bayi"], "answer": 3, "explain": "Stimulasi dini mencakup berbicara, bernyanyi, sentuhan, dan bermain.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa layanan anak usia dini memerlukan staf terlatih?", "options": ["Staf terlatih paling baik mendukung perkembangan anak", "Staf tidak diperlukan", "Pelatihan adalah pemborosan uang", "Staf terlatih membuat anak berhenti belajar"], "answer": 0, "explain": "Staf anak usia dini yang terlatih dengan baik memahami cara anak kecil belajar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Apa itu program transisi dari anak usia dini ke sekolah dasar?", "options": ["Jembatan di atas sungai", "Program yang membantu anak menyesuaikan diri", "Jalan untuk bus sekolah", "Lapangan olahraga"], "answer": 1, "explain": "Program transisi membantu anak kecil beradaptasi di sekolah dasar.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Apa itu kesadaran fonemik?", "options": ["Mengetahui nama-nama warna", "Menulis dengan huruf kapital saja", "Menyadari bunyi dalam kata yang diucapkan", "Membaca bagian belakang buku"], "answer": 2, "explain": "Kesadaran fonemik membantu anak menghubungkan bunyi dengan huruf.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Apa itu kosakata dalam membaca dini?", "options": ["Harga buku", "Jumlah halaman", "Ukuran huruf", "Kata-kata yang diketahui dan digunakan anak"], "answer": 3, "explain": "Kosakata yang kuat membantu anak memahami apa yang mereka baca.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Apa itu pendidikan dasar orang dewasa?", "options": ["Membaca, menulis, dan berhitung dasar bagi orang dewasa", "Studi lanjutan di universitas dalam fisika dan hukum", "Pelatihan olahraga untuk tim sepak bola setempat", "Kursus mengemudi bagi orang dewasa yang ingin SIM"], "answer": 0, "explain": "Pendidikan dasar orang dewasa membantu orang dewasa mempelajari literasi dan numerasi yang esensial.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Apa itu lingkungan yang kaya bahan cetak?", "options": ["Tempat tanpa kata cetak sama sekali", "Tempat dengan banyak kata cetak untuk dibaca", "Tempat di mana semua buku dikunci", "Tempat yang hanya berisi gambar"], "answer": 1, "explain": "Lingkungan kaya bahan cetak memperkenalkan anak pada huruf dan kata dalam kehidupan sehari-hari.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Mengapa daerah pedesaan sering memiliki tingkat literasi yang lebih rendah?", "options": ["Orang pedesaan tidak pernah membaca", "Secara hukum, literasi tidak diajarkan di daerah pedesaan", "Sekolah, buku, dan tempat membaca lebih sedikit dan jauh", "Orang pedesaan tidak membutuhkan membaca"], "answer": 2, "explain": "Banyak negara menunjukkan literasi yang lebih rendah di pedesaan, tempat sekolah dan buku lebih sulit dijangkau.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Mengapa membaca untuk kesenangan itu penting?", "options": ["Itu membuang waktu", "Itu hanya untuk guru", "Itu membuat anak berhenti membaca di kemudian hari", "Itu membangun kebiasaan membaca dan pengetahuan yang lebih luas"], "answer": 3, "explain": "Membaca untuk kesenangan membangun kebiasaan yang mendukung pembelajaran sepanjang hayat.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "Apa yang didorong oleh desain universal untuk pembelajaran?", "options": ["Beragam cara untuk menyajikan, melibatkan, dan menilai pembelajaran", "Satu cara mengajar yang harus diikuti setiap peserta didik", "Menghapus semua penilaian dari tahun ajaran", "Mengajar hanya dalam keheningan tanpa diskusi sama sekali"], "answer": 0, "explain": "Desain universal menawarkan pilihan agar peserta didik dapat mengakses dan menunjukkan pembelajaran mereka.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu rencana dukungan belajar?", "options": ["Rencana libur sekolah untuk semua siswa", "Rencana yang menetapkan dukungan bagi kebutuhan seorang peserta didik", "Rencana untuk mengakhiri pelajaran lebih awal setiap hari", "Rencana untuk mengeluarkan sebagian peserta didik dari sekolah"], "answer": 1, "explain": "Rencana dukungan belajar menetapkan penyesuaian dan bantuan bagi peserta didik secara individu.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Mengapa keluarga peserta didik penyandang disabilitas perlu dilibatkan?", "options": ["Keluarga tidak perlu dilibatkan", "Keluarga hanya membayar biaya", "Mereka paling tahu kebutuhan peserta didik", "Keluarga menimbulkan masalah"], "answer": 2, "explain": "Keluarga memberikan pengetahuan yang membantu sekolah mendukung peserta didik.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu penilaian inklusif?", "options": ["Tes yang hanya bisa dilewati oleh yang terbaik", "Tes yang tidak pernah diberikan", "Tes yang hanya mengukur kecepatan", "Tes yang memungkinkan semua peserta didik menunjukkan apa yang mereka ketahui"], "answer": 3, "explain": "Penilaian inklusif menyesuaikan cara pembelajaran ditunjukkan agar semua peserta didik dapat memperlihatkannya.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu dukungan teman sebaya di sekolah inklusif?", "options": ["Teman sekelas yang saling membantu belajar", "Teman sekelas yang bersaing untuk mengucilkan orang lain", "Teman sekelas yang hanya bekerja sendiri", "Teman sekelas yang saling menghindar"], "answer": 0, "explain": "Dukungan teman sebaya membantu peserta didik merasa diterima dan belajar bersama.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Mengapa sekolah inklusif mengurangi diskriminasi?", "options": ["Mereka memisahkan anak berdasarkan kemampuan", "Mereka mengajarkan rasa hormat dan membuat perbedaan menjadi hal yang wajar", "Mereka menghapus semua keberagaman", "Mereka meningkatkan ketakutan"], "answer": 1, "explain": "Ketika anak-anak belajar bersama, mereka membangun rasa hormat dan pengertian.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu segregasi di sekolah?", "options": ["Menyatukan semua anak di kelas yang sama setiap hari", "Membagi buku dan bahan ajar secara merata di antara murid", "Memisahkan anak berdasarkan disabilitas, gender, atau latar belakang", "Memberi semua orang giliran yang adil di halaman bermain"], "answer": 2, "explain": "Segregasi memisahkan peserta didik secara tidak adil dan ditentang oleh pendidikan inklusif.", "src": "UN CRPD (2006), Article 24"}, {"ch": 1, "q": "Apa itu wilayah tangkapan sekolah?", "options": ["Sejenis olahraga sekolah", "Atap sebuah sekolah", "Makanan sekolah", "Wilayah yang direncanakan untuk dilayani sebuah sekolah"], "answer": 3, "explain": "Wilayah tangkapan adalah zona anak-anak yang direncanakan untuk dilayani sebuah sekolah.", "src": "UNESCO"}], "9": [{"ch": 0, "q": "Tujuan SDG manakah yang berkaitan dengan kemitraan untuk mencapai tujuan?", "options": ["Tujuan 17", "Tujuan 7", "Tujuan 12", "Tujuan 1"], "answer": 0, "explain": "Tujuan 17 adalah Kemitraan untuk Mencapai Tujuan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa yang dimaksud dengan sarana pelaksanaan?", "options": ["Nama-nama semua tujuan yang ditulis pada poster besar", "Sumber daya dan alat yang diperlukan untuk mencapai tujuan", "Tanggal rapat yang diadakan di balai kota setiap tahun", "Warna poster yang dipasang di aula sekolah"], "answer": 1, "explain": "Sarana pelaksanaan mencakup pembiayaan, teknologi, kapasitas, dan kemitraan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa masalah kesenjangan data dalam pemantauan SDG?", "options": ["Data terlalu banyak sehingga tidak ada yang bisa membacanya dengan benar", "Data hanya disimpan di atas kertas dalam lemari arsip lama", "Banyak negara tidak memiliki data yang andal untuk memantau kemajuan", "Data selalu sempurna dan tidak pernah perlu diperiksa"], "answer": 2, "explain": "Kesenjangan data menyulitkan pengukuran kemajuan dan pengenalan siapa yang tertinggal.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Mengapa SDG menggunakan indikator?", "options": ["Untuk menyusun jadwal pelajaran sekolah", "Untuk memilih lagu kebangsaan", "Untuk menggantikan guru", "Untuk mengukur kemajuan secara konsisten"], "answer": 3, "explain": "Indikator membuat kemajuan dapat dibandingkan antarnegara dan dari waktu ke waktu.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa itu Agenda 2030?", "options": ["Rencana yang disepakati pada 2015 untuk mencapai tujuan pada 2030", "Rencana untuk Olimpiade yang digelar di Paris pada 2030", "Jadwal pelajaran sekolah yang berlaku untuk setiap semester sampai 2030", "Jadwal libur untuk setiap sekolah sepanjang tahun 2030"], "answer": 0, "explain": "Agenda 2030 adalah rencana PBB yang disepakati pada 2015 untuk Tujuan Pembangunan Berkelanjutan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa fungsi rencana nasional SDG 4?", "options": ["Menutup semua sekolah", "Menetapkan cara sebuah negara akan mencapai SDG 4", "Membatalkan semua ujian", "Menghapus biaya sekolah hanya dengan keputusan"], "answer": 1, "explain": "Rencana nasional menetapkan prioritas, anggaran, dan tindakan untuk mencapai SDG 4.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Apa itu pengucilan dari sekolah?", "options": ["Mendapat hadiah", "Pindah ke sekolah baru atas pilihan sendiri", "Dikeluarkan atau tidak diterima di sekolah", "Mendapat pelajaran tambahan"], "answer": 2, "explain": "Pengucilan membuat anak tidak bisa belajar, sehingga melanggar hak atas pendidikan.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "Apa dampak pernikahan anak terhadap sekolah?", "options": ["Selalu membuat sekolah lebih baik", "Tidak berpengaruh", "Membuat sekolah menjadi gratis", "Sering menghentikan sekolah lebih awal"], "answer": 3, "explain": "Pernikahan anak merupakan penyebab utama anak perempuan putus sekolah lebih awal.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "Apa itu pengungsian yang memengaruhi pendidikan?", "options": ["Terpaksa meninggalkan rumah, yang sering mengganggu sekolah", "Memindahkan meja sekolah ke sisi lain ruangan", "Memilih sekolah baru untuk semester berikutnya setiap tahun", "Sejenis tes sekolah yang diberikan di awal semester"], "answer": 0, "explain": "Anak-anak pengungsi dapat kehilangan bertahun-tahun sekolah tanpa dukungan.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa itu pendidikan pengungsi?", "options": ["Pendidikan hanya untuk guru di satu sekolah tertentu", "Pendidikan bagi anak dan kaum muda yang melarikan diri dari rumah mereka", "Pendidikan melalui olahraga dan kegiatan luar ruangan saja untuk seluruh sekolah", "Pendidikan hanya untuk orang dewasa yang kembali belajar di usia lanjut"], "answer": 1, "explain": "Pendidikan pengungsi membantu peserta didik yang terpaksa mengungsi untuk tetap belajar.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Mengapa pendidikan dalam keadaan darurat penting?", "options": ["Tidak punya nilai dalam krisis", "Hanya untuk turis", "Memberi anak rasa aman dan perlindungan", "Menggantikan semua bantuan pangan"], "answer": 2, "explain": "Sekolah dalam keadaan darurat memberi anak rasa aman, rutinitas, dan harapan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Apa itu ruang belajar sementara?", "options": ["Bangunan untuk menyimpan mobil dan mesin berat", "Toko yang menjual buku, pulpen, dan kertas kepada semua siswa", "Tempat khusus orang dewasa untuk beristirahat setiap sore", "Tempat belajar yang aman dan didirikan dengan cepat setelah krisis"], "answer": 3, "explain": "Ruang belajar sementara membuat anak tetap belajar saat sekolah permanen tidak dapat digunakan.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Jarak ke sekolah biasanya diukur dengan apa?", "options": ["Waktu atau jarak yang harus ditempuh anak", "Jumlah buku", "Warna sekolah", "Jumlah guru di kota"], "answer": 0, "explain": "Waktu tempuh dan jarak adalah ukuran akses yang umum digunakan.", "src": "UNESCO"}, {"ch": 1, "q": "Mengapa anak penyandang disabilitas sering tidak bersekolah?", "options": ["Mereka tidak mau belajar", "Sekolah tidak ramah akses dan tidak mendapat dukungan", "Mereka terlalu pintar untuk sekolah", "Mereka punya terlalu banyak mainan"], "answer": 1, "explain": "Kurangnya gedung yang mudah diakses, pengajaran, dan dukungan membuat banyak anak tidak bersekolah.", "src": "UN CRPD (2006), Article 24"}, {"ch": 2, "q": "Apa itu angka tinggal kelas?", "options": ["Proporsi siswa yang memenangkan lomba", "Proporsi siswa yang masuk sekolah lebih awal", "Proporsi siswa yang mengulang kelas", "Proporsi siswa yang belajar musik"], "answer": 2, "explain": "Angka tinggal kelas menunjukkan seberapa sering siswa mengulang kelas.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa tinggal kelas sering menjadi solusi yang buruk?", "options": ["Selalu memperbaiki pembelajaran", "Gratis untuk semua orang", "Menghapus semua kesenjangan", "Dapat meningkatkan risiko putus sekolah"], "answer": 3, "explain": "Mengulang satu tahun sering meningkatkan peluang siswa meninggalkan sekolah.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu kenaikan kelas?", "options": ["Naik ke kelas berikutnya", "Menjual seragam sekolah", "Pindah ke negara lain", "Berhenti sekolah"], "answer": 0, "explain": "Kenaikan kelas berarti siswa melanjutkan ke kelas berikutnya.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu ijazah kelulusan sekolah?", "options": ["Tiket pertandingan sepak bola besar di stadion nasional", "Dokumen yang menunjukkan siswa telah menyelesaikan suatu jenjang", "Denda untuk siswa yang sering bolos", "Peta yang menunjukkan lokasi setiap sekolah di kota"], "answer": 1, "explain": "Ijazah kelulusan mencatat penyelesaian suatu jenjang pendidikan.", "src": "UNESCO"}, {"ch": 2, "q": "Apa tujuan target penyelesaian pendidikan nasional?", "options": ["Mengurangi jumlah sekolah di seluruh negeri", "Mencegah anak naik ke jenjang berikutnya", "Meningkatkan proporsi anak yang menyelesaikan setiap jenjang", "Memberi lebih sedikit ujian kepada seluruh siswa di sekolah"], "answer": 2, "explain": "Target nasional berfokus pada membantu lebih banyak anak menyelesaikan setiap jenjang.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apa itu sertifikasi keterampilan?", "options": ["Sejenis tas sekolah dengan banyak kantong kecil", "Jadwal liburan keluarga setiap musim panas", "Resep masakan untuk makan malam keluarga yang istimewa", "Pengakuan resmi atas keterampilan yang dimiliki seseorang"], "answer": 3, "explain": "Sertifikasi menunjukkan kepada pemberi kerja dan pihak lain bahwa seseorang memiliki keterampilan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apa itu pengakuan pembelajaran sebelumnya?", "options": ["Pemberian kredit atas pembelajaran yang sudah diperoleh di luar sekolah", "Mengabaikan semua pembelajaran sebelumnya dan mulai dari nol setiap kali", "Hanya menghitung ujian yang diambil di universitas atau perguruan tinggi", "Menghapus kualifikasi yang sudah diperoleh seseorang"], "answer": 0, "explain": "Pengakuan pembelajaran sebelumnya membantu orang maju tanpa mengulang apa yang sudah mereka kuasai.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu standar pembelajaran?", "options": ["Sejenis gedung sekolah dengan banyak ruang kelas", "Pernyataan tentang apa yang harus diketahui dan dapat dilakukan peserta didik", "Sejenis bus sekolah yang beroperasi setiap pagi", "Aturan berpakaian untuk siswa dan guru"], "answer": 1, "explain": "Standar pembelajaran menjelaskan hasil yang diharapkan untuk setiap jenjang.", "src": "UNESCO"}, {"ch": 3, "q": "Apa fokus Laporan Pemantauan Pendidikan Global?", "options": ["Menjual buku pelajaran", "Memilih olahraga sekolah", "Memantau kemajuan pendidikan di seluruh dunia", "Merencanakan liburan"], "answer": 2, "explain": "Laporan GEM memantau kemajuan pendidikan dan membagikan bukti.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu profil pembelajaran?", "options": ["Foto seorang siswa", "Daftar libur sekolah", "Denah sekolah", "Catatan tentang kekuatan dan kebutuhan seorang peserta didik"], "answer": 3, "explain": "Profil pembelajaran membantu guru merencanakan dukungan untuk setiap peserta didik.", "src": "UNESCO"}, {"ch": 3, "q": "Mengapa guru menggunakan asesmen diagnostik?", "options": ["Untuk mengetahui apa yang sudah dikuasai peserta didik dan apa yang mereka butuhkan", "Untuk memberi nilai hanya di akhir setiap tahun ajaran", "Untuk menghindari mengajar seluruh kelas sepanjang hari", "Untuk menghukum anak setiap kali mereka berbuat salah"], "answer": 0, "explain": "Asesmen diagnostik membantu guru merencanakan pelajaran yang sesuai dengan kebutuhan peserta didik.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu reformasi kurikulum?", "options": ["Mengubah warna sekolah", "Mengubah apa yang diajarkan dan cara mengajarkannya", "Menutup semua sekolah", "Membatalkan semua mata pelajaran"], "answer": 1, "explain": "Reformasi kurikulum memperbarui mata pelajaran, keterampilan, dan metode pengajaran.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu pembelajaran berbasis kompetensi?", "options": ["Hanya berfokus pada menghafal fakta", "Hanya berfokus pada olahraga", "Berfokus pada apa yang dapat dilakukan peserta didik", "Hanya berfokus pada waktu yang dihabiskan di kelas"], "answer": 2, "explain": "Pembelajaran berbasis kompetensi mengukur keterampilan dan kemampuan, bukan hanya pengetahuan.", "src": "UNESCO"}, {"ch": 3, "q": "Mengapa literasi sains penting?", "options": ["Menggantikan semua keterampilan membaca dan menulis", "Hanya membantu ilmuwan di laboratorium mereka", "Sama sekali tidak berguna dalam kehidupan sehari-hari", "Membantu orang memahami dan menilai bukti"], "answer": 3, "explain": "Literasi sains membantu orang membuat keputusan yang tepat tentang kesehatan dan lingkungan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Apa itu penalaran matematika?", "options": ["Menjelaskan mengapa suatu metode berhasil", "Menebak jawabannya", "Menyalin jawabannya", "Melewatkan langkah pengerjaan"], "answer": 0, "explain": "Penalaran menunjukkan bahwa peserta didik memahami metodenya, bukan hanya jawabannya.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu peningkatan hasil belajar?", "options": ["Kenaikan berat badan", "Kemajuan yang dicapai peserta didik dalam kurun waktu tertentu", "Keuntungan dari penjualan sekolah", "Tambahan hari libur"], "answer": 1, "explain": "Peningkatan hasil belajar mengukur seberapa besar peserta didik berkembang dari waktu ke waktu.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "Apa itu keterampilan hijau?", "options": ["Keterampilan untuk mengecat dinding menjadi hijau", "Keterampilan untuk menanam rumput saja", "Keterampilan yang membantu melindungi lingkungan", "Keterampilan untuk bermain gim hijau"], "answer": 2, "explain": "Keterampilan hijau mendukung perlindungan lingkungan dan pekerjaan yang berkelanjutan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Mengapa pendidikan iklim terkait dengan Target 4.7?", "options": ["Iklim tidak berhubungan dengan pembelajaran", "Pendidikan iklim dilarang", "Pendidikan iklim menggantikan matematika", "Mendukung pendidikan untuk pembangunan berkelanjutan"], "answer": 3, "explain": "Target 4.7 mencakup pendidikan untuk pembangunan berkelanjutan, yang meliputi iklim.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu pendidikan perdamaian?", "options": ["Belajar menyelesaikan konflik tanpa kekerasan", "Belajar cara memulai konflik", "Hanya belajar sejarah perang", "Belajar cara menghindari orang"], "answer": 0, "explain": "Pendidikan perdamaian mengajarkan rasa hormat, dialog, dan anti-kekerasan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa yang diajarkan pendidikan hak asasi manusia?", "options": ["Hanya aturan permainan", "Hak dan tanggung jawab peserta didik", "Hanya sejarah kereta api", "Hanya cara memasak"], "answer": 1, "explain": "Pendidikan hak asasi manusia membantu peserta didik mengetahui dan menghormati hak.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu pendidikan kewarganegaraan?", "options": ["Hanya belajar tentang mobil", "Hanya belajar tentang pohon", "Belajar tentang kewarganegaraan dan kehidupan publik", "Hanya belajar tentang olahraga"], "answer": 2, "explain": "Pendidikan kewarganegaraan membantu peserta didik berpartisipasi secara bertanggung jawab di masyarakat.", "src": "UNESCO"}, {"ch": 4, "q": "Mengapa pemahaman lintas budaya diajarkan?", "options": ["Mencegah orang bepergian", "Membuat semua budaya sama", "Hanya untuk turis", "Membantu orang menghormati cara hidup yang berbeda"], "answer": 3, "explain": "Pemahaman lintas budaya mengurangi prasangka dan membangun rasa hormat.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu pembelajaran berbasis masalah?", "options": ["Belajar dengan memecahkan masalah nyata", "Belajar dengan menghafal daftar", "Belajar dengan menghindari pertanyaan", "Belajar hanya dengan menyalin catatan"], "answer": 0, "explain": "Pembelajaran berbasis masalah mengembangkan cara berpikir melalui tantangan nyata.", "src": "UNESCO"}, {"ch": 5, "q": "Apa arti kemiskinan dalam pendidikan?", "options": ["Terlalu banyak buku di rak kelas", "Kekurangan uang yang membatasi akses ke pembelajaran", "Terlalu banyak guru dibandingkan jumlah murid", "Terlalu banyak libur selama tahun ajaran"], "answer": 1, "explain": "Kemiskinan dapat membatasi akses ke sekolah, makanan, transportasi, dan bahan belajar.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Apa itu disparitas etnis dalam pendidikan?", "options": ["Perbedaan warna tas sekolah", "Perbedaan libur sekolah saja", "Perbedaan capaian sekolah antarkelompok etnis", "Perbedaan sepatu sekolah"], "answer": 2, "explain": "Disparitas etnis menunjukkan sebagian kelompok mencapai lebih sedikit, yang mungkin mencerminkan hambatan yang tidak adil.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Apa itu disparitas desa-kota?", "options": ["Perbedaan jumlah taman kota", "Perbedaan curah hujan", "Perbedaan seragam sekolah", "Perbedaan pembelajaran antara wilayah perdesaan dan perkotaan"], "answer": 3, "explain": "Wilayah perdesaan sering memiliki sumber daya yang lebih sedikit, yang dapat memperlebar kesenjangan belajar.", "src": "UNESCO"}, {"ch": 5, "q": "Apa yang diukur oleh kuintil kekayaan?", "options": ["Pembagian rumah tangga menjadi lima kelompok berdasarkan kekayaan", "Lima jenis bus sekolah yang digunakan di seluruh kota", "Lima cara menyusun ujian untuk satu kelas setiap tahun", "Lima warna kapur yang digunakan di setiap ruang kelas"], "answer": 0, "explain": "Kuintil kekayaan membagi keluarga menjadi lima kelompok untuk membandingkan hasil pendidikan.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Apa itu kebijakan pro-miskin dalam pendidikan?", "options": ["Kebijakan yang hanya membantu yang terkaya", "Kebijakan yang menyasar peserta didik termiskin", "Kebijakan yang menutup sekolah di daerah miskin", "Kebijakan yang menaikkan biaya bagi orang miskin"], "answer": 1, "explain": "Kebijakan pro-miskin memusatkan sumber daya pada mereka yang paling membutuhkan.", "src": "UNESCO"}, {"ch": 5, "q": "Apa itu kesetaraan kesempatan dalam pendidikan?", "options": ["Hanya peserta didik terbaik yang mendapat kesempatan", "Kesempatan bergantung pada kekayaan keluarga", "Kesempatan yang sama untuk berhasil, terlepas dari latar belakang", "Kesempatan hanya diberikan di kota"], "answer": 2, "explain": "Kesetaraan kesempatan berarti latar belakang tidak boleh menentukan apa yang dapat dicapai peserta didik.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Apa itu kesenjangan gaji guru?", "options": ["Guru dibayar lebih tinggi daripada dokter", "Guru dibayar dengan emas", "Guru tidak pernah dibayar", "Guru dibayar lebih rendah daripada profesi yang sebanding"], "answer": 3, "explain": "Kesenjangan gaji berarti guru berpenghasilan lebih rendah daripada pekerja yang sebanding, sehingga profesi ini kurang menarik.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa gaji guru penting bagi pembelajaran?", "options": ["Memengaruhi siapa yang menjadi dan tetap menjadi guru", "Tidak ada kaitannya dengan pembelajaran", "Hanya memengaruhi gedung sekolah", "Hanya memengaruhi libur"], "answer": 0, "explain": "Gaji memengaruhi apakah orang yang cakap memilih dan tetap bertahan di profesi mengajar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu lisensi mengajar?", "options": ["Izin untuk menjual makanan sekolah", "Izin resmi untuk mengajar", "Izin untuk membangun sekolah", "Izin untuk menjalankan layanan bus"], "answer": 1, "explain": "Lisensi menetapkan standar minimum bagi orang yang mengajar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu program induksi guru?", "options": ["Pelatihan untuk sopir bus sekolah", "Pelatihan untuk juru masak", "Dukungan bagi guru pada tahun-tahun pertama mereka", "Pelatihan khusus untuk orang tua"], "answer": 2, "explain": "Program induksi membantu guru baru beradaptasi dan berkembang.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu mobilitas guru?", "options": ["Guru yang bepergian dengan pesawat", "Guru yang mengikuti lomba lari", "Guru yang selamanya tinggal di satu ruangan", "Guru yang berpindah antarsekolah atau wilayah"], "answer": 3, "explain": "Mobilitas guru memengaruhi wilayah mana yang memiliki cukup guru berkualifikasi.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu keberagaman guru?", "options": ["Guru dari latar belakang yang berbeda di sekolah", "Guru yang semuanya terlihat sama", "Guru yang hanya menguasai satu bahasa", "Guru tanpa pelatihan"], "answer": 0, "explain": "Tenaga pengajar yang beragam dapat membantu siswa melihat diri mereka dalam diri gurunya.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "Apa itu kepemimpinan pembelajaran?", "options": ["Kepala sekolah yang hanya berfokus pada olahraga", "Kepala sekolah yang berfokus pada pengajaran dan pembelajaran", "Kepala sekolah yang berfokus pada libur", "Kepala sekolah yang menghindari guru"], "answer": 1, "explain": "Pemimpin pembelajaran membantu guru meningkatkan praktik di kelas.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa sekolah membutuhkan kepala sekolah?", "options": ["Mereka menggantikan guru di setiap kelas", "Mereka hanya mengajar olahraga dan pendidikan jasmani", "Mereka membimbing pengajaran dan mengelola sekolah", "Mereka tidak diperlukan di sekolah yang dikelola dengan baik"], "answer": 2, "explain": "Kepala sekolah mendukung guru dan menentukan arah pembelajaran.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Apa itu pembiayaan pendidikan yang berkelanjutan?", "options": ["Uang yang dikeluarkan sekali dan tidak pernah lagi", "Uang yang hanya berasal dari satu undian", "Uang yang hanya dibelanjakan untuk gedung", "Pendanaan yang bertahan dalam jangka panjang"], "answer": 3, "explain": "Pembiayaan berkelanjutan berarti pendanaan yang andal dan terus berlanjut selama bertahun-tahun.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Apa itu bantuan pendidikan?", "options": ["Uang atau dukungan yang diberikan oleh negara atau organisasi lain", "Uang yang diberikan guru kepada sekolahnya untuk perlengkapan", "Uang yang hanya berasal dari biaya sekolah yang dibayar orang tua", "Uang yang hanya dikumpulkan dari penjualan, bazar, dan acara sekolah"], "answer": 0, "explain": "Bantuan pendidikan berasal dari donor yang mendukung sekolah di negara lain.", "src": "UNESCO"}, {"ch": 7, "q": "Apa kepanjangan dari ODA?", "options": ["Akses Digital Resmi", "Bantuan Pembangunan Resmi", "Arsip Dokumen Terbuka", "Kehadiran Harian Daring"], "answer": 1, "explain": "ODA berarti Bantuan Pembangunan Resmi, yang mencakup bantuan untuk pendidikan.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu mobilisasi sumber daya domestik?", "options": ["Menggalang dana hanya dari negara lain", "Menggalang dana dengan menjual sekolah", "Menggalang dana di dalam negeri untuk layanan publik", "Menggalang dana dari Bulan"], "answer": 2, "explain": "Negara menggalang uang melalui pajak dan pendapatan dalam negeri lainnya untuk sekolah.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Mengapa sebagian negara bergantung pada bantuan luar negeri untuk pendidikan?", "options": ["Mereka memiliki uang yang tidak terbatas", "Mereka tidak menginginkan sekolah", "Mereka tidak bisa membelanjakan uang", "Sumber daya dalam negeri mereka terbatas"], "answer": 3, "explain": "Sumber daya dalam negeri yang terbatas dapat membuat negara bergantung pada dukungan dari luar.", "src": "UNESCO"}, {"ch": 7, "q": "Untuk apa dana pendidikan digunakan?", "options": ["Membiayai persekolahan dan program pembelajaran", "Membiayai liburan keluarga dan perjalanan musim panas", "Membeli mobil baru untuk staf sekolah", "Membayar tiket acara olahraga besar"], "answer": 0, "explain": "Dana pendidikan membiayai persekolahan, bahan ajar, dan program.", "src": "UNESCO"}, {"ch": 8, "q": "Apa hasil konferensi Jomtien tahun 1990?", "options": ["Buku aturan sepak bola untuk turnamen sekolah saja", "Deklarasi tentang pemenuhan kebutuhan belajar dasar", "Daftar libur sekolah untuk setiap tahun", "Mata uang baru yang diperkenalkan di seluruh kawasan pada tahun itu"], "answer": 1, "explain": "Deklarasi Dunia tentang Pendidikan untuk Semua diadopsi di Jomtien pada 1990.", "src": "UNESCO"}, {"ch": 8, "q": "Apa itu Deklarasi Dunia tentang Pendidikan untuk Semua?", "options": ["Rencana olahraga tahun 2030 untuk semua tim nasional", "Kode seragam sekolah yang berlaku untuk semua siswa", "Deklarasi tahun 1990 yang menjanjikan pendidikan untuk semua", "Undang-undang gaji guru yang disahkan parlemen tahun lalu"], "answer": 2, "explain": "Deklarasi itu diadopsi di Jomtien pada 1990 dan menetapkan Pendidikan untuk Semua.", "src": "UNESCO"}, {"ch": 8, "q": "Acara tahun 2000 manakah yang mengesahkan Kerangka Aksi Dakar?", "options": ["Piala Dunia sepak bola", "Olimpiade", "Konferensi tingkat tinggi perdagangan", "Forum Pendidikan Dunia"], "answer": 3, "explain": "Kerangka Aksi Dakar disepakati di Forum Pendidikan Dunia pada 2000.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Apa komitmen Deklarasi Incheon?", "options": ["Pendidikan yang inklusif, adil, dan bermutu untuk pembelajaran sepanjang hayat", "Hanya pendidikan tinggi bagi sekelompok kecil siswa terbaik", "Hanya olahraga dan permainan untuk tim sekolah setiap minggu", "Hanya libur dan hari bebas untuk semua siswa"], "answer": 0, "explain": "Deklarasi Incheon mengikat negara-negara untuk menyediakan kesempatan belajar sepanjang hayat.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Apa yang dicakup Kerangka Aksi Dakar selain persekolahan anak?", "options": ["Keaksaraan hanya untuk guru", "Keaksaraan orang dewasa dan kesetaraan gender", "Keaksaraan hanya dalam olahraga", "Keaksaraan hanya untuk negara kaya"], "answer": 1, "explain": "Kerangka Aksi Dakar mencakup tujuan keaksaraan orang dewasa dan kesetaraan gender.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Tujuan Pembangunan Milenium manakah yang bertujuan mendorong kesetaraan gender?", "options": ["Tujuan 1", "Tujuan 5", "Tujuan 3", "Tujuan 6"], "answer": 2, "explain": "MDG 3 bertujuan mendorong kesetaraan gender dan pemberdayaan perempuan.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "Apa yang ingin dikurangi oleh MDG?", "options": ["Olahraga", "Sekolah", "Libur", "Kemiskinan ekstrem dan kelaparan"], "answer": 3, "explain": "Di antara tujuan lainnya, MDG bertujuan mengurangi kemiskinan ekstrem dan kelaparan.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "Apa itu pembelajaran anak usia dini yang berkualitas?", "options": ["Pembelajaran yang responsif, menyenangkan, dan mendukung", "Pembelajaran yang ketat dan senyap", "Pembelajaran yang hanya memakai lembar kerja", "Pembelajaran yang menghindari orang dewasa"], "answer": 0, "explain": "Pembelajaran anak usia dini yang berkualitas membangun keterampilan melalui interaksi yang hangat dan menyenangkan.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa deteksi dini keterlambatan perkembangan penting?", "options": ["Masalah sebaiknya diabaikan sampai masuk sekolah", "Dukungan dapat dimulai saat otak berkembang pesat", "Anak harus diberi label seumur hidup", "Orang tua harus disalahkan"], "answer": 1, "explain": "Deteksi dini memungkinkan dukungan dimulai saat otak berkembang pesat.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa tenaga kerja PAUD penting?", "options": ["Tenaga tidak diperlukan", "Tenaga hanya membersihkan ruangan", "Tenaga yang terampil membuat perbedaan besar bagi anak", "Tenaga tidak berpengaruh pada anak"], "answer": 2, "explain": "Tenaga PAUD yang terlatih membentuk pembelajaran dan kesejahteraan anak.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Apa itu ruang ramah anak?", "options": ["Toko yang hanya menjual mainan dan permen untuk anak", "Bangunan tanpa jendela dan pintu sama sekali bagi siswa", "Ruangan tempat anak dipisahkan dari yang lain sepanjang hari", "Tempat yang aman bagi anak untuk belajar dan bermain"], "answer": 3, "explain": "Ruang ramah anak memberi anak tempat yang aman untuk belajar dan bermain, terutama saat krisis.", "src": "UNESCO GEM Report 2026"}, {"ch": 9, "q": "Apa arti lingkungan yang merangsang bagi bayi?", "options": ["Banyak ajakan bicara, sentuhan, dan bermain", "Keheningan total", "Ruangan yang gelap", "Kebisingan keras yang terus-menerus"], "answer": 0, "explain": "Lingkungan yang merangsang mendukung perkembangan otak melalui interaksi.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa anak usia dini menjadi prioritas kebijakan?", "options": ["Tidak memberi manfaat bagi anak maupun keluarga", "Investasi dini memberi hasil besar di kemudian hari", "Hanya menghabiskan uang tanpa memberi hasil", "Hanya membantu orang dewasa yang sudah bekerja"], "answer": 1, "explain": "Investasi dini membantu anak belajar dan mengurangi biaya di kemudian hari.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Apa itu literasi awal (emergent literacy)?", "options": ["Literasi khusus orang dewasa", "Membaca hanya di perguruan tinggi", "Keterampilan awal yang mengarah pada membaca dan menulis", "Membaca hanya angka"], "answer": 2, "explain": "Literasi awal mencakup keterampilan dasar seperti mengenal huruf dan rima yang mengarah pada membaca.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Apa itu kesadaran rima?", "options": ["Melukis rima di dinding", "Hanya menyanyikan lagu keras", "Hanya menulis rima di kertas", "Mendengar dan mengucapkan bunyi yang berima"], "answer": 3, "explain": "Kesadaran rima membantu anak mendengar bunyi di dalam kata.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Apa yang termasuk literasi dwibahasa?", "options": ["Membaca dan menulis dalam dua bahasa", "Hanya membaca angka", "Hanya menggambar", "Hanya mendengarkan"], "answer": 0, "explain": "Literasi dwibahasa membangun kemampuan membaca dalam dua bahasa.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Mengapa literasi terkait dengan pekerjaan?", "options": ["Pekerjaan tidak pernah memerlukan membaca", "Banyak pekerjaan menuntut kemampuan membaca dan menulis", "Literasi hanya untuk guru", "Literasi tidak ada kaitannya dengan pekerjaan"], "answer": 1, "explain": "Literasi membantu orang membaca instruksi, menulis laporan, dan mempelajari keterampilan baru.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Apa itu literasi informasi?", "options": ["Menyembunyikan informasi dari semua orang di sekitar", "Menghafal setiap halaman dari setiap buku yang dibaca", "Menemukan, menilai, dan menggunakan informasi dengan baik", "Mengabaikan berita dan semua peristiwa terkini"], "answer": 2, "explain": "Literasi informasi membantu orang menilai sumber dan menggunakan informasi secara bertanggung jawab.", "src": "UNESCO"}, {"ch": 10, "q": "Mengapa banyak negara menggunakan bahasa lokal dalam belajar membaca awal?", "options": ["Bahasa lokal tidak diizinkan", "Bahasa lokal membuat membaca lebih sulit", "Bahasa lokal hanya untuk orang dewasa", "Anak belajar paling baik dalam bahasa yang mereka gunakan sehari-hari"], "answer": 3, "explain": "Membaca awal lebih mudah saat anak memahami kata-kata yang mereka lihat.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Mengapa latihan menulis penting?", "options": ["Mengubah pengetahuan membaca menjadi kemampuan berkomunikasi", "Tidak ada kaitannya dengan kemampuan membaca", "Hanya penting bagi siswa yang belajar seni", "Menggantikan membaca dengan menggambar saja"], "answer": 0, "explain": "Latihan menulis membantu peserta didik menyampaikan gagasan dan memperdalam bacaan.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "Apa itu kurikulum yang inklusif?", "options": ["Kurikulum yang mengecualikan sebagian peserta didik", "Kurikulum yang menghargai dan merangkul semua peserta didik", "Kurikulum hanya untuk satu kelompok", "Kurikulum tanpa mata pelajaran"], "answer": 1, "explain": "Kurikulum inklusif mencerminkan kebutuhan dan identitas semua peserta didik.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu pengajaran multisensori?", "options": ["Hanya menggunakan suara", "Mengajar dalam keheningan", "Menggunakan penglihatan, pendengaran, dan sentuhan dalam pelajaran", "Mengajar hanya dengan penutup mata"], "answer": 2, "explain": "Pengajaran multisensori membantu peserta didik yang belajar paling baik dengan cara yang berbeda.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu teknologi asistif dalam pendidikan?", "options": ["Permainan yang membuat belajar jauh lebih sulit bagi semua siswa", "Alat yang mencegah siswa membaca buku mereka", "Perlengkapan yang hanya digunakan untuk olahraga dan permainan", "Alat yang membantu peserta didik penyandang disabilitas untuk berpartisipasi"], "answer": 3, "explain": "Teknologi asistif mencakup pembaca layar, alat bantu dengar, dan alat bantu komunikasi.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu akomodasi yang wajar untuk ujian?", "options": ["Perubahan seperti tambahan waktu atau pembaca soal", "Menghapus ujian sepenuhnya untuk semua orang", "Membuat ujian lebih sulit bagi sebagian siswa", "Memungut biaya tambahan untuk ujian"], "answer": 0, "explain": "Akomodasi membuat ujian adil tanpa mengubah apa yang diuji.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Mengapa sekolah perlu mengumpulkan data disabilitas?", "options": ["Untuk meranking anak berdasarkan disabilitas", "Untuk merencanakan dukungan dan memantau inklusi", "Untuk mencegah anak mendaftar", "Untuk menjual perlengkapan sekolah"], "answer": 1, "explain": "Data disabilitas membantu sekolah merencanakan dukungan dan memastikan anak-anak terlibat.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu stereotip dalam pendidikan?", "options": ["Sejenis ujian sekolah yang diberikan sekali setahun", "Rute bus sekolah yang melewati kebun", "Pandangan yang kaku dan sering tidak adil tentang suatu kelompok", "Sejenis tas sekolah yang memuat banyak buku"], "answer": 2, "explain": "Stereotip dapat membatasi apa yang peserta didik yakini bisa mereka capai.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Apa itu rasa memiliki di sekolah?", "options": ["Sendirian di kelas", "Dikeluarkan dari pelajaran", "Pindah ke kota lain", "Merasa diterima dan dihargai"], "answer": 3, "explain": "Rasa memiliki membantu peserta didik terlibat dan tetap bersekolah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Apa arti akses universal untuk disabilitas?", "options": ["Akses bagi semua orang, termasuk penyandang disabilitas", "Akses hanya untuk orang tanpa disabilitas", "Akses hanya di satu gedung", "Akses hanya pada hari-hari tertentu"], "answer": 0, "explain": "Akses universal berarti pendidikan terbuka bagi semua orang, dengan dukungan yang dibutuhkan masing-masing.", "src": "UN CRPD (2006), Article 24"}], "10": [{"ch": 0, "q": "Prinsip apa yang berarti Agenda 2030 bertujuan menjangkau lebih dulu mereka yang paling tertinggal?", "options": ["Tidak ada yang ditinggalkan", "Yang terkuat yang bertahan", "Pertumbuhan dengan segala cara", "Setiap negara untuk dirinya sendiri"], "answer": 0, "explain": "Tidak ada yang ditinggalkan berarti memprioritaskan orang-orang yang paling kurang beruntung.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Indikator SDG 4 manakah yang memantau partisipasi dalam pembelajaran terorganisasi satu tahun sebelum sekolah dasar?", "options": ["Indikator 4.1.1", "Indikator 4.2.2", "Indikator 4.5.1", "Indikator 4.7.1"], "answer": 1, "explain": "Indikator 4.2.2 mengukur partisipasi dalam pembelajaran terorganisasi satu tahun sebelum usia masuk sekolah dasar resmi.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Apa tujuan Target 4.a sampai 4.c?", "options": ["Menyusun soal ujian", "Memilih warna sekolah", "Menyediakan sarana untuk menyelenggarakan pendidikan", "Menutup universitas"], "answer": 2, "explain": "Target-target ini berfokus pada fasilitas, beasiswa, dan ketersediaan guru.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Mengapa target SDG 4 diukur dengan indikator dan data?", "options": ["Agar laporan menjadi lebih panjang", "Agar tidak perlu mengambil keputusan", "Untuk menggantikan guru", "Untuk memeriksa apakah kemajuan itu nyata dan adil"], "answer": 3, "explain": "Indikator dan data terpilah menunjukkan kemajuan serta ketimpangan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa hubungan antara SDG 4 dan SDG 1 (Tanpa Kemiskinan)?", "options": ["Pendidikan membantu mengurangi kemiskinan dan kemiskinan membatasi pendidikan", "Keduanya sama sekali tidak berhubungan di negara mana pun", "Pendidikan menyebabkan kemiskinan dan membuat keluarga makin miskin setiap tahun", "Kemiskinan hanya memengaruhi seberapa baik anak-anak berolahraga di sekolah"], "answer": 0, "explain": "Pendidikan dan kemiskinan saling berkaitan erat ke dua arah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa yang dimaksud dengan garis dasar (baseline) dalam pemantauan SDG?", "options": ["Garis finis yang menandai akhir sebuah lomba lari panjang", "Titik awal yang digunakan untuk mengukur kemajuan", "Dasar tas sekolah tempat menyimpan buku-buku lama", "Harga buku teks baru di toko setempat"], "answer": 1, "explain": "Baseline adalah data awal yang digunakan untuk mengukur perubahan.", "src": "UN SDG Report 2026"}, {"ch": 1, "q": "Apa yang dimaksud dengan pendidikan wajib?", "options": ["Pendidikan yang bersifat pilihan bagi semua orang", "Pendidikan yang hanya untuk orang dewasa", "Pendidikan yang oleh hukum wajib diikuti anak-anak", "Pendidikan yang dilarang"], "answer": 2, "explain": "Pendidikan wajib berarti anak-anak harus bersekolah sampai usia tertentu menurut hukum.", "src": "UNESCO"}, {"ch": 1, "q": "Apa itu bantuan tunai bersyarat untuk pendidikan?", "options": ["Uang yang diberikan kepada guru untuk liburan", "Uang untuk biaya sekolah yang hanya dibayar oleh donor", "Uang yang hanya digunakan untuk membangun jalan", "Uang yang diberikan kepada keluarga jika anak-anak bersekolah"], "answer": 3, "explain": "Bantuan tunai bersyarat mendorong keluarga menyekolahkan anak-anak mereka.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Mengapa pemerintah menghapus biaya sekolah?", "options": ["Untuk memperluas akses bagi keluarga miskin", "Untuk mengurangi jumlah murid", "Agar sekolah menjadi kurang bermanfaat", "Untuk menghentikan gaji guru"], "answer": 0, "explain": "Menghapus biaya membantu anak-anak yang lebih miskin untuk mendaftar dan tetap bersekolah.", "src": "UNESCO"}, {"ch": 1, "q": "Siapa yang dimaksud dengan remaja di luar sekolah?", "options": ["Orang dewasa yang rutin belajar daring dari rumah", "Kaum muda usia SMP/SMA yang tidak bersekolah", "Anak-anak TK yang bermain di kebun sepanjang hari", "Guru yang sedang cuti dari sekolahnya tahun ini"], "answer": 1, "explain": "Remaja di luar sekolah adalah anak muda yang tidak terdaftar di satuan pendidikan mana pun.", "src": "UNESCO"}, {"ch": 1, "q": "Apa itu sekolah yang fleksibel untuk anak-anak?", "options": ["Pendidikan tanpa aturan dan jadwal sama sekali bagi anak-anak", "Pendidikan hanya pada malam hari untuk semua orang di seluruh kota", "Pendidikan yang diatur mengikuti pekerjaan atau kebutuhan keluarga anak", "Pendidikan tanpa guru yang hadir di kelas pada waktu apa pun"], "answer": 2, "explain": "Sekolah fleksibel membantu anak-anak yang tidak bisa bersekolah penuh waktu.", "src": "UNESCO"}, {"ch": 1, "q": "Mengapa transportasi yang aman penting bagi akses anak perempuan ke sekolah?", "options": ["Transportasi tidak pernah diperlukan untuk perjalanan sekolah mana pun", "Anak perempuan tidak boleh bepergian ke mana pun di luar rumah", "Anak perempuan lebih suka berjalan sangat jauh untuk sampai ke sekolah", "Perjalanan yang tidak aman atau jauh dapat membuat anak perempuan tetap di rumah"], "answer": 3, "explain": "Transportasi yang aman dapat membuat perbedaan besar pada kehadiran anak perempuan.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "Apa itu kampanye pendaftaran?", "options": ["Kampanye untuk membawa anak-anak ke sekolah", "Balap mobil", "Hanya makan malam penggalangan dana sekolah", "Turnamen olahraga"], "answer": 0, "explain": "Kampanye pendaftaran mendorong keluarga untuk mendaftarkan anak mereka ke sekolah.", "src": "UNESCO"}, {"ch": 2, "q": "Apa arti menyelesaikan jenjang SMP?", "options": ["Menyelesaikan TK", "Menyelesaikan tahap pertama pendidikan menengah", "Menyelesaikan universitas", "Menyelesaikan kursus liburan"], "answer": 1, "explain": "SMP adalah tahap pertama pendidikan menengah.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa remaja putus sekolah di banyak negara?", "options": ["Mereka menyelesaikan sekolah terlalu cepat setiap tahun", "Mereka semua mendapat beasiswa ke sekolah terbaik", "Tekanan bekerja, biaya, dan pembelajaran yang terasa tidak relevan", "Mereka mendapat terlalu banyak libur dan hari bebas selama semester"], "answer": 2, "explain": "Tekanan bekerja, biaya, dan pembelajaran yang terasa tidak relevan sering mendorong siswa keluar sekolah.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Apa itu jalur pembelajaran bagi kaum muda yang telah meninggalkan sekolah?", "options": ["Jalan menuju toko tempat barang dijual kepada pelanggan", "Jalan yang berakhir tanpa kualifikasi sama sekali", "Jalan yang hanya terbuka bagi guru dan staf yang berkualifikasi", "Jalan kembali ke pembelajaran dengan kualifikasi yang diakui"], "answer": 3, "explain": "Jalur pembelajaran membantu kaum muda kembali belajar dan memperoleh kualifikasi.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa menyelesaikan SMA dikaitkan dengan pekerjaan?", "options": ["Membuka lebih banyak pilihan kerja dan pelatihan", "Menghentikan semua peluang kerja", "Berarti tidak ada lagi pembelajaran", "Hanya membantu seniman"], "answer": 0, "explain": "Menyelesaikan SMA memperluas akses ke pekerjaan dan studi lanjut.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apa itu intervensi berbasis sekolah untuk menjaga anak tetap bersekolah?", "options": ["Menutup sekolah lebih awal setiap hari dalam seminggu", "Tindakan dukungan di dalam sekolah, seperti mentoring", "Menghapus semua pelajaran dari jadwal sekolah setiap minggu", "Mengabaikan siswa yang sudah tidak masuk sekolah selama berminggu-minggu"], "answer": 1, "explain": "Dukungan berbasis sekolah membantu siswa yang berisiko putus sekolah.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa dukungan tunai dan pangan dikaitkan dengan penyelesaian pendidikan?", "options": ["Menggantikan semua pengajaran di kelas", "Menyebabkan lebih banyak anak putus sekolah setiap tahun", "Mengurangi biaya yang mendorong anak keluar dari sekolah", "Membuat jam sekolah jauh lebih panjang dan melelahkan"], "answer": 2, "explain": "Dukungan biaya dapat membantu anak-anak bertahan hingga selesai.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa sebagian siswa putus sekolah setelah berulang kali gagal ujian?", "options": ["Ujian tidak pernah gagal", "Gagal ujian membantu siswa", "Kegagalan justru diberi hadiah", "Kegagalan yang berulang dapat membuat pembelajar kehilangan semangat"], "answer": 3, "explain": "Kegagalan berulang tanpa dukungan dapat membuat siswa kehilangan kepercayaan diri dan keluar sekolah.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu Pengajaran pada Tingkat yang Tepat?", "options": ["Mengelompokkan pembelajar berdasarkan tingkat kemampuan, bukan usia", "Hanya mengajar pembelajar yang paling tua", "Hanya mengajar dalam bahasa Inggris", "Mengajar tanpa rencana"], "answer": 0, "explain": "Pengajaran pada Tingkat yang Tepat mengelompokkan pembelajar berdasarkan apa yang sudah mampu mereka lakukan.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu pembelajaran dasar (foundational learning)?", "options": ["Penelitian universitas tingkat lanjut di bidang sains, hukum, dan kedokteran", "Kemampuan membaca, menulis, dan berhitung dasar yang menopang pembelajaran berikutnya", "Hanya pendidikan jasmani dan olahraga sepanjang tahun ajaran", "Hanya sejarah seni dan studi lukisan serta patung kuno"], "answer": 1, "explain": "Pembelajaran dasar adalah fondasi bagi seluruh pendidikan selanjutnya.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Studi internasional manakah yang menguji kemampuan membaca di sekolah dasar?", "options": ["PISA", "TIMSS", "PIRLS", "Tes ICAO"], "answer": 2, "explain": "PIRLS, Progress in International Reading Literacy Study, menguji kemampuan membaca di sekolah dasar.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa yang diukur oleh TIMSS?", "options": ["Musik dan tari", "Olahraga dan kebugaran", "Keterampilan memasak", "Capaian matematika dan sains"], "answer": 3, "explain": "TIMSS, Trends in International Mathematics and Science Study, mengukur capaian matematika dan sains.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu tes berisiko rendah (low-stakes test)?", "options": ["Tes yang hasilnya tidak menentukan masa depan siswa", "Tes yang menentukan siapa yang dikeluarkan", "Tes tanpa soal sama sekali", "Tes yang hanya dipakai untuk merekrut guru"], "answer": 0, "explain": "Tes berisiko rendah membantu guru melihat pembelajaran tanpa tekanan tinggi.", "src": "UNESCO"}, {"ch": 3, "q": "Mengapa hasil belajar berbeda di dalam satu negara?", "options": ["Hanya cuaca yang mengubah hasil dari satu sekolah ke sekolah lain", "Pendapatan, bahasa, lokasi, dan jenis kelamin berperan", "Hanya warna sekolah yang menentukan prestasi siswa", "Hanya jadwal bus yang menentukan prestasi siswa"], "answer": 1, "explain": "Hasil belajar dibentuk oleh banyak faktor sosial dan ekonomi.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu keterampilan kognitif dalam pembelajaran?", "options": ["Keterampilan untuk tidur nyenyak setiap malam", "Keterampilan bermain sepak bola di tim sekolah sepanjang tahun", "Keterampilan berpikir seperti ingatan, penalaran, dan pemecahan masalah", "Keterampilan memasak makanan sederhana di rumah untuk keluarga"], "answer": 2, "explain": "Keterampilan kognitif menopang penalaran dan pembelajaran di semua mata pelajaran.", "src": "UNESCO"}, {"ch": 3, "q": "Mengapa asesmen pembelajaran penting bagi kebijakan?", "options": ["Menggantikan sekolah di setiap komunitas di seluruh negeri", "Hanya memberi hadiah kepada siswa terbaik setiap tahun", "Mengakhiri kebutuhan akan guru di setiap sekolah", "Menunjukkan di mana pembelajaran paling lemah dan perlu dukungan"], "answer": 3, "explain": "Data asesmen membantu pemerintah memutuskan di mana harus berinvestasi dan memberi dukungan.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "Apa empat C dalam keterampilan abad ke-21?", "options": ["Kreativitas, berpikir kritis, komunikasi, dan kolaborasi", "Memasak, membersihkan, bersepeda, dan mewarnai di sekolah setiap minggu", "Menghitung, mencacah, menyalin, dan membuat kode di laboratorium komputer", "Bersorak, melatih, bertanding, dan memasak untuk tim sekolah"], "answer": 0, "explain": "Empat C banyak digunakan untuk menggambarkan keterampilan utama untuk dunia kerja dan kehidupan modern.", "src": "UNESCO"}, {"ch": 4, "q": "Apa kepanjangan dari STEM?", "options": ["Olahraga, pengajaran, ujian, dan musik", "Sains, teknologi, teknik, dan matematika", "Berbicara, teater, penyuntingan, dan pasar", "Sosiologi, pariwisata, ekonomi, dan media"], "answer": 1, "explain": "STEM mencakup sains, teknologi, teknik, dan matematika.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu keamanan digital bagi pembelajar?", "options": ["Membagikan kata sandi kepada semua orang yang ditemui secara daring setiap hari", "Mengabaikan privasi daring dan membagikan setiap foto", "Melindungi data pribadi dan mengenali risiko daring", "Bertemu orang asing dari daring secara langsung dan merahasiakannya"], "answer": 2, "explain": "Keamanan digital membantu pembelajar melindungi informasi mereka dan tetap aman daring.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu penggunaan teknologi yang etis dalam pembelajaran?", "options": ["Menyalin karya orang lain tanpa memberi kredit", "Merundung teman sekelas secara daring", "Membagikan foto pribadi", "Menggunakannya secara jujur, hormat, dan dengan persetujuan"], "answer": 3, "explain": "Penggunaan teknologi yang etis menghormati orang lain dan kejujuran akademik.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu kerangka kompetensi?", "options": ["Daftar keterampilan dan pengetahuan yang harus dikuasai pembelajar", "Sejenis bangunan sekolah dengan beberapa lantai dan ruangan", "Daftar olahraga, permainan, dan klub sekolah yang bisa diikuti", "Rencana hanya untuk ujian dan tes tanpa pembelajaran lain"], "answer": 0, "explain": "Kerangka kompetensi menjelaskan apa yang harus mampu dilakukan pembelajar.", "src": "UNESCO"}, {"ch": 4, "q": "Mengapa kewirausahaan dikaitkan dengan SDG 4?", "options": ["Sama sekali tidak berhubungan dengan pekerjaan atau pemecahan masalah", "Mengembangkan keterampilan untuk menciptakan lapangan kerja dan memecahkan masalah", "Hanya mengajarkan penjualan dan pengelolaan toko", "Mencegah orang mendapatkan pekerjaan sama sekali"], "answer": 1, "explain": "Kewirausahaan membangun inisiatif dan kemampuan memecahkan masalah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu kesenjangan keterampilan (skills gap)?", "options": ["Celah di dinding sekolah yang perlu segera diperbaiki semester ini", "Jeda antara dua pelajaran panjang pada hari sekolah yang sibuk", "Ketidaksesuaian antara keterampilan yang dimiliki orang dan yang dibutuhkan pekerjaan", "Ujian yang hilang dari jadwal sekolah semester ini"], "answer": 2, "explain": "Kesenjangan keterampilan menyulitkan orang mencari kerja dan pemberi kerja mengisi lowongan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Mengapa pendidikan dan pelatihan vokasi (TVET) penting bagi lapangan kerja kaum muda?", "options": ["Menggantikan semua pembelajaran akademik", "Hanya untuk orang dewasa", "Tidak pernah berguna", "Menyediakan keterampilan praktis yang terkait dengan pekerjaan"], "answer": 3, "explain": "TVET memberi kaum muda keterampilan siap kerja dan jalur menuju pekerjaan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa itu hambatan belajar berbasis gender?", "options": ["Aturan atau norma yang membuat pembelajaran lebih sulit bagi salah satu gender", "Hambatan yang membantu setiap siswa belajar jauh lebih baik", "Hambatan yang hanya memengaruhi guru di sekolah", "Hambatan yang sama sekali tidak berpengaruh pada pembelajaran"], "answer": 0, "explain": "Hambatan berbasis gender mencakup norma dan praktik yang membatasi pembelajaran anak perempuan atau laki-laki.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Bagaimana kurangnya fasilitas kebersihan dapat memengaruhi anak perempuan di sekolah?", "options": ["Tidak berhubungan dengan kehadiran sekolah di negara mana pun", "Anak perempuan bisa tidak masuk sekolah tanpa toilet pribadi dan perlengkapan kebersihan", "Hanya memengaruhi anak laki-laki yang bersekolah di tempat yang sama", "Merupakan mata pelajaran yang diajarkan kepada siswa kelas sembilan"], "answer": 1, "explain": "Akses ke fasilitas kebersihan dan toilet pribadi membantu anak perempuan tetap bersekolah.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa tujuan kebijakan tentang pekerja anak?", "options": ["Memaksa anak bekerja berjam-jam di ladang setiap hari", "Menghentikan semua pendidikan bagi anak di desa dan kota", "Melindungi anak dari pekerjaan yang merugikan belajar dan kesehatan mereka", "Membayar anak agar bolos sekolah dan tinggal di rumah setiap hari"], "answer": 2, "explain": "Kebijakan pekerja anak melindungi hak anak untuk belajar dan hidup sehat.", "src": "UNESCO"}, {"ch": 5, "q": "Apa arti kelompok minoritas dalam pendidikan?", "options": ["Kelompok yang selalu paling kaya", "Kelompok yang selalu paling unggul dalam ujian", "Kelompok yang tidak pernah bersekolah", "Kelompok yang jumlahnya lebih kecil dari populasi utama"], "answer": 3, "explain": "Kelompok minoritas adalah kelompok yang lebih kecil dalam suatu populasi, yang mungkin menghadapi hambatan.", "src": "UNESCO"}, {"ch": 5, "q": "Mengapa pembelajar dari masyarakat adat sering membutuhkan pendidikan yang relevan secara budaya?", "options": ["Menghormati identitas mereka dan meningkatkan pembelajaran", "Menggantikan bahasa mereka sepenuhnya dengan bahasa lain", "Tidak diperlukan di sekolah mana pun", "Hanya memengaruhi olahraga dan permainan di sekolah"], "answer": 0, "explain": "Pendidikan yang relevan secara budaya membantu pembelajar adat merasa dihargai dan belajar lebih baik.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa itu penargetan dalam kebijakan kesetaraan?", "options": ["Memberi sumber daya kepada yang paling kaya", "Memusatkan sumber daya pada kelompok yang tertinggal", "Memberi sumber daya yang sama hanya kepada yang paling kuat", "Mengabaikan kelompok yang membutuhkan"], "answer": 1, "explain": "Penargetan memusatkan upaya pada kelompok yang paling membutuhkan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa itu kurikulum yang peka gender?", "options": ["Kurikulum khusus laki-laki yang diajarkan di setiap sekolah", "Kurikulum yang mengajarkan stereotip tentang anak perempuan dan laki-laki", "Kurikulum yang menghindari stereotip dan memperlakukan semua pembelajar secara setara", "Kurikulum tanpa mata pelajaran sama sekali bagi siswa mana pun"], "answer": 2, "explain": "Kurikulum yang peka gender menantang stereotip dan mendukung semua pembelajar.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa yang dijelaskan oleh diskriminasi interseksional?", "options": ["Diskriminasi di satu tempat saja", "Diskriminasi yang selalu adil", "Diskriminasi hanya terhadap guru", "Berbagai bentuk diskriminasi yang saling tumpang tindih"], "answer": 3, "explain": "Diskriminasi interseksional terjadi ketika beberapa identitas berpadu sehingga menimbulkan kerugian.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Apa itu ketersediaan guru dalam Target 4.c?", "options": ["Jumlah guru berkualifikasi yang tersedia", "Jumlah hari libur", "Jumlah bel sekolah", "Jumlah meja"], "answer": 0, "explain": "Target 4.c berfokus pada peningkatan ketersediaan guru berkualifikasi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Mengapa negara perlu merekrut lebih banyak guru?", "options": ["Karena guru tidak diperlukan", "Untuk memenuhi kebutuhan yang meningkat dan menggantikan guru yang keluar", "Untuk mengurangi jumlah siswa per kelas menjadi nol", "Untuk menutup sekolah"], "answer": 1, "explain": "Perekrutan diperlukan agar tetap sejalan dengan bertambahnya jumlah siswa dan guru yang pensiun.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu guru kontrak?", "options": ["Mengajar dengan janji kerja seumur hidup", "Mengajar tanpa dibayar", "Mengajar dengan kontrak singkat dan sementara", "Mengajar hanya lewat telepon"], "answer": 2, "explain": "Guru kontrak sering kurang terjamin, yang dapat memengaruhi keberlanjutan mereka di profesi.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa arti pendidikan guru pra-jabatan?", "options": ["Pelatihan setelah pensiun", "Pelatihan hanya untuk kepala sekolah", "Pelatihan untuk orang tua", "Pelatihan sebelum mulai mengajar"], "answer": 3, "explain": "Pelatihan pra-jabatan mempersiapkan orang sebelum mereka mulai mengajar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa arti pelatihan dalam jabatan?", "options": ["Pelatihan saat sudah mengajar", "Pelatihan untuk orang yang tidak mengajar", "Pelatihan hanya selama libur berdasarkan undang-undang", "Pelatihan yang menggantikan seluruh kegiatan mengajar"], "answer": 0, "explain": "Pelatihan dalam jabatan membantu guru terus meningkatkan kemampuan saat bekerja.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu kode etik guru?", "options": ["Bahasa rahasia guru yang hanya digunakan staf", "Aturan yang menetapkan perilaku profesional yang diharapkan", "Daftar hari libur guru untuk sepanjang tahun", "Aturan berpakaian sekolah yang hanya berlaku untuk guru"], "answer": 1, "explain": "Kode etik menetapkan bagaimana guru harus bersikap terhadap pembelajar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa guru membutuhkan pelatihan pengajaran inklusif?", "options": ["Tidak diperlukan", "Agar mereka bisa menghindari pembelajar", "Untuk mendukung pembelajar dengan kebutuhan yang berbeda", "Agar mereka bisa mengajar lebih sedikit mata pelajaran"], "answer": 2, "explain": "Pelatihan inklusif membantu guru memenuhi berbagai kebutuhan pembelajar.", "src": "UN CRPD (2006), Article 24"}, {"ch": 6, "q": "Apa itu kelelahan guru (burnout)?", "options": ["Guru yang terlalu bersemangat", "Guru yang mengajar terlalu bagus", "Guru yang digaji terlalu tinggi", "Kelelahan jangka panjang akibat pekerjaan yang penuh tekanan"], "answer": 3, "explain": "Kelelahan mengurangi kesejahteraan dan dapat mendorong guru untuk meninggalkan profesi.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Apa yang diukur oleh kesenjangan pembiayaan SDG 4?", "options": ["Dana tambahan yang dibutuhkan di luar belanja saat ini", "Dana yang dibelanjakan untuk olahraga", "Dana yang ditabung di bank", "Dana yang dibayarkan kepada penjual sekolah"], "answer": 0, "explain": "Kesenjangan pembiayaan menunjukkan seberapa banyak tambahan yang dibutuhkan untuk mencapai tujuan pendidikan.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "Apa kontribusi penerimaan pajak bagi pendidikan?", "options": ["Uang yang hanya membayar liburan", "Uang yang digunakan pemerintah untuk membiayai sekolah", "Uang yang menggantikan guru", "Uang yang selalu terbuang sia-sia"], "answer": 1, "explain": "Penerimaan pajak merupakan sumber utama pendanaan pemerintah untuk pendidikan.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu pendanaan di luar anggaran (off-budget) untuk pendidikan?", "options": ["Uang yang dibelanjakan untuk liburan", "Uang yang disimpan di bawah tempat tidur", "Uang yang dibelanjakan di luar anggaran resmi", "Uang yang dibelanjakan untuk jet pribadi"], "answer": 2, "explain": "Pendanaan di luar anggaran dapat menyulitkan pelacakan total belanja pendidikan.", "src": "UNESCO"}, {"ch": 7, "q": "Mengapa donor kadang mendanai pendidikan?", "options": ["Untuk meraup keuntungan besar dari menjalankan sekolah bagi anak-anak", "Untuk menutup sekolah di negara-negara termiskin setiap tahun", "Untuk mencegah anak-anak belajar di sekolah mana pun", "Untuk mendukung anak-anak di negara dengan sumber daya lebih sedikit"], "answer": 3, "explain": "Donor sering mendanai pendidikan untuk membantu negara yang membutuhkan dukungan tambahan.", "src": "UNESCO"}, {"ch": 7, "q": "Bagaimana utang dapat memengaruhi belanja pendidikan?", "options": ["Pembayaran utang yang besar dapat mengurangi dana untuk sekolah", "Utang secara otomatis membiayai sekolah", "Utang sama sekali tidak berpengaruh", "Utang hanya memengaruhi olahraga"], "answer": 0, "explain": "Pemerintah yang banyak membelanjakan untuk pembayaran utang mungkin memiliki lebih sedikit dana untuk pendidikan.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu audit nilai uang (value-for-money) dalam pendidikan?", "options": ["Pemeriksaan harga dan kualitas seragam sekolah", "Pemeriksaan apakah belanja menghasilkan hasil yang baik", "Pemeriksaan berapa lama setiap guru mengambil cuti liburan", "Pemeriksaan makanan sekolah yang disajikan setiap siang"], "answer": 1, "explain": "Audit nilai uang memeriksa apakah dana pendidikan menghasilkan hasil belajar.", "src": "UNESCO"}, {"ch": 7, "q": "Mengapa sekolah membutuhkan pendanaan yang stabil?", "options": ["Agar bisa mengubah cuaca", "Agar bisa menghindari semua guru", "Agar bisa merencanakan guru, bahan ajar, dan perbaikan", "Agar bisa tutup lebih awal"], "answer": 2, "explain": "Pendanaan yang stabil memungkinkan sekolah merencanakan ke depan dan menjaga proses belajar tetap berjalan.", "src": "UNESCO"}, {"ch": 7, "q": "Apa fungsi hibah tingkat sekolah?", "options": ["Memberi guru liburan", "Memberi anak-anak hadiah saja", "Memberi keluarga mobil", "Memberi sekolah dana untuk memenuhi kebutuhan setempat"], "answer": 3, "explain": "Hibah sekolah memungkinkan sekolah menanggapi prioritas setempat.", "src": "UNESCO"}, {"ch": 8, "q": "Pernyataan tahun 1994 manakah yang mendorong sekolah inklusif bagi semua anak?", "options": ["Pernyataan Salamanca", "Deklarasi Tokyo", "Pakta Kairo", "Rencana Lima"], "answer": 0, "explain": "Pernyataan Salamanca tahun 1994 mendorong sekolah inklusif bagi semua anak.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "Pada tahun berapa Pernyataan Salamanca diadopsi?", "options": ["1948", "1994", "1989", "2015"], "answer": 1, "explain": "Pernyataan Salamanca diadopsi pada tahun 1994.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "Apa yang diserukan konferensi Jomtien 1990 di luar persekolahan?", "options": ["Hanya sekolah untuk orang dewasa", "Hanya olahraga", "Pembelajaran bagi anak-anak, kaum muda, dan orang dewasa", "Tidak ada pembelajaran setelah usia sepuluh tahun"], "answer": 2, "explain": "Jomtien menekankan pembelajaran sepanjang hayat bagi semua orang.", "src": "UNESCO"}, {"ch": 8, "q": "Berapa tujuan yang ditetapkan Kerangka Aksi Dakar untuk Pendidikan untuk Semua?", "options": ["Tiga", "Sepuluh", "Tujuh belas", "Enam"], "answer": 3, "explain": "Kerangka Aksi Dakar menetapkan enam tujuan untuk Pendidikan untuk Semua.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Apa yang dikatakan Deklarasi Universal Hak Asasi Manusia 1948 tentang pendidikan?", "options": ["Pendidikan adalah hak asasi manusia", "Pendidikan adalah kemewahan", "Pendidikan hanya untuk anak laki-laki", "Pendidikan bersifat opsional"], "answer": 0, "explain": "DUHAM menyatakan bahwa pendidikan adalah hak asasi manusia.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Mengapa konferensi Jomtien 1990 penting?", "options": ["Melarang semua sekolah di seluruh negeri", "Menetapkan komitmen global untuk Pendidikan untuk Semua", "Menetapkan harga buku untuk setiap toko di kota", "Mengakhiri pelatihan guru di sebagian besar negara pada tahun itu"], "answer": 1, "explain": "Jomtien menetapkan komitmen global untuk Pendidikan untuk Semua.", "src": "UNESCO"}, {"ch": 8, "q": "Apa kesamaan komitmen pendidikan global yang besar?", "options": ["Tidak pernah dijalankan", "Hanya berlaku untuk sekolah swasta", "Mereka menetapkan tujuan yang disepakati pemerintah untuk dicapai", "Hanya berlaku untuk satu negara"], "answer": 2, "explain": "Komitmen global menetapkan tujuan bersama yang disepakati pemerintah untuk diupayakan.", "src": "UNESCO"}, {"ch": 8, "q": "Kapan Hari Pendidikan Internasional?", "options": ["1 Mei", "31 Oktober", "25 Desember", "24 Januari"], "answer": 3, "explain": "UNESCO memperingati Hari Pendidikan Internasional setiap 24 Januari.", "src": "UNESCO"}, {"ch": 9, "q": "Apa itu Kerangka Perawatan Pengasuhan (Nurturing Care Framework)?", "options": ["Kerangka yang menyatukan kesehatan, gizi, pengasuhan, dan pembelajaran pada usia dini", "Rencana membangun sekolah hanya di kota-kota besar negara", "Daftar aturan dan hukuman sekolah bagi anak kecil", "Rencana olahraga dan permainan di halaman setiap minggu"], "answer": 0, "explain": "Kerangka ini menghubungkan kesehatan, gizi, pengasuhan yang responsif, keamanan, dan pembelajaran pada usia dini.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Apa arti arsitektur otak pada masa kanak-kanak usia dini?", "options": ["Bentuk sebuah bangunan sekolah", "Cara sambungan-sambungan otak terbentuk sejak awal kehidupan", "Desain meja sekolah", "Tata letak sebuah kota"], "answer": 1, "explain": "Pengalaman awal membentuk sambungan-sambungan yang membangun arsitektur otak.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu keterlibatan orang tua dalam pembelajaran usia dini?", "options": ["Orang tua tidak pernah hadir di acara sekolah mana pun", "Orang tua membayar guru untuk mengajar anak mereka secara privat", "Orang tua ikut serta secara aktif dalam pembelajaran anak", "Orang tua sama sekali menghindari anak dan tugas sekolahnya"], "answer": 2, "explain": "Orang tua yang terlibat mendukung pembelajaran di rumah dan di sekolah.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu bermain dan eksplorasi pada usia dini?", "options": ["Duduk diam berjam-jam tanpa bergerak sama sekali di kelas", "Menyalin dari papan tulis sepanjang pelajaran", "Latihan senyap yang diulang setiap hari di sekolah", "Kegiatan langsung yang membantu anak menemukan gagasan"], "answer": 3, "explain": "Bermain dan eksplorasi membantu anak belajar tentang dunia.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa yang membuat pendidikan anak usia dini berkualitas tinggi?", "options": ["Staf terlatih, ruang yang baik, dan interaksi yang hangat", "Kelas besar tanpa orang dewasa di ruangan", "Hanya lembar kerja yang dibagikan tanpa pengajaran", "Jam-jam panjang dalam keheningan tanpa orang dewasa atau kegiatan"], "answer": 0, "explain": "Kualitas bergantung pada staf yang terampil, ruang yang aman, dan hubungan yang hangat.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Apa itu kelekatan (attachment) pada usia dini?", "options": ["Sejenis mainan", "Ikatan yang aman antara anak dan pengasuhnya", "Jadwal sekolah yang tetap", "Pajak bagi keluarga"], "answer": 1, "explain": "Kelekatan yang aman mendukung perkembangan emosi dan sosial anak.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa yang termasuk kesiapan sekolah selain kemampuan akademik?", "options": ["Hanya membaca kata dengan suara keras setiap hari", "Hanya menulis huruf dan angka di kertas berjam-jam", "Kesehatan, kesejahteraan emosi, dan keterampilan sosial", "Hanya kekuatan fisik dan kecepatan dalam lomba setiap semester"], "answer": 2, "explain": "Kesiapan mencakup kesehatan, keterampilan sosial dan emosional, serta akademik.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Apa itu lingkungan literasi di rumah?", "options": ["Ruangan sunyi tanpa buku", "Hanya televisi", "Tanpa kontak dengan keluarga", "Buku, percakapan, dan rutinitas membaca di rumah"], "answer": 3, "explain": "Lingkungan literasi di rumah mendukung keterampilan membaca.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Apa itu budaya membaca?", "options": ["Kebiasaan bersama dan nilai yang diberikan pada membaca", "Sejenis tarian yang dipentaskan di aula sekolah", "Sejenis olahraga yang dimainkan di lapangan sekolah", "Sistem bel sekolah yang digunakan sepanjang hari"], "answer": 0, "explain": "Budaya membaca menjadikan membaca bagian dari kehidupan sehari-hari.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Mengapa orang dewasa dengan literasi rendah sulit mendapatkan pekerjaan?", "options": ["Pekerjaan tidak pernah memerlukan membaca", "Banyak pekerjaan membutuhkan keterampilan membaca dan menulis", "Orang dewasa memang tidak bisa mendapatkan pekerjaan", "Pemberi kerja lebih suka buta huruf"], "answer": 1, "explain": "Literasi yang rendah dapat membatasi akses ke banyak pekerjaan dan pelatihan.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Apa itu literasi pascasekolah dasar?", "options": ["Literasi sebelum lahir", "Literasi hanya di TK", "Keterampilan literasi setelah sekolah dasar", "Literasi hanya untuk guru"], "answer": 2, "explain": "Literasi pascasekolah dasar membangun dan menjaga kemampuan membaca dan menulis setelah SD.", "src": "UNESCO"}, {"ch": 10, "q": "Apa salah satu penyebab kesulitan membaca?", "options": ["Sejenis pola makan", "Sejenis ujian", "Sejenis cuaca", "Disleksia"], "answer": 3, "explain": "Sebagian kesulitan membaca disebabkan oleh disleksia, yang memerlukan dukungan khusus.", "src": "UN CRPD (2006), Article 24"}, {"ch": 10, "q": "Apa yang membantu komunitas pedesaan mendapat akses ke buku?", "options": ["Perpustakaan terdekat atau pengiriman buku", "Melarang buku", "Menjual buku dengan harga sangat tinggi", "Hanya menyimpan buku di kota"], "answer": 0, "explain": "Akses buku di daerah pedesaan dapat diperbaiki melalui perpustakaan dan layanan keliling.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Apa itu perpustakaan keliling?", "options": ["Perpustakaan di tempat parkir saja", "Perpustakaan yang berkeliling ke komunitas", "Perpustakaan yang menjual ponsel", "Perpustakaan yang tertutup untuk umum"], "answer": 1, "explain": "Perpustakaan keliling membawa buku kepada orang yang tinggal jauh dari perpustakaan.", "src": "UNESCO"}, {"ch": 11, "q": "Apa yang dicakup Pasal 24 CRPD PBB?", "options": ["Olahraga dan permainan untuk semua siswa", "Memasak dan makanan untuk keluarga di rumah", "Pendidikan, termasuk pendidikan inklusif", "Liburan dan pariwisata untuk kelompok sekolah"], "answer": 2, "explain": "Pasal 24 CRPD PBB menetapkan hak atas pendidikan inklusif.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa arti aksesibilitas bagi sekolah?", "options": ["Hanya satu pintu di depan gedung untuk semua orang", "Bahan yang hanya boleh dibaca oleh guru", "Informasi yang dirahasiakan dari keluarga siswa", "Bangunan, bahan, dan informasi yang dapat digunakan semua orang"], "answer": 3, "explain": "Aksesibilitas membuat ruang dan informasi sekolah dapat digunakan oleh semua orang.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu pedagogi inklusif?", "options": ["Metode mengajar yang dirancang untuk melibatkan setiap pembelajar", "Hanya mengajar pembelajar terbaik di setiap kelas setiap hari", "Mengajar dengan satu cara tetap yang cocok untuk semua pembelajar", "Mengajar tanpa bahan atau sumber daya apa pun di ruangan"], "answer": 0, "explain": "Pedagogi inklusif menyesuaikan pengajaran agar semua pembelajar ikut serta dan belajar.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Mengapa sekolah membutuhkan staf pendukung untuk inklusi?", "options": ["Staf pendukung tidak diperlukan", "Untuk membantu pembelajar mengakses pelajaran dan kehidupan sehari-hari", "Untuk menggantikan semua guru", "Untuk memisahkan pembelajar"], "answer": 1, "explain": "Staf pendukung membantu pembelajar penyandang disabilitas ikut serta di sekolah.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu lingkungan yang paling tidak membatasi?", "options": ["Kelas paling padat di seluruh gedung sekolah", "Ruangan yang paling jauh dari semua kelas lain", "Lingkungan tempat pembelajar dapat belajar dengan inklusi paling besar", "Ruangan tanpa jendela, tanpa cahaya, dan tanpa kursi"], "answer": 2, "explain": "Lingkungan yang paling tidak membatasi mendukung pembelajaran dengan inklusi sebesar mungkin.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa arti partisipasi penuh bagi pembelajar penyandang disabilitas?", "options": ["Hadir hanya pada hari-hari khusus", "Menonton dari luar", "Dipisahkan di ruangan tersendiri", "Ikut serta secara setara dalam semua bagian kehidupan sekolah"], "answer": 3, "explain": "Partisipasi penuh berarti pembelajar dapat ikut serta dalam semua kegiatan dan pembelajaran.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu model sosial disabilitas?", "options": ["Disabilitas dibentuk oleh hambatan dalam masyarakat", "Disabilitas adalah kesalahan pribadi", "Disabilitas dapat diabaikan di sekolah", "Disabilitas hanya memengaruhi pekerjaan"], "answer": 0, "explain": "Model sosial menyatakan bahwa hambatan dalam masyarakat, bukan hanya keterbatasan fisik, yang membatasi partisipasi.", "src": "UN CRPD (2006), Article 24"}, {"ch": 0, "q": "Apa hubungan antara SDG 4 dan SDG 5 (Kesetaraan Gender)?", "options": ["Tidak ada hubungannya", "Pendidikan anak perempuan mendukung kesetaraan gender", "Kesetaraan gender mengurangi pembelajaran", "Anak perempuan tidak boleh bersekolah"], "answer": 1, "explain": "Pendidikan adalah alat utama untuk kesetaraan gender, yaitu Tujuan 5.", "src": "UN 2030 Agenda (2015)"}], "11": [{"ch": 0, "q": "Bagaimana Agenda 2030 menggambarkan hubungan antar tujuan?", "options": ["Terpadu dan tidak dapat dipisahkan", "Terpisah dan tidak berhubungan", "Saling bersaing dan bertentangan", "Opsional dan diabaikan"], "answer": 0, "explain": "Agenda 2030 menggambarkan tujuan-tujuan itu sebagai sesuatu yang terpadu dan tidak dapat dipisahkan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa yang disediakan sistem pemantauan pendidikan nasional?", "options": ["Hanya tanggal libur setiap sekolah dalam setahun", "Data berkala untuk memantau kemajuan dan mengidentifikasi kesenjangan", "Hanya hadiah ujian untuk siswa terbaik di setiap kelas", "Hanya desain bangunan untuk sekolah baru di kota"], "answer": 1, "explain": "Sistem pemantauan mengumpulkan data agar pemerintah dapat melihat kemajuan dan kesenjangan.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "Apa itu EMIS?", "options": ["Perangkat musik elektronik yang digunakan dalam band sekolah", "Alat penilaian ujian yang hanya digunakan guru di akhir", "Sistem informasi manajemen pendidikan yang mengumpulkan data sekolah", "Rencana manajemen energi untuk semua gedung sekolah"], "answer": 2, "explain": "EMIS adalah sistem informasi manajemen pendidikan, yang mencatat data sekolah dan peserta didik.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "Apa itu koherensi kebijakan untuk pembangunan berkelanjutan?", "options": ["Setiap sektor mengabaikan yang lain dan bekerja sendiri sepenuhnya", "Kebijakan yang sengaja saling bertentangan setiap tahun", "Kebijakan yang berhenti tepat di batas setiap kabupaten", "Menyelaraskan kebijakan lintas sektor agar saling mendukung"], "answer": 3, "explain": "Koherensi kebijakan berarti berbagai bidang kebijakan bekerja bersama menuju tujuan yang sama.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa arti lokalisasi SDG 4?", "options": ["Menyesuaikan tujuan dengan prioritas dan konteks setempat", "Menyalin persis rencana satu negara", "Mengabaikan kebutuhan setempat", "Memindahkan sekolah ke bulan"], "answer": 0, "explain": "Lokalisasi membantu masyarakat menyesuaikan tujuan global dengan kondisi mereka sendiri.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa itu akuntabilitas dalam kebijakan pendidikan?", "options": ["Menghindari semua tanggung jawab atas hasil sekolah", "Meminta pemimpin bertanggung jawab atas hasil dan belanja", "Menyembunyikan hasil dari publik dan media", "Menyalahkan siswa saja atas setiap kegagalan di kelas"], "answer": 1, "explain": "Akuntabilitas berarti para pemimpin bertanggung jawab atas cara sumber daya pendidikan digunakan.", "src": "UNESCO"}, {"ch": 0, "q": "Apa itu keterlibatan multi-pemangku kepentingan dalam pendidikan?", "options": ["Hanya melibatkan pejabat pemerintah dalam setiap keputusan", "Hanya melibatkan perusahaan swasta dan stafnya", "Melibatkan pemerintah, keluarga, guru, dan masyarakat", "Tidak melibatkan siapa pun selain siswa dalam keputusan apa pun"], "answer": 2, "explain": "Pendekatan multi-pemangku kepentingan menyatukan banyak kelompok untuk merencanakan dan memantau pendidikan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Apa itu rencana sektor pendidikan?", "options": ["Rencana khusus untuk lapangan olahraga dan taman bermain di setiap kota", "Jadwal untuk satu sekolah di satu kabupaten selama satu semester", "Daftar tanggal libur untuk seluruh negeri setiap tahun", "Rencana yang menetapkan prioritas dan tindakan untuk pendidikan"], "answer": 3, "explain": "Rencana sektor memandu cara pemerintah berinvestasi dan bertindak di seluruh bidang pendidikan.", "src": "UNESCO"}, {"ch": 1, "q": "Apa itu survei anak di luar sekolah?", "options": ["Survei yang menemukan anak-anak yang tidak bersekolah", "Survei bus sekolah di jalan-jalan utama kota", "Survei libur guru di seluruh negeri", "Survei seragam sekolah yang dipakai di setiap kota setiap tahun"], "answer": 0, "explain": "Survei anak di luar sekolah membantu pemerintah menemukan anak-anak yang perlu didaftarkan.", "src": "UNESCO"}, {"ch": 1, "q": "Mengapa akses universal memerlukan lebih dari sekadar membangun sekolah?", "options": ["Membangun sekolah selalu cukup dengan sendirinya untuk semua orang", "Biaya, jarak, diskriminasi, dan kualitas juga penting", "Akses hanya bergantung pada cuaca di setiap musim", "Akses tidak pernah menjadi masalah bagi keluarga mana pun di wilayah mana pun"], "answer": 1, "explain": "Akses bergantung pada banyak faktor, bukan hanya jumlah gedung sekolah.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa itu pendaftaran sesuai usia?", "options": ["Anak yang terdaftar di kelas mana pun tanpa memandang usia", "Anak yang tidak pernah terdaftar", "Anak yang terdaftar di kelas sesuai dengan usianya", "Anak yang hanya terdaftar di perguruan tinggi"], "answer": 2, "explain": "Pendaftaran sesuai usia membantu anak belajar pada tingkat yang sesuai.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa itu peserta didik yang usianya melebihi batas?", "options": ["Guru yang terlalu tua untuk mengajar di kelas mana pun sekarang", "Peserta didik yang menyelesaikan kelas lebih cepat lalu keluar sekolah", "Peserta didik yang tanggal lahirnya tidak tercatat di berkas mana pun", "Peserta didik yang lebih tua dari usia normal untuk kelasnya"], "answer": 3, "explain": "Peserta didik yang usianya melebihi batas sering memerlukan program fleksibel untuk mengejar ketertinggalan.", "src": "UNESCO"}, {"ch": 1, "q": "Apa itu pembelajaran jarak jauh saat sekolah ditutup?", "options": ["Belajar dari jarak jauh dengan memanfaatkan teknologi atau bahan ajar", "Belajar hanya di ruangan yang sama dengan guru setiap hari", "Belajar hanya dalam diam tanpa berbicara sama sekali", "Belajar hanya pada malam hari ketika sekolah tutup"], "answer": 0, "explain": "Pembelajaran jarak jauh menjaga pendidikan tetap berjalan ketika sekolah tidak bisa dibuka.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Mengapa penutupan sekolah merugikan pembelajaran?", "options": ["Tidak berpengaruh sama sekali", "Anak kehilangan waktu dan bisa tertinggal", "Selalu meningkatkan pembelajaran", "Hanya berdampak pada guru"], "answer": 1, "explain": "Penutupan yang panjang dapat menyebabkan hilangnya pembelajaran, terutama bagi anak yang kurang beruntung.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa itu inklusi digital bagi peserta didik?", "options": ["Menghindari semua teknologi dalam kehidupan sehari-hari dan setiap tugas belajar", "Hanya menggunakan kertas dan pensil untuk semua pelajaran setiap hari", "Akses ke perangkat, koneksi, dan keterampilan untuk menggunakannya", "Memiliki mobil dan mengendarainya ke sekolah bersama teman setiap hari"], "answer": 2, "explain": "Inklusi digital berarti semua orang dapat mengakses dan menggunakan alat belajar digital.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Mengapa sebagian peserta didik kesulitan belajar di rumah?", "options": ["Mereka lebih suka merasa bosan", "Rumah selalu ideal", "Mereka tidak ingin belajar", "Tidak ada ruang tenang, perangkat, atau dukungan di rumah"], "answer": 3, "explain": "Kondisi rumah memengaruhi seberapa baik peserta didik dapat belajar dari jarak jauh.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Apa arti kesinambungan antar-kelas?", "options": ["Naik dari satu kelas ke kelas berikutnya tanpa keluar sekolah", "Mengulang kelas yang sama selamanya tanpa pernah naik", "Keluar sekolah secara permanen dan tidak pernah kembali ke kelas mana pun", "Pindah ke sekolah baru di negara lain setiap tahun"], "answer": 0, "explain": "Kesinambungan berarti peserta didik bergerak melalui kelas secara stabil.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu kebijakan pencegahan putus sekolah?", "options": ["Langkah yang mengeluarkan peserta didik", "Langkah yang menjaga peserta didik berisiko tetap bersekolah", "Langkah yang menutup sekolah", "Langkah yang mengabaikan ketidakhadiran"], "answer": 1, "explain": "Kebijakan pencegahan putus sekolah berfokus pada dukungan dini bagi peserta didik yang berisiko.", "src": "UNESCO"}, {"ch": 2, "q": "Apa yang ditunjukkan oleh kesenjangan penyelesaian pendidikan antara anak perempuan dan laki-laki?", "options": ["Kelompok mana yang rata-rata lebih tinggi di setiap sekolah setiap tahun", "Kelompok mana yang membaca lebih cepat selama setiap pelajaran", "Apakah satu kelompok lebih kecil kemungkinannya menyelesaikan sekolah", "Kelompok mana yang jauh lebih menyukai olahraga dibanding yang lain"], "answer": 2, "explain": "Kesenjangan penyelesaian mengungkap ketimpangan yang memerlukan kebijakan yang tepat sasaran.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 2, "q": "Apa itu program reintegrasi bagi mantan peserta didik?", "options": ["Program yang mengirim peserta didik bekerja ke luar negeri", "Program yang mengakhiri pendidikan", "Program khusus untuk guru", "Program yang membantu mantan peserta didik kembali ke sekolah"], "answer": 3, "explain": "Program reintegrasi mendukung peserta didik untuk kembali mengikuti pendidikan.", "src": "UNESCO"}, {"ch": 2, "q": "Apa yang dilakukan kebijakan transisi yang baik bagi peserta didik yang pindah antarsistem?", "options": ["Membuat perpindahan antar sekolah atau jenjang lebih lancar", "Membuat perpindahan jauh lebih sulit bagi setiap peserta didik", "Menghentikan semua perpindahan antar sekolah dan jenjang", "Membatalkan ujian pada akhir setiap tahun ajaran"], "answer": 0, "explain": "Kebijakan transisi yang baik mengurangi risiko putus sekolah di antara jenjang.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu pemilahan dini (early tracking) di sekolah?", "options": ["Melacak anak-anak hanya dengan GPS", "Membagi peserta didik ke jalur terpisah sejak usia muda", "Mengajarkan hal yang sama kepada semua anak di semua usia", "Mencatat cuaca"], "answer": 1, "explain": "Pemilahan dini dapat membatasi peluang di kemudian hari dan memperlebar ketimpangan.", "src": "UNESCO"}, {"ch": 2, "q": "Mengapa pengelompokan kemampuan menjadi masalah bagi kesetaraan?", "options": ["Selalu membantu peserta didik terlemah", "Tidak berpengaruh pada kesetaraan", "Dapat mengunci peserta didik yang kurang beruntung ke jalur yang lebih rendah", "Membuat pembelajaran lebih mudah bagi semua"], "answer": 2, "explain": "Pemilahan dini dapat memperkuat ketidakberuntungan jika tidak fleksibel.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Apa arti ungkapan \"menyelesaikan saja tidak cukup\"?", "options": ["Menyelesaikan sekolah adalah satu-satunya tujuan", "Pembelajaran tidak penting", "Sekolah sebaiknya tutup lebih awal", "Kualitas pembelajaran juga harus dijamin"], "answer": 3, "explain": "Menyelesaikan sekolah itu penting, tetapi peserta didik juga perlu belajar dengan baik.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu nilai tambah (value-added) dalam pengukuran pembelajaran?", "options": ["Kemajuan yang ditambahkan sekolah di luar kondisi awal peserta didik", "Uang yang ditambahkan sekolah ke anggaran tahunannya setiap tahun", "Berat semua buku yang disimpan di rak sekolah", "Jumlah guru yang direkrut sekolah setiap tahun"], "answer": 0, "explain": "Nilai tambah mengukur seberapa besar sekolah membantu peserta didik berkembang.", "src": "UNESCO"}, {"ch": 3, "q": "Apa nama kesenjangan pembelajaran yang dikaitkan dengan pendapatan keluarga?", "options": ["Kesenjangan cuaca", "Kesenjangan pembelajaran sosial-ekonomi", "Kesenjangan olahraga", "Kesenjangan sepatu"], "answer": 1, "explain": "Kesenjangan pembelajaran yang dikaitkan dengan pendapatan keluarga menunjukkan kesempatan yang tidak setara.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Mengapa negara melakukan pembandingan (benchmarking) hasil belajar mereka?", "options": ["Untuk menghindari mengajar", "Untuk menilai guru berdasarkan tinggi badan", "Untuk membandingkan kemajuan dan menetapkan target yang realistis", "Untuk menghukum peserta didik"], "answer": 2, "explain": "Pembandingan membantu negara membandingkan hasil dan belajar satu sama lain.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa yang didukung oleh pembelajaran dalam bahasa ibu?", "options": ["Hanya menulis dalam bahasa Inggris", "Hanya bernyanyi", "Tidak ada pembelajaran", "Pemahaman dan membaca awal"], "answer": 3, "explain": "Pengajaran dalam bahasa ibu membantu peserta didik memahami dan membangun keterampilan membaca awal.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "Apa itu keselarasan kurikulum dengan penilaian?", "options": ["Tes yang mengukur apa yang diajarkan kurikulum", "Tes yang tidak pernah cocok dengan pelajaran", "Tes yang mencakup topik yang tidak pernah diajarkan", "Tes yang tidak pernah dinilai"], "answer": 0, "explain": "Keselarasan yang baik memastikan tes mengukur pembelajaran yang dimaksudkan kurikulum.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu analitik pembelajaran (learning analytics)?", "options": ["Menghitung jumlah meja", "Memanfaatkan data tentang pembelajaran untuk meningkatkan pengajaran", "Menebak cuaca", "Menjual data kepada perusahaan"], "answer": 1, "explain": "Analitik pembelajaran menggunakan data untuk memahami pembelajaran dan memandu dukungan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Apa itu metakognisi?", "options": ["Hanya berpikir tentang olahraga", "Melupakan semua pikiran", "Berpikir tentang cara berpikir sendiri", "Berpikir hanya dalam satu bahasa"], "answer": 2, "explain": "Metakognisi membantu peserta didik merencanakan, memantau, dan meningkatkan pembelajaran mereka.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu pembelajaran mendalam dalam pendidikan?", "options": ["Belajar sedalam mungkin di dalam kolam renang", "Menghafal tanpa memahami", "Belajar hanya di ruangan gelap", "Memahami gagasan dengan cukup baik untuk menerapkannya"], "answer": 3, "explain": "Pembelajaran mendalam melampaui hafalan menuju pemahaman dan penerapan gagasan.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu keterserapan kerja (employability) dalam pendidikan?", "options": ["Keterampilan yang membantu orang mendapatkan dan mempertahankan pekerjaan", "Tidak mampu bekerja di pekerjaan atau bidang apa pun", "Memiliki perusahaan tetapi tidak pernah bekerja di dalamnya", "Menghindari segala jenis pekerjaan sepanjang hidup"], "answer": 0, "explain": "Keterserapan kerja menggabungkan keterampilan, pengetahuan, dan sikap yang mendukung pekerjaan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu relevansi pendidikan dengan pasar kerja?", "options": ["Pembelajaran yang sama sekali mengabaikan pekerjaan", "Pembelajaran yang sesuai dengan keterampilan yang dibutuhkan ekonomi", "Pembelajaran hanya untuk seniman", "Pembelajaran yang tidak pernah berubah"], "answer": 1, "explain": "Pendidikan yang relevan mempersiapkan peserta didik untuk pekerjaan yang ada atau yang sedang muncul.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu magang (apprenticeship)?", "options": ["Sejenis ujian sekolah yang diikuti di akhir setiap tahun", "Libur guru yang diambil di tengah setiap semester", "Belajar pekerjaan sambil bekerja di bawah orang yang berpengalaman", "Sejenis seragam sekolah yang dipakai setiap pelajaran setiap hari"], "answer": 2, "explain": "Magang menggabungkan pelatihan di tempat kerja dengan pembelajaran formal.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu kompetensi digital bagi guru dan peserta didik?", "options": ["Menghindari semua teknologi", "Hanya menggunakan kertas", "Merusak komputer", "Menggunakan alat digital dengan aman dan efektif"], "answer": 3, "explain": "Kompetensi digital membantu orang menggunakan teknologi untuk belajar, bekerja, dan berkomunikasi.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu literasi kecerdasan buatan (AI)?", "options": ["Memahami apa yang dapat dan tidak dapat dilakukan AI", "Percaya bahwa AI selalu benar", "Menolak belajar tentang AI", "Menganggap AI menggantikan semua pemikiran"], "answer": 0, "explain": "Literasi AI membantu peserta didik menggunakan AI secara bertanggung jawab dan mempertanyakan keluarannya.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa tujuan kebijakan pembelajaran sepanjang hayat?", "options": ["Mengakhiri semua pembelajaran setelah tahun-tahun sekolah selesai", "Menciptakan kesempatan belajar di setiap tahap kehidupan", "Membatasi semua pembelajaran hanya untuk kaum muda di kota", "Menghentikan semua program pendidikan orang dewasa di seluruh negeri"], "answer": 1, "explain": "Kebijakan pembelajaran sepanjang hayat mendukung pembelajaran dari masa kanak-kanak hingga usia lanjut.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu pengakuan keterampilan yang diperoleh secara informal?", "options": ["Mengabaikan semua keterampilan yang dipelajari di tempat kerja selama bertahun-tahun", "Hanya menghitung nilai dari ujian tertulis sekolah setiap tahun", "Memberikan kredit resmi untuk keterampilan yang dipelajari di luar sekolah", "Mencabut sertifikat yang sudah diperoleh orang di tempat kerja"], "answer": 2, "explain": "Pengakuan membantu orang memanfaatkan keterampilan yang diperoleh dari pekerjaan dan kehidupan bermasyarakat.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu inovasi dalam pendidikan?", "options": ["Mempertahankan metode lama selamanya", "Menyalin buku teks lama", "Menghentikan semua gagasan baru", "Gagasan baru yang meningkatkan pembelajaran"], "answer": 3, "explain": "Inovasi dalam pendidikan memperkenalkan pendekatan baru yang meningkatkan pembelajaran.", "src": "UNESCO"}, {"ch": 5, "q": "Apa itu penganggaran responsif gender dalam pendidikan?", "options": ["Anggaran yang mempertimbangkan kebutuhan anak perempuan dan laki-laki", "Anggaran yang mengabaikan gender sepenuhnya dalam setiap keputusan", "Anggaran hanya untuk anak laki-laki di setiap sekolah kabupaten", "Anggaran hanya untuk guru beserta gaji dan liburannya"], "answer": 0, "explain": "Penganggaran responsif gender merencanakan dana untuk memenuhi kebutuhan yang berbeda.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa itu retensi anak perempuan di sekolah menengah?", "options": ["Menjauhkan anak perempuan dari sekolah", "Menjaga anak perempuan tetap terdaftar hingga mereka menyelesaikan sekolah", "Menahan anak perempuan di satu kelas", "Menahan anak perempuan di rumah"], "answer": 1, "explain": "Retensi anak perempuan berarti mereka tetap bersekolah hingga menyelesaikan pendidikan.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa yang dilakukan perlindungan sosial bagi keluarga miskin?", "options": ["Memisahkan anak dari keluarga dan rumah mereka", "Menambah biaya sekolah baru bagi setiap keluarga miskin di wilayah itu", "Membantu keluarga menghadapi guncangan dan menjaga anak tetap bersekolah", "Menghentikan makan siang gratis bagi anak miskin setiap hari"], "answer": 2, "explain": "Perlindungan sosial dapat membantu keluarga menjaga anak tetap bersekolah pada masa sulit.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa itu kemiskinan anak?", "options": ["Memiliki terlalu banyak mainan", "Bertubuh terlalu tinggi", "Terlalu pintar", "Hidup dalam kemiskinan sejak masa kanak-kanak"], "answer": 3, "explain": "Kemiskinan anak membatasi akses ke makanan, kesehatan, perumahan, dan pembelajaran.", "src": "UNESCO"}, {"ch": 5, "q": "Apa itu segregasi etnis di sekolah?", "options": ["Peserta didik dari kelompok etnis berbeda dipisahkan", "Semua peserta didik berbagi satu lapangan bermain", "Semua peserta didik berbicara dalam satu bahasa", "Semua peserta didik memakai seragam yang sama"], "answer": 0, "explain": "Segregasi memisahkan peserta didik dan membatasi pembelajaran serta pemahaman bersama.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Mengapa kebijakan harus menjangkau komunitas nomaden dan berpindah-pindah?", "options": ["Mereka tidak pernah membutuhkan sekolah dan tidak menginginkannya", "Mereka sering tertinggal dari pendidikan tanpa pilihan yang fleksibel", "Mereka selalu kaya dan tidak memiliki kebutuhan pendidikan", "Mereka lebih memilih tidak bersekolah sepanjang hidup"], "answer": 1, "explain": "Komunitas yang berpindah-pindah memerlukan pendidikan yang fleksibel agar dapat menjangkau pendidikan.", "src": "UNESCO"}, {"ch": 5, "q": "Apa itu kuota afirmatif dalam pendidikan?", "options": ["Kuota yang melarang kelompok yang kurang beruntung", "Kuota khusus untuk guru", "Porsi tempat yang disediakan untuk kelompok yang kurang beruntung", "Kuota khusus untuk olahraga"], "answer": 2, "explain": "Kuota dapat membantu peserta didik yang kurang beruntung memperoleh tempat yang mungkin terlewat.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa arti akses yang setara bagi anak perempuan di daerah konflik?", "options": ["Menutup semua sekolah anak perempuan", "Mengirim anak perempuan jauh dari rumah", "Mengabaikan kebutuhan anak perempuan", "Jalur dan sekolah yang aman dan terlindungi"], "answer": 3, "explain": "Ruang yang terlindungi dan jalur yang aman membantu anak perempuan tetap belajar di tengah konflik.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "Apa penyebab umum berkurangnya jumlah guru?", "options": ["Gaji rendah, kondisi buruk, dan kurangnya pengembangan karier", "Terlalu banyak promosi dan kenaikan karier yang cepat untuk semua orang", "Keamanan kerja yang tinggi dan kontrak jangka panjang untuk semua staf", "Libur panjang dan jam kerja singkat untuk setiap guru"], "answer": 0, "explain": "Guru meninggalkan profesi ketika gaji, kondisi, dan prospek karier lemah.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu penjaminan mutu guru?", "options": ["Sistem yang menyingkirkan semua guru", "Sistem yang memeriksa bahwa pengajaran memenuhi standar yang ditetapkan", "Sistem yang menetapkan libur guru", "Sistem yang mengabaikan siswa"], "answer": 1, "explain": "Penjaminan mutu membantu menjaga pengajaran tetap pada standar tinggi.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu penilaian kinerja guru (appraisal)?", "options": ["Tes kecepatan lari guru di lintasan sekolah", "Pemeringkatan guru berdasarkan tinggi badan di ruang guru", "Tinjauan kinerja guru untuk mendukung peningkatan", "Pemeriksaan rencana liburan guru sepanjang musim panas"], "answer": 2, "explain": "Penilaian kinerja membantu guru merefleksikan diri dan meningkat, jika dilakukan secara adil.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu kurikulum pendidikan guru?", "options": ["Jadwal sekolah untuk anak-anak", "Daftar seragam sekolah", "Menu untuk makan siang sekolah", "Mata pelajaran dan keterampilan yang diajarkan kepada calon guru"], "answer": 3, "explain": "Kurikulum pendidikan guru mempersiapkan guru dalam mata pelajaran dan pedagogi.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa guru memerlukan pelatihan dalam penilaian?", "options": ["Untuk menilai pembelajaran secara akurat dan mendukungnya", "Agar mereka dapat menghindari pemberian nilai", "Agar mereka dapat menghentikan ujian", "Agar mereka dapat memberi nilai tanpa bukti"], "answer": 0, "explain": "Pelatihan penilaian membantu guru menggunakan bukti untuk mendukung peserta didik.", "src": "UNESCO GEM Report 2026"}, {"ch": 6, "q": "Apa itu agensi guru?", "options": ["Guru yang patuh pada setiap perintah tanpa berpikir", "Kemampuan guru untuk membentuk praktiknya sendiri", "Guru yang tidak pernah membuat rencana", "Guru yang hanya bekerja pada malam hari"], "answer": 1, "explain": "Agensi guru berarti guru dapat mengambil keputusan yang meningkatkan pembelajaran.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu komunitas belajar profesional guru?", "options": ["Kelompok yang bersaing untuk mendapatkan libur terbanyak", "Klub yang hanya menjual bahan ajar", "Guru yang belajar bersama untuk meningkatkan praktik mereka", "Kelompok peserta didik yang mengajar"], "answer": 2, "explain": "Komunitas belajar membantu guru berbagi gagasan dan meningkat bersama.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa yang dipengaruhi oleh rasa tujuan seorang guru?", "options": ["Hanya harga kapur tulis", "Hanya biaya gedung sekolah", "Tidak ada yang penting", "Motivasi dan komitmen terhadap peserta didik"], "answer": 3, "explain": "Tujuan dan komitmen memengaruhi cara guru terlibat dengan peserta didik.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Apa itu kemitraan publik-swasta dalam pendidikan?", "options": ["Kerja sama antara pemerintah dan penyedia swasta", "Perusahaan swasta yang menjalankan semua sekolah menurut hukum", "Pemerintah yang melepaskan semua tanggung jawabnya", "Sekolah yang membayar pemerintah"], "answer": 0, "explain": "Kemitraan dapat memperluas layanan tetapi harus diatur untuk menjamin mutu dan kesetaraan.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu regulasi sekolah swasta?", "options": ["Melarang semua sekolah swasta secara default dalam hukum nasional", "Aturan yang memastikan sekolah swasta memenuhi standar mutu dan keselamatan", "Membiarkan sekolah swasta menulis dan menetapkan aturan sendiri secara bebas", "Mengabaikan sekolah swasta sepenuhnya dan tidak pernah memeriksanya"], "answer": 1, "explain": "Regulasi melindungi peserta didik di sekolah swasta.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu ruang fiskal untuk pendidikan?", "options": ["Ruang untuk membangun mobil dan truk di pusat kota", "Ruang di lorong sekolah untuk loker dan bangku baru", "Ruang dalam anggaran pemerintah untuk menambah belanja", "Ruang untuk perkemahan liburan di pedesaan setiap musim panas"], "answer": 2, "explain": "Ruang fiskal adalah keleluasaan yang dimiliki pemerintah untuk membiayai pendidikan.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Apa itu belanja pajak (tax expenditure) untuk pendidikan?", "options": ["Uang yang dibelanjakan untuk ujian, penilaian, dan percetakan sekolah setiap tahun", "Uang yang dibelanjakan untuk libur dan cuti guru setiap tahun", "Uang yang dibelanjakan untuk peralatan olahraga dan permainan sekolah setiap semester", "Keringanan pajak yang mengurangi penerimaan pemerintah untuk pendidikan"], "answer": 3, "explain": "Belanja pajak adalah keringanan yang dapat mengurangi dana yang tersedia untuk pendidikan.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu efektivitas biaya (cost-effectiveness) dalam pendidikan?", "options": ["Mencapai kemajuan belajar dengan biaya terendah", "Membelanjakan sebanyak mungkin", "Membelanjakan hanya untuk gedung", "Menghindari semua belanja"], "answer": 0, "explain": "Program yang efektif dari sisi biaya menghasilkan lebih banyak pembelajaran untuk setiap satuan dana.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu pembebasan biaya (fee waiver)?", "options": ["Biaya pendaftaran terlambat untuk keluarga baru di sekolah", "Pembebasan biaya sekolah bagi keluarga yang tidak mampu membayar", "Bonus yang dibayarkan kepada guru atas kinerja baik setiap periode", "Biaya naik bus sekolah selama satu semester penuh"], "answer": 1, "explain": "Pembebasan biaya membantu keluarga miskin agar anak mereka tetap bersekolah.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu kredibilitas anggaran dalam pendidikan?", "options": ["Dana tidak pernah dibelanjakan untuk sekolah sepanjang tahun", "Anggaran disusun secara rahasia oleh beberapa orang setiap tahun", "Dana pendidikan yang direncanakan benar-benar dibelanjakan untuk sekolah", "Anggaran berubah setiap jam tanpa alasan yang jelas"], "answer": 2, "explain": "Kredibilitas anggaran berarti dana pendidikan yang direncanakan benar-benar tersalurkan.", "src": "UNESCO"}, {"ch": 7, "q": "Peran apa yang dapat dimainkan asosiasi orang tua dan guru dalam pendanaan sekolah?", "options": ["Membayar seluruh gaji guru sendirian", "Menggantikan seluruh pendanaan pemerintah", "Menutup sekolah", "Mengumpulkan dana atau dukungan untuk membantu kebutuhan sekolah"], "answer": 3, "explain": "Asosiasi orang tua dapat membantu sekolah, meskipun tidak seharusnya menggantikan pendanaan publik.", "src": "UNESCO"}, {"ch": 8, "q": "Konvensi tahun 2006 manakah yang berkaitan dengan penyandang disabilitas?", "options": ["Konvensi PBB tentang Hak-hak Penyandang Disabilitas", "Konvensi Jenewa tentang perdagangan internasional dan tarif", "Perjanjian Tokyo tentang olahraga dan pelatihan atlet", "Konvensi Lima tentang pertanian, pangan, dan penggunaan lahan"], "answer": 0, "explain": "CRPD diadopsi pada 2006 dan mencakup hak atas pendidikan.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "Pada tahun berapa CRPD diadopsi?", "options": ["1994", "2006", "1989", "2015"], "answer": 1, "explain": "CRPD PBB diadopsi pada tahun 2006.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "Apa yang dikatakan Pasal 29 Konvensi tentang Hak Anak mengenai pendidikan?", "options": ["Pendidikan harus mahal", "Pendidikan hanya untuk anak laki-laki", "Pendidikan harus mengembangkan kepribadian dan bakat setiap anak", "Pendidikan harus dilarang bagi anak penyandang disabilitas"], "answer": 2, "explain": "Pasal 29 menetapkan tujuan pendidikan, termasuk penghormatan terhadap hak dan budaya.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "Apa singkatan umum dari Pendidikan untuk Semua?", "options": ["ELA", "EAL", "EFR", "EFA"], "answer": 3, "explain": "EFA adalah singkatan umum dari Pendidikan untuk Semua.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Apa yang dikatakan Deklarasi Incheon 2015 tentang pembelajaran sepanjang hayat?", "options": ["Harus menjadi bagian dari pendidikan untuk semua usia", "Harus berakhir pada usia 14 tahun", "Harus dilarang", "Hanya berlaku untuk guru"], "answer": 0, "explain": "Deklarasi Incheon mendorong kesempatan pembelajaran sepanjang hayat bagi semua orang.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Lembaga manakah yang menerbitkan data pendidikan global?", "options": ["Asosiasi Sepak Bola Dunia", "Institut Statistik UNESCO", "Dewan Hotel Internasional", "Dana Musik Global"], "answer": 1, "explain": "Institut Statistik UNESCO menerbitkan data pendidikan global.", "src": "UNESCO GEM Report 2026"}, {"ch": 8, "q": "Apa hubungan antara MDG dan SDG?", "options": ["SDG tidak menggantikan apa pun", "SDG membatalkan semua tujuan", "SDG dibangun dari pelajaran MDG", "MDG masih berlaku"], "answer": 2, "explain": "SDG dibangun di atas MDG dan memperluas agenda.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Untuk tujuan apa Kemitraan Global untuk Pendidikan didirikan?", "options": ["Menjual buku teks ke seluruh dunia", "Menyelenggarakan acara olahraga", "Mendanai perjalanan antariksa", "Mendukung pendidikan di negara berpendapatan rendah"], "answer": 3, "explain": "Kemitraan Global untuk Pendidikan membantu negara berpendapatan rendah memperbaiki pembelajaran.", "src": "UNESCO GEM Report 2026"}, {"ch": 8, "q": "Apa yang dikatakan Deklarasi Universal Hak Asasi Manusia tentang orang tua dan pendidikan?", "options": ["Orang tua memiliki hak utama untuk memilih pendidikan bagi anak-anak mereka", "Orang tua tidak memiliki peran sama sekali dalam persekolahan anak-anak mereka", "Orang tua hanya boleh memilih olahraga dan permainan untuk anak-anak mereka", "Orang tua harus membayar semua sekolah di kota mereka"], "answer": 0, "explain": "Pasal 26 menyatakan bahwa orang tua memiliki hak utama untuk memilih jenis pendidikan bagi anak-anak mereka.", "src": "UN General Assembly (1948)"}, {"ch": 9, "q": "Apa itu pendidikan dan pengasuhan anak usia dini (ECEC)?", "options": ["Kursus pendidikan orang dewasa khusus bagi pekerja", "Layanan belajar dan pengasuhan bagi anak kecil sebelum sekolah dasar", "Kursus pelatihan guru bagi guru baru di negara itu", "Ujian menengah dan penilaian akhir untuk semua siswa"], "answer": 1, "explain": "ECEC mencakup layanan yang mendukung perkembangan dan pembelajaran anak kecil.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Apa itu pendekatan multisektor dalam pendidikan anak usia dini?", "options": ["Hanya pendidikan yang bekerja sendiri di setiap sekolah dan kelas", "Hanya kesehatan yang bekerja sendiri di setiap klinik dan rumah sakit lokal", "Kesehatan, gizi, pendidikan, dan perlindungan bekerja bersama", "Hanya olahraga yang bekerja sendiri di halaman dan lapangan"], "answer": 2, "explain": "Pendekatan multisektor menjawab kebutuhan anak di seluruh layanan.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu rasio anak per staf?", "options": ["Jumlah mainan per anak", "Jumlah jendela di sebuah ruangan", "Jumlah staf yang sedang libur", "Jumlah anak yang diasuh oleh setiap orang dewasa"], "answer": 3, "explain": "Rasio yang lebih rendah memungkinkan perhatian dan interaksi yang lebih besar dengan setiap anak.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa anak kecil memerlukan pengasuh yang konsisten?", "options": ["Hubungan yang stabil mendukung pertumbuhan emosi dan kognitif", "Konsistensi tidak penting sama sekali bagi anak kecil", "Anak lebih suka banyak orang asing daripada keluarga dekat", "Pengasuh sebaiknya berganti setiap hari agar bervariasi"], "answer": 0, "explain": "Pengasuh yang stabil dan konsisten membantu anak merasa aman dan belajar.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu dukungan dini bagi anak penyandang disabilitas?", "options": ["Menunggu sampai sekolah untuk mulai", "Bantuan dini untuk membangun keterampilan dan perkembangan", "Menjauhkan anak dari orang lain", "Mengabaikan kebutuhan perkembangan"], "answer": 1, "explain": "Intervensi dini membantu anak penyandang disabilitas mengembangkan keterampilan lebih cepat.", "src": "UN CRPD (2006), Article 24"}, {"ch": 9, "q": "Apa itu skrining perkembangan?", "options": ["Tes untuk memilih sepatu sekolah yang tepat bagi setiap murid", "Ujian yang harus dilalui guru di akhir setiap tahun", "Pemeriksaan singkat untuk menemukan anak yang mungkin memerlukan dukungan", "Pemeriksaan rencana liburan sekolah setempat setiap tahun"], "answer": 2, "explain": "Skrining membantu mengidentifikasi anak yang mungkin memerlukan penilaian atau bantuan lebih lanjut.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu pengalaman buruk masa kanak-kanak (ACE)?", "options": ["Liburan keluarga yang menyenangkan setiap musim panas", "Hadiah sekolah untuk kerja baik dan usaha setiap semester", "Sejenis ujian yang dijalani murid sekolah dasar setiap tahun", "Peristiwa yang penuh tekanan atau merugikan di masa kanak-kanak yang dapat memengaruhi perkembangan"], "answer": 3, "explain": "ACE dapat memengaruhi kesehatan dan pembelajaran, sehingga dukungan dini sangat penting.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Apa itu strategi literasi nasional?", "options": ["Rencana untuk meningkatkan literasi di seluruh negeri", "Rencana untuk menjual koran", "Rencana untuk menutup perpustakaan", "Rencana untuk satu sekolah saja"], "answer": 0, "explain": "Strategi literasi nasional menetapkan tujuan dan tindakan untuk meningkatkan keterampilan membaca dan menulis.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Apa itu literasi di era digital?", "options": ["Menghindari semua layar dan perangkat digital di setiap kelas", "Membaca, menulis, dan memahami informasi dalam bentuk digital", "Hanya membaca buku kertas dan tidak ada yang lain setiap saat", "Hanya menulis dengan pensil di atas kertas dalam setiap mata pelajaran"], "answer": 1, "explain": "Literasi digital memperluas kegiatan membaca dan menulis ke lingkungan daring.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Apa itu survei literasi orang dewasa?", "options": ["Survei liburan dan rencana perjalanan orang dewasa setiap tahun", "Survei mobil orang dewasa dan pemiliknya di setiap kota", "Survei yang mengukur kemampuan membaca dan berhitung orang dewasa", "Survei kebiasaan olahraga dan kebugaran orang dewasa di setiap kota"], "answer": 2, "explain": "Survei literasi orang dewasa mengukur keterampilan untuk memandu kebijakan.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Mengapa perpustakaan penting bagi literasi orang dewasa?", "options": ["Hanya untuk anak-anak dan siswa muda di setiap kota", "Hanya menjual buku dan tidak pernah meminjamkannya", "Tertutup bagi semua orang dewasa setiap saat dalam sehari", "Memberi akses gratis ke buku dan dukungan belajar"], "answer": 3, "explain": "Perpustakaan mendukung orang dewasa yang ingin membaca, belajar, dan membangun keterampilan.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Apa itu keberagaman bahasa dalam literasi?", "options": ["Berbagai bahasa yang digunakan dalam sebuah komunitas", "Hanya menggunakan satu bahasa di mana-mana", "Melarang bahasa daerah", "Hanya mengajarkan bahasa isyarat"], "answer": 0, "explain": "Keberagaman bahasa penting karena peserta didik membaca dan belajar dalam banyak bahasa.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Apa itu keterlibatan membaca peserta didik?", "options": ["Seberapa cepat peserta didik berjalan", "Seberapa besar peserta didik menikmati dan memilih untuk membaca", "Seberapa keras peserta didik berbicara", "Berapa banyak buku yang terjual"], "answer": 1, "explain": "Keterlibatan membaca menunjukkan seberapa termotivasi peserta didik untuk membaca.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Apa itu program jembatan literasi?", "options": ["Program yang membangun jembatan sungguhan di atas sungai dan jalan", "Program yang menutup perpustakaan kota setiap tahun", "Program yang membantu peserta didik beralih dari literasi dasar ke literasi yang lebih tinggi", "Program khusus olahraga dan permainan tanpa kegiatan membaca sama sekali"], "answer": 2, "explain": "Program jembatan literasi membantu peserta didik melampaui kemampuan membaca dasar.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "Apa itu sistem pendidikan inklusif?", "options": ["Sistem tempat peserta didik dipisahkan berdasarkan disabilitas", "Sistem tanpa guru", "Sistem tanpa aturan", "Sistem tempat semua peserta didik diikutsertakan dalam pendidikan umum"], "answer": 3, "explain": "Sistem inklusif menerima peserta didik dan menyesuaikan pendidikan umum dengan mereka.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu nondiskriminasi dalam pendidikan?", "options": ["Memperlakukan peserta didik secara adil tanpa memandang disabilitas, gender, atau latar belakang", "Memperlakukan peserta didik berbeda berdasarkan kelompok di setiap sekolah", "Menolak masuknya peserta didik ke sekolah hanya karena kelompoknya", "Membebankan biaya tambahan kepada sebagian peserta didik berdasarkan latar belakang mereka"], "answer": 0, "explain": "Nondiskriminasi adalah prinsip dasar pendidikan inklusif.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa prinsip representasi dalam Universal Design for Learning?", "options": ["Hanya menyajikan satu format", "Menyajikan informasi dalam berbagai format", "Menyembunyikan informasi dari peserta didik", "Hanya menyajikan dalam keadaan hening"], "answer": 1, "explain": "Berbagai cara representasi membantu peserta didik mengakses materi dengan cara yang berbeda.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Mengapa peserta didik penyandang disabilitas perlu didengar dalam pengambilan keputusan?", "options": ["Mereka tidak boleh pernah dimintai pendapat", "Hanya orang dewasa yang boleh memutuskan", "Mereka paling mengetahui kebutuhan mereka sendiri", "Keputusan harus diambil tanpa melibatkan mereka"], "answer": 2, "explain": "Peserta didik penyandang disabilitas harus dimintai pendapat tentang keputusan yang memengaruhi mereka.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu partisipasi peserta didik dalam keputusan sekolah?", "options": ["Peserta didik tetap diam", "Peserta didik membuat semua keputusan sendirian", "Peserta didik tidak pernah hadir dalam rapat", "Peserta didik ikut serta dalam keputusan yang memengaruhi mereka"], "answer": 3, "explain": "Partisipasi peserta didik membangun tanggung jawab dan menghormati hak-hak mereka.", "src": "UN Convention on the Rights of the Child (1989), Article 12"}, {"ch": 11, "q": "Apa itu iklim sekolah?", "options": ["Suasana sekolah bagi peserta didik dan staf", "Hanya suhu di dalam sekolah", "Banyaknya sinar matahari di sekolah", "Jumlah bus sekolah"], "answer": 0, "explain": "Iklim sekolah membentuk apakah peserta didik merasa aman, dihormati, dan termotivasi.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "Apa itu kebijakan anti-perundungan?", "options": ["Aturan yang mendorong perundungan di antara murid di setiap sekolah", "Aturan dan tindakan untuk menghentikan perundungan dan melindungi peserta didik", "Kebijakan yang sama sekali mengabaikan perundungan di setiap sekolah", "Kebijakan yang menghukum korban perundungan setiap semester"], "answer": 1, "explain": "Kebijakan anti-perundungan melindungi peserta didik dan mendukung lingkungan belajar yang aman.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Mengapa pendidikan inklusif baik bagi masyarakat?", "options": ["Menciptakan perpecahan", "Mengurangi pembelajaran bagi semua", "Membangun keadilan dan kohesi sosial", "Hanya berguna bagi sedikit orang"], "answer": 2, "explain": "Pendidikan inklusif membangun kohesi sosial dan keadilan bagi semua orang.", "src": "UN CRPD (2006), Article 24"}], "12": [{"ch": 0, "q": "Apa itu terutama Kerangka Aksi Pendidikan 2030?", "options": ["Panduan bagi negara-negara untuk menerapkan SDG 4", "Buku aturan olahraga untuk turnamen sekolah", "Undang-undang perbankan untuk bank nasional", "Aturan seragam sekolah untuk semua seragam"], "answer": 0, "explain": "Kerangka ini memberikan panduan untuk menerapkan SDG 4 di seluruh negara.", "src": "Incheon Framework for Action (2015)"}, {"ch": 0, "q": "Apa itu kerangka indikator global SDG?", "options": ["Daftar tanggal libur untuk setiap sekolah dalam setahun", "Kumpulan indikator yang disepakati untuk mengukur kemajuan", "Daftar buku yang dilarang di setiap perpustakaan sekolah", "Peta yang menunjukkan lokasi semua gedung sekolah"], "answer": 1, "explain": "Kerangka indikator global menyediakan indikator bersama untuk melacak kemajuan SDG.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Apa yang ditunjukkan oleh klasifikasi tingkat indikator SDG?", "options": ["Seberapa tinggi setiap siswa pada awal tahun ajaran", "Berapa banyak sekolah yang dibangun suatu negara dari waktu ke waktu", "Seberapa mapan metodologi setiap indikator", "Berapa banyak uang yang dikumpulkan sekolah dari kegiatan setiap tahun"], "answer": 2, "explain": "Tingkat menunjukkan kesiapan metodologi dan ketersediaan data indikator.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Mengapa indikator SDG 4 dipilah berdasarkan tingkat kekayaan?", "options": ["Untuk menentukan peringkat keluarga berdasarkan tinggi badan anggotanya", "Untuk memilih seragam sekolah", "Untuk menentukan tanggal libur", "Untuk mengungkap kesenjangan antara siswa kaya dan miskin"], "answer": 3, "explain": "Pemilahan menurut kekayaan menunjukkan apakah kemajuan menjangkau siswa yang lebih miskin.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "Apa yang diukur oleh pelacakan pembiayaan SDG 4?", "options": ["Berapa banyak dana yang diinvestasikan dan ke mana tujuannya", "Berapa banyak pohon yang ditanam", "Berapa banyak klub olahraga yang ada", "Berapa banyak buku yang dicetak"], "answer": 0, "explain": "Pelacakan pembiayaan menunjukkan tingkat investasi dan apakah sampai kepada kelompok prioritas.", "src": "Incheon Framework for Action (2015)"}, {"ch": 0, "q": "Apa itu evaluasi kebijakan dalam pendidikan?", "options": ["Memilih warna baru yang resmi untuk mengecat fasad sekolah", "Menilai apakah kebijakan mencapai tujuannya", "Menghitung jendela di fasad semua gedung sekolah", "Menulis puisi tentang liburan musim panas setiap tahun"], "answer": 1, "explain": "Evaluasi membantu memutuskan apakah kebijakan perlu dilanjutkan, diubah, atau dihentikan.", "src": "UNESCO"}, {"ch": 0, "q": "Apa itu kebijakan berbasis bukti?", "options": ["Kebijakan yang dibuat tanpa data atau bukti apa pun", "Kebijakan yang dibuat dengan menebak-nebak tanpa dasar", "Kebijakan yang didasarkan pada penelitian dan data", "Kebijakan yang disalin dari film dan televisi"], "answer": 2, "explain": "Kebijakan berbasis bukti menggunakan penelitian untuk memandu keputusan.", "src": "UNESCO"}, {"ch": 0, "q": "Mengapa pemerintah memerlukan sistem data pendidikan?", "options": ["Untuk menghindari pengambilan keputusan tentang pendidikan setiap tahun", "Untuk menyembunyikan informasi dari masyarakat dan pers", "Untuk menggantikan guru dengan sistem otomatis", "Untuk merencanakan, memantau, dan memperbaiki pendidikan"], "answer": 3, "explain": "Sistem data mendukung perencanaan, pemantauan, dan akuntabilitas.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "Apa arti SDG 4 memiliki sinergi dengan tujuan lain?", "options": ["Kemajuan pendidikan membantu kemajuan tujuan lainnya", "Pendidikan menghambat semua tujuan lainnya", "Pendidikan tidak berkaitan dengan tujuan lainnya sama sekali", "Tujuan lainnya hanya berpengaruh pada olahraga"], "answer": 0, "explain": "Pendidikan mendukung tujuan kesehatan, kesetaraan gender, pekerjaan, dan iklim.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Apa itu tidak terdaftar sekolah (non-enrolment)?", "options": ["Terdaftar tetapi tidak hadir", "Berusia sekolah tetapi tidak terdaftar", "Hanya bersekolah di luar negeri", "Mengajar tanpa dibayar"], "answer": 1, "explain": "Tidak terdaftar berarti anak usia sekolah tidak tercatat di sekolah mana pun.", "src": "UNESCO"}, {"ch": 1, "q": "Apa itu akses efektif terhadap pendidikan?", "options": ["Akses yang hanya ada di atas kertas tanpa realisasi nyata", "Akses tanpa guru sama sekali di sekolah mana pun", "Akses yang juga mengarah pada pembelajaran nyata", "Akses yang hanya berlaku satu hari saja dalam setahun"], "answer": 2, "explain": "Akses efektif berarti anak hadir dan belajar, bukan sekadar terdaftar.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa itu jalur pengejaran (catch-up) bagi anak dengan sekolah yang terputus?", "options": ["Jalur yang memungkinkan keluar dari sekolah tanpa prosedur apa pun", "Jalur untuk melompati kelas tanpa belajar apa pun sama sekali", "Jalur yang menutup sekolah dan menjauhkan anak dari sekolah", "Jalur yang membantu mereka mengejar ketertinggalan dan kembali"], "answer": 3, "explain": "Jalur pengejaran membantu anak yang kehilangan sekolah untuk kembali ke pendidikan.", "src": "UNESCO"}, {"ch": 1, "q": "Apa yang dituntut hak atas pendidikan dari negara?", "options": ["Membuat pendidikan tersedia, dapat diakses, dapat diterima, dan dapat disesuaikan", "Menyediakan pendidikan hanya untuk keluarga kaya di negara itu", "Menyediakan pendidikan hanya di kota-kota besar negara itu", "Membuat pendidikan sepenuhnya opsional bagi setiap keluarga"], "answer": 0, "explain": "Empat A menggambarkan kewajiban inti dari hak atas pendidikan.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "Apa arti ketersediaan (availability) dalam hak atas pendidikan?", "options": ["Sekolah tidak pernah dibuka untuk siswa mana pun sepanjang tahun", "Ada sekolah dan program yang berfungsi dalam jumlah yang memadai", "Sekolah hanya dibuka pada akhir pekan dan hari libur", "Sekolah hanya untuk digunakan guru pada hari-hari tertentu"], "answer": 1, "explain": "Ketersediaan berarti cukup banyak lembaga dan program yang berfungsi.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "Apa arti keberterimaan (acceptability) dalam hak atas pendidikan?", "options": ["Pendidikan yang selalu membosankan bagi siswa", "Pendidikan yang dirahasiakan dari keluarga", "Pendidikan yang berkualitas baik dan sesuai budaya", "Pendidikan yang hanya memakai satu bahasa saja"], "answer": 2, "explain": "Keberterimaan berarti pendidikan relevan, aman, dan berkualitas baik.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "Apa arti kemampuan menyesuaikan diri (adaptability) dalam hak atas pendidikan?", "options": ["Pendidikan yang tidak pernah berubah mengikuti kebutuhan zaman", "Pendidikan yang mengabaikan kebutuhan siswa dan keluarga", "Pendidikan yang tetap sama selamanya di setiap sekolah", "Pendidikan yang menyesuaikan diri dengan kebutuhan siswa dan masyarakat"], "answer": 3, "explain": "Kemampuan menyesuaikan diri berarti pendidikan menanggapi kebutuhan yang berubah.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "Mengapa pengeluaran pribadi untuk pendidikan menjadi perhatian?", "options": ["Keluarga membayar biaya secara langsung sehingga anak bisa tersingkir", "Keluarga tidak pernah membayar apa pun untuk pendidikan", "Pengeluaran pribadi selalu membantu sekolah dan semua siswa secara setara", "Hanya berdampak pada guru dan gaji bulanannya"], "answer": 0, "explain": "Biaya langsung yang tinggi dapat menghalangi keluarga miskin menyekolahkan anak mereka.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Apa itu respons pendidikan kemanusiaan?", "options": ["Pendidikan yang hanya diberikan saat damai dan stabil", "Dukungan untuk pendidikan dalam keadaan darurat dan krisis", "Respons yang langsung menutup sekolah yang terdampak", "Respons yang hanya dibatasi pada bidang olahraga sekolah"], "answer": 1, "explain": "Respons pendidikan kemanusiaan menjaga pembelajaran tetap berjalan saat krisis.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Apa itu jalur pembelajaran dari sekolah menengah ke pendidikan tinggi?", "options": ["Jalur untuk keluar dari pendidikan selamanya dan tidak kembali", "Jalur hanya untuk orang dewasa yang sudah keluar dari sekolah", "Jalur dari sekolah menengah ke studi lanjutan", "Jalur ke klub olahraga untuk setiap siswa setelah sekolah"], "answer": 2, "explain": "Jalur menghubungkan pendidikan menengah dengan studi dan pelatihan tingkat lanjut.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu pendidikan tinggi (tertiary education)?", "options": ["Pendidikan sebelum taman kanak-kanak untuk balita", "Pendidikan hanya untuk guru dalam kursus pelatihan mereka", "Pendidikan hanya untuk olahraga dan pelatihan atlet di klub", "Pendidikan setelah sekolah menengah, seperti universitas atau akademi"], "answer": 3, "explain": "Pendidikan tinggi mencakup universitas, akademi, dan pelatihan teknis lanjutan.", "src": "UNESCO"}, {"ch": 2, "q": "Apa itu keadilan dalam penyelesaian pendidikan?", "options": ["Tingkat penyelesaian yang serupa antar kelompok", "Tingkat penyelesaian yang hanya menguntungkan orang kaya", "Tingkat penyelesaian yang tidak pernah diukur sama sekali", "Tingkat penyelesaian yang selalu nol di setiap daerah"], "answer": 0, "explain": "Keadilan penyelesaian berarti kelompok-kelompok menyelesaikan sekolah dengan tingkat yang serupa.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Siapa yang disebut pemuda putus pendidikan dini (early leavers)?", "options": ["Anak muda yang keluar lebih awal untuk liburan", "Anak muda yang keluar tanpa menyelesaikan sekolah menengah", "Guru yang meninggalkan pekerjaannya lebih awal", "Siswa yang selesai lebih dulu"], "answer": 1, "explain": "Putus pendidikan dini adalah anak muda yang keluar tanpa ijazah sekolah menengah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apa itu program kejuruan di tingkat menengah atas?", "options": ["Kursus memasak dan membuat kue yang hanya diajarkan di rumah", "Gelar universitas dalam sejarah, hukum, dan politik", "Kursus yang memberikan keterampilan praktis dan kualifikasi", "Perkemahan liburan untuk anak kecil pada musim panas"], "answer": 2, "explain": "Program kejuruan menengah atas memberikan keterampilan praktis dan kualifikasi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Mengapa menyelesaikan sekolah penting untuk kehidupan nanti?", "options": ["Tidak berpengaruh sama sekali di kemudian hari", "Hanya berpengaruh pada liburan", "Hanya berpengaruh pada olahraga", "Sangat memengaruhi kesehatan, pekerjaan, dan penghasilan"], "answer": 3, "explain": "Menyelesaikan sekolah terkait dengan kesehatan, pekerjaan, dan kesejahteraan yang lebih baik.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Apa itu penyelesaian belajar sepanjang hayat?", "options": ["Menyelesaikan pembelajaran pada usia berapa pun", "Menyelesaikan pembelajaran hanya sebelum usia sepuluh tahun", "Berhenti belajar setelah sekolah", "Belajar hanya untuk guru"], "answer": 0, "explain": "Penyelesaian sepanjang hayat berarti orang dapat menuntaskan pembelajaran pada usia berapa pun.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Apa itu pembalikan putus sekolah (reversal of dropout)?", "options": ["Siswa yang keluar lebih cepat dari sebelumnya", "Siswa yang kembali ke pendidikan setelah keluar", "Siswa yang mundur hanya saat ujian", "Siswa yang memotong biaya sekolah setiap tahun"], "answer": 1, "explain": "Pembalikan putus sekolah berarti siswa kembali masuk dan menuntaskan pendidikan.", "src": "UNESCO"}, {"ch": 3, "q": "Apa target keterampilan dasar bagi negara-negara?", "options": ["Memastikan anak hanya belajar musik dan bernyanyi selama SD", "Memastikan anak tidak pernah belajar membaca di SD", "Memastikan sebagian besar anak mencapai literasi dan numerasi dasar pada akhir SD", "Memastikan anak membolos dan tinggal di rumah selama SD"], "answer": 2, "explain": "Banyak negara bertujuan memastikan anak mencapai keterampilan dasar di awal SD.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa arti kualitas pembelajaran?", "options": ["Pembelajaran yang hanya cepat dan terburu-buru di setiap pelajaran", "Pembelajaran yang hanya panjang dan melelahkan bagi setiap siswa", "Pembelajaran yang menghindari semua ujian dan tes bagi setiap siswa", "Pembelajaran yang relevan, efektif, dan adil"], "answer": 3, "explain": "Pembelajaran berkualitas memenuhi kebutuhan siswa dan membawa kemajuan nyata.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Apa itu relevansi kurikulum?", "options": ["Menghubungkan pembelajaran dengan kehidupan siswa dan pekerjaan di masa depan", "Mengajarkan hal-hal yang tidak pernah digunakan dalam kehidupan nyata", "Mengabaikan kehidupan dan minat siswa sepenuhnya", "Mengajar hanya dalam bahasa kuno yang tidak dipakai lagi sama sekali"], "answer": 0, "explain": "Kurikulum yang relevan menghubungkan pelajaran dengan kehidupan nyata dan kebutuhan masa depan.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu kebijakan pendidikan berbasis hasil?", "options": ["Menetapkan target berdasarkan ukuran sekolah", "Menetapkan target berdasarkan apa yang bisa dilakukan siswa", "Menetapkan target berdasarkan tinggi badan guru", "Menetapkan target berdasarkan lamanya libur"], "answer": 1, "explain": "Kebijakan berbasis hasil berfokus pada keterampilan dan capaian yang diraih siswa.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu translanguaging di kelas?", "options": ["Melarang semua bahasa kecuali satu di sekolah bagi setiap siswa", "Hanya memakai bahasa isyarat di setiap pelajaran sepanjang hari sekolah", "Menggunakan semua bahasa siswa untuk mendukung pembelajaran", "Mengajar tanpa suara dan tanpa berbicara di pelajaran mana pun"], "answer": 2, "explain": "Translanguaging memanfaatkan seluruh repertoar bahasa siswa untuk membantu mereka belajar.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "Apa itu beban kognitif?", "options": ["Berat tas sekolah yang dibawa setiap hari", "Jumlah halaman dalam sebuah buku pelajaran", "Jumlah cahaya matahari di sebuah ruangan", "Jumlah usaha mental yang dibutuhkan sebuah tugas"], "answer": 3, "explain": "Beban kognitif penting untuk bagaimana siswa memproses dan mengingat informasi.", "src": "Harvard Center on the Developing Child"}, {"ch": 3, "q": "Apa itu latihan berjarak (spaced practice)?", "options": ["Membagi sesi belajar dari waktu ke waktu untuk meningkatkan ingatan", "Menjejalkan semuanya dalam satu malam sebelum ujian", "Tidak pernah berlatih materi yang sama lagi kapan pun", "Hanya berlatih selama libur panjang sekolah setiap tahun"], "answer": 0, "explain": "Latihan berjarak membantu siswa mengingat informasi lebih baik dari waktu ke waktu.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu latihan mengingat kembali (retrieval practice)?", "options": ["Menyalin catatan berulang kali tanpa berusaha mengingat", "Mengingat informasi dari memori untuk memperkuat pembelajaran", "Hanya membaca judul materi tanpa isinya", "Mengabaikan apa yang sudah diajarkan di kelas"], "answer": 1, "explain": "Latihan mengingat kembali memperkuat memori dengan mengingat apa yang telah dipelajari.", "src": "UNESCO"}, {"ch": 3, "q": "Apa itu bias dalam penilaian (assessment bias)?", "options": ["Tes yang selalu adil bagi semua siswa", "Tes yang tidak pernah mengukur pembelajaran sama sekali", "Tes yang secara tidak adil menguntungkan kelompok tertentu", "Tes yang hanya mengukur tinggi badan siswa"], "answer": 2, "explain": "Bias dalam penilaian dapat merugikan siswa karena alasan yang tidak berkaitan dengan kemampuan.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "Apa itu keterampilan lintas bidang (transversal skills)?", "options": ["Keterampilan untuk satu mata pelajaran saja", "Keterampilan untuk tidur dengan nyenyak setiap malam", "Keterampilan hanya untuk menyeberang jalan dengan aman", "Keterampilan yang berguna di banyak mata pelajaran dan pekerjaan"], "answer": 3, "explain": "Keterampilan lintas bidang seperti komunikasi dan kerja tim berlaku di mana saja.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu pedagogi digital?", "options": ["Metode pengajaran yang memanfaatkan teknologi dengan baik", "Pengajaran tanpa teknologi sama sekali", "Pengajaran hanya dengan mesin yang rusak dan tidak dipakai", "Pengajaran hanya melalui keheningan di dalam kelas"], "answer": 0, "explain": "Pedagogi digital memakai teknologi untuk mendukung pembelajaran, bukan sekadar menggantikan kertas.", "src": "UNESCO"}, {"ch": 4, "q": "Apa itu privasi data dalam teknologi pendidikan?", "options": ["Membagikan data siswa kepada orang asing", "Melindungi informasi pribadi siswa", "Menjual data siswa kepada pihak lain", "Mengabaikan aturan privasi yang berlaku"], "answer": 1, "explain": "Privasi data melindungi siswa dari penyalahgunaan informasi pribadi mereka.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu peningkatan keterampilan (upskilling)?", "options": ["Kehilangan keterampilan yang sudah dimiliki saat bekerja setiap hari", "Belajar hanya untuk anak SD setiap tahun ajaran lengkap", "Mempelajari keterampilan baru untuk mengikuti pekerjaan yang berubah", "Berhenti pelatihan begitu memulai pekerjaan dan karier baru"], "answer": 2, "explain": "Peningkatan keterampilan membantu pekerja beradaptasi dengan teknologi dan pekerjaan baru.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu pelatihan ulang keterampilan (reskilling)?", "options": ["Melupakan semua keterampilan dan pengetahuan dari masa lalu", "Belajar hanya olahraga dan permainan untuk bersenang-senang", "Berhenti bekerja sepenuhnya dan tinggal di rumah selamanya", "Mempelajari keterampilan baru untuk pindah ke jenis pekerjaan lain"], "answer": 3, "explain": "Pelatihan ulang menyiapkan orang untuk peran baru saat pekerjaan lama berubah.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu pelatihan pekerjaan hijau (green jobs)?", "options": ["Menyiapkan pekerja untuk pekerjaan yang membantu lingkungan", "Pelatihan untuk pekerjaan yang merusak alam dan lingkungan", "Pelatihan hanya untuk mengecat dinding dan bangunan", "Pelatihan khusus untuk memainkan salah satu olahraga sekolah"], "answer": 0, "explain": "Pelatihan pekerjaan hijau menyiapkan orang untuk pekerjaan yang berkelanjutan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu kompetensi global?", "options": ["Mengabaikan negara lain dan warganya sepenuhnya", "Memahami dan terlibat dengan dunia serta budaya lain", "Hanya mengetahui sejarah satu negara dan tidak ada yang lain", "Menolak bepergian atau bertemu orang dari negara lain"], "answer": 1, "explain": "Kompetensi global membantu siswa memahami isu global dan berkomunikasi lintas budaya.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Apa itu pembelajaran sosial-emosional (SEL)?", "options": ["Belajar menghindari semua perasaan dan emosi di setiap situasi", "Hanya belajar matematika dan tidak ada yang lain di sekolah setiap hari", "Belajar mengelola emosi dan menjalin hubungan baik dengan orang lain", "Belajar diam di setiap situasi sosial yang dimasuki"], "answer": 2, "explain": "SEL membangun kesadaran diri, empati, dan keterampilan hubungan.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Apa itu norma gender?", "options": ["Aturan tentang apa yang dimakan anak-anak di kantin setiap sekolah", "Ukuran setiap gedung sekolah di seluruh kota", "Aturan tentang libur yang hanya berlaku untuk guru dan staf", "Harapan bersama tentang bagaimana anak perempuan dan laki-laki harus berperilaku"], "answer": 3, "explain": "Norma gender membentuk peran dan peluang anak perempuan dan laki-laki.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa hubungan antara menjaga anak perempuan tetap bersekolah dan pernikahan anak?", "options": ["Ini salah satu cara paling efektif untuk menunda pernikahan anak", "Ini mendorong anak perempuan untuk menikah sangat muda setiap tahun", "Ini tidak berhubungan dengan pernikahan di usia mana pun di komunitas mana pun", "Ini menutup sekolah untuk anak perempuan di komunitas setiap triwulan"], "answer": 0, "explain": "Menjaga anak perempuan tetap bersekolah adalah salah satu cara paling efektif untuk menunda pernikahan anak.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa dampak kehamilan remaja terhadap sekolah?", "options": ["Selalu meningkatkan kualitas sekolah", "Dapat mengganggu pendidikan anak perempuan", "Tidak berhubungan dengan sekolah sama sekali", "Hanya berdampak pada anak laki-laki seusianya"], "answer": 1, "explain": "Kehamilan dapat mengganggu sekolah, sehingga kebijakan kembali bersekolah dan dukungan itu penting.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Apa itu sanitasi inklusif di sekolah?", "options": ["Toilet hanya untuk guru dan staf di sekolah", "Tidak ada toilet atau fasilitas cuci sama sekali bagi siswa mana pun", "Toilet dan fasilitas cuci yang memenuhi kebutuhan semua orang", "Toilet yang selalu terkunci bagi siswa pada siang hari"], "answer": 2, "explain": "Sanitasi inklusif mencakup fasilitas bagi anak perempuan dan siswa penyandang disabilitas.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Selain uang, apa saja yang termasuk kemiskinan siswa?", "options": ["Terlalu banyak buku untuk dibaca di rumah setiap malam", "Terlalu banyak teman untuk bermain setelah sekolah", "Terlalu banyak waktu luang untuk bermain setiap hari setelah sekolah", "Kurangnya makanan, transportasi, perlengkapan, dan ruang belajar"], "answer": 3, "explain": "Kemiskinan siswa mencakup kurangnya makanan, transportasi, perlengkapan, dan ruang belajar yang tenang.", "src": "UNESCO"}, {"ch": 5, "q": "Apa itu kerugian berlapis (multiple disadvantage)?", "options": ["Menghadapi beberapa hambatan sekaligus", "Tidak memiliki hambatan sama sekali", "Hanya menghadapi satu hambatan kecil", "Memiliki terlalu banyak dukungan"], "answer": 0, "explain": "Kerugian berlapis berarti beberapa hambatan saling menggabung dan membutuhkan respons terpadu.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Apa arti inklusi pengungsi dalam sistem nasional?", "options": ["Memisahkan siswa pengungsi dari siswa lain secara permanen", "Memasukkan siswa pengungsi ke sistem pendidikan nasional", "Menolak siswa pengungsi yang datang ke sekolah", "Hanya mengajar pengungsi secara daring tanpa tatap muka"], "answer": 1, "explain": "Inklusi pengungsi dalam sistem nasional membantu mereka mengakses pendidikan dan ijazah yang diakui.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Apa itu pendidikan nomaden?", "options": ["Pendidikan yang selalu berada di satu gedung", "Pendidikan hanya untuk anak-anak yang tinggal di kota", "Pendidikan yang dirancang untuk komunitas yang berpindah-pindah", "Pendidikan tanpa guru sama sekali"], "answer": 2, "explain": "Pendidikan nomaden menyesuaikan pengajaran dan jadwal dengan keluarga yang berpindah.", "src": "UNESCO"}, {"ch": 5, "q": "Apa yang diukur oleh indeks kesetaraan dalam pendidikan?", "options": ["Tinggi gedung sekolah di setiap kecamatan", "Jumlah bel sekolah yang berbunyi setiap hari", "Lamanya libur guru di setiap wilayah", "Seberapa banyak akses atau hasil yang dibandingkan antar kelompok"], "answer": 3, "explain": "Indeks kesetaraan merangkum seberapa adil pendidikan itu terdistribusi.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Apa arti keseimbangan gender di antara guru?", "options": ["Jumlah guru perempuan dan laki-laki yang seimbang", "Hanya laki-laki yang boleh mengajar di sekolah di sini", "Hanya perempuan yang boleh mengajar di sekolah di sini", "Tidak ada guru yang dibutuhkan di sekolah mana pun di sini"], "answer": 0, "explain": "Keseimbangan gender di antara guru dapat memengaruhi teladan dan budaya sekolah.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "Apa itu analisis penawaran dan permintaan guru?", "options": ["Membandingkan warna dan pakaian favorit guru setiap tahun", "Membandingkan berapa banyak guru yang dibutuhkan dengan yang tersedia", "Menghitung berapa banyak libur dan hari cuti yang diambil guru setiap tahun", "Membandingkan tinggi badan guru di ruang guru setiap tahun"], "answer": 1, "explain": "Analisis penawaran dan permintaan membantu pemerintah merencanakan perekrutan.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu reformasi pendidikan guru?", "options": ["Menghapus semua pelatihan guru yang ada saat ini", "Mengakhiri karier guru di seluruh negeri", "Mengubah cara guru dilatih dan dipersiapkan", "Hanya menutup lembaga pendidikan guru yang tersisa"], "answer": 2, "explain": "Reformasi pendidikan guru memperbarui pelatihan agar sesuai dengan kelas modern.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu pengembangan kepemimpinan sekolah?", "options": ["Melatih pemimpin untuk tidak mengajar di kelas yang mereka kunjungi", "Melatih pemimpin hanya dalam olahraga dan permainan sekolah", "Melatih pemimpin untuk menutup sekolah lebih awal setiap triwulan", "Melatih kepala sekolah untuk membimbing pengajaran dan pembelajaran"], "answer": 3, "explain": "Mengembangkan pemimpin meningkatkan mutu sekolah.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa yang termasuk jenjang karier guru?", "options": ["Langkah yang jelas untuk meningkatkan keterampilan dan tanggung jawab", "Tidak ada langkah bagi guru untuk naik dalam kariernya", "Hanya libur dan jeda panjang setiap tahun bagi guru", "Hanya pemotongan gaji dan lebih sedikit staf setiap triwulan"], "answer": 0, "explain": "Jenjang yang jelas membantu guru berkembang dan bertahan dalam profesi.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu hubungan guru dan siswa?", "options": ["Hubungan tanpa kontak sama sekali", "Ikatan positif yang mendukung pembelajaran", "Hanya urusan bisnis tanpa ikatan emosional", "Persaingan yang menghentikan pembelajaran"], "answer": 1, "explain": "Hubungan yang kuat membantu siswa merasa aman dan termotivasi.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Apa itu waktu kerja guru?", "options": ["Hanya jumlah menit yang dihitung dalam satu hari sekolah penuh", "Waktu yang dihabiskan untuk bersenang-senang saat berlibur", "Total waktu yang dihabiskan guru untuk mengajar dan pekerjaan terkait", "Waktu yang dihabiskan setiap pagi untuk bepergian dengan bus sekolah"], "answer": 2, "explain": "Waktu kerja mencakup perencanaan, koreksi, dan tugas lain di luar kelas.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Mengapa sebagian guru membutuhkan dukungan tambahan di wilayah krisis?", "options": ["Mereka tidak menghadapi kesulitan khusus dalam pekerjaan sehari-hari", "Mereka tidak pernah membutuhkan dukungan apa pun dalam praktik mengajar", "Mereka memiliki terlalu banyak libur dan hari cuti selama tahun ajaran", "Mereka menghadapi kondisi tidak aman dan trauma"], "answer": 3, "explain": "Guru dalam krisis mungkin membutuhkan pelatihan dan dukungan kesejahteraan.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Apa itu belanja pendidikan per siswa?", "options": ["Rata-rata belanja untuk setiap siswa", "Jumlah total buku yang tersedia di setiap sekolah dasar", "Biaya total penyelenggaraan satu ujian nasional", "Biaya satu rute bus sekolah selama setahun penuh"], "answer": 0, "explain": "Belanja per siswa membantu membandingkan sumber daya antar sistem.", "src": "UNESCO"}, {"ch": 7, "q": "Mengapa pembagian biaya bisa menjadi masalah bagi akses?", "options": ["Selalu mengurangi biaya yang ditanggung keluarga di komunitas", "Dapat membebankan biaya kepada keluarga yang tidak mampu membayar", "Tidak berdampak pada akses siswa ke sekolah sama sekali", "Menghapus sepenuhnya semua biaya yang ditanggung keluarga"], "answer": 1, "explain": "Pembagian biaya dapat menciptakan hambatan bagi keluarga miskin jika tidak dikelola dengan baik.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu keringanan utang untuk pendidikan?", "options": ["Menambah utang publik untuk mendanai olahraga sekolah saja", "Menutup semua sekolah negeri di negara itu dengan segera", "Mengurangi pembayaran utang agar dana bisa dialihkan ke sekolah", "Memaksa guru membayar utang pemerintah"], "answer": 2, "explain": "Keringanan utang dapat membebaskan dana untuk pendidikan.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "Apa itu pembiayaan inovatif untuk pendidikan?", "options": ["Membayar guru hanya dengan emas dan batu berharga", "Hanya menjual meja dan perlengkapan sekolah bekas setiap tahun", "Menutup sekolah secara sistematis untuk menghemat uang", "Cara-cara baru untuk menggalang dana bagi pendidikan"], "answer": 3, "explain": "Pembiayaan inovatif mencakup mekanisme baru untuk menggalang pendanaan.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Apa itu rencana pembiayaan pendidikan?", "options": ["Rencana yang menunjukkan bagaimana pendidikan akan dibiayai dari waktu ke waktu", "Rencana khusus untuk libur sekolah tanpa pelajaran sama sekali", "Rencana untuk membeli mobil dan van untuk staf sekolah", "Rencana tanpa angka, biaya, atau tanggal sama sekali"], "answer": 0, "explain": "Rencana pembiayaan menghubungkan tujuan pendidikan dengan uang yang dibutuhkan untuk mencapainya.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Apa itu desentralisasi fiskal dalam pendidikan?", "options": ["Mengambil semua uang ke ibu kota setiap tahun anggaran", "Memberi pemerintah daerah lebih banyak kendali atas dana pendidikan", "Melarang pemerintah daerah mengambil keputusan apa pun", "Menutup sekolah lokal satu per satu sampai tidak ada yang tersisa"], "answer": 1, "explain": "Desentralisasi dapat membantu respons lokal, tetapi memerlukan perlindungan kesetaraan.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu hibah pemerataan (equalisation grant)?", "options": ["Uang yang membuat daerah kaya semakin kaya setiap tahun", "Uang khusus untuk libur dan cuti guru setiap musim panas", "Dana tambahan yang membantu daerah miskin menyamai daerah kaya", "Uang untuk menutup sekolah di daerah miskin setiap tahun"], "answer": 2, "explain": "Hibah pemerataan mengurangi kesenjangan antar wilayah.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu klausul kedaluwarsa (sunset clause) dalam pendanaan pendidikan?", "options": ["Klausul tentang matahari terbenam dan warna langit sore", "Aturan untuk mengatur malam dansa di sekolah-sekolah", "Aturan yang menggandakan pendanaan secara otomatis setiap hari", "Aturan yang mengakhiri pendanaan setelah jangka waktu tertentu kecuali diperpanjang"], "answer": 3, "explain": "Klausul kedaluwarsa mengakhiri program kecuali ditinjau dan diperpanjang.", "src": "UNESCO"}, {"ch": 7, "q": "Apa itu pendapatan negara untuk pendidikan?", "options": ["Uang yang dikumpulkan pemerintah dari pajak dan sumber lain", "Uang dari tiket olahraga yang dijual di stadion nasional setiap tahun", "Uang dari biaya sekolah yang hanya dibayar keluarga tanpa pajak", "Uang yang hanya diperoleh dari pariwisata dan perjalanan setiap tahun"], "answer": 0, "explain": "Pendapatan negara adalah dasar utama pendanaan pendidikan publik.", "src": "UNESCO"}, {"ch": 8, "q": "Apa yang dipromosikan oleh Pernyataan Salamanca?", "options": ["Sekolah khusus yang terpisah dari anak lain", "Sekolah inklusif untuk semua anak", "Sekolah khusus untuk orang dewasa", "Sekolah khusus untuk guru"], "answer": 1, "explain": "Pernyataan Salamanca mempromosikan inklusi bagi anak dengan kebutuhan khusus.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "Tahun berapa Deklarasi Universal Hak Asasi Manusia diadopsi?", "options": ["1989", "1990", "1948", "2015"], "answer": 2, "explain": "UDHR diadopsi oleh Majelis Umum PBB pada tahun 1948.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Konvensi mana yang menetapkan hak anak, termasuk pendidikan?", "options": ["Perjanjian Perdagangan", "Piagam Olahraga Jenewa", "Kode Pelayaran Tokyo", "Konvensi tentang Hak-Hak Anak"], "answer": 3, "explain": "CRC, diadopsi pada 1989, menetapkan hak anak termasuk hak atas pendidikan.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "Apa yang dijanjikan tujuan Dakar untuk anak usia dini?", "options": ["Memperluas dan meningkatkan pengasuhan dan pendidikan anak usia dini", "Menutup layanan anak usia dini di seluruh negeri", "Mengabaikan anak kecil dan keluarganya sepenuhnya", "Melarang taman kanak-kanak di setiap desa dan kota"], "answer": 0, "explain": "Tujuan Dakar mencakup perluasan dan peningkatan pengasuhan dan pendidikan anak usia dini.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Apa yang ditargetkan Deklarasi Incheon untuk tahun 2030?", "options": ["Hanya pendidikan tinggi untuk siswa terbaik setiap tahun", "Pendidikan inklusif, setara, berkualitas, dan pembelajaran sepanjang hayat", "Hanya olahraga dan permainan untuk setiap sekolah di seluruh negeri", "Hanya sekolah musim panas di setiap wilayah selama bulan-bulan musim panas"], "answer": 1, "explain": "Deklarasi Incheon menetapkan tujuan ini untuk 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Mengapa SDG 2015 melampaui MDG?", "options": ["Hanya untuk negara miskin di dunia dan tidak untuk yang lain", "Hanya mencakup pendidikan dan tidak ada yang lain di dunia", "Bersifat universal dan mencakup isu yang lebih luas seperti iklim dan ketimpangan", "Mengakhiri semua bantuan bagi negara termiskin di dunia"], "answer": 2, "explain": "SDG berlaku untuk semua negara dan mencakup lebih banyak isu daripada MDG.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Apa tujuan Pendidikan untuk Pembangunan Berkelanjutan (ESD)?", "options": ["Hanya mengajarkan undang-undang lingkungan hidup", "Menutup kelas sains di seluruh sekolah", "Berhenti mempelajari topik lingkungan di semua jenjang", "Membekali siswa untuk bertindak demi masa depan yang berkelanjutan"], "answer": 3, "explain": "ESD membantu siswa memahami keberlanjutan dan mengambil tindakan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Apa yang dilakukan Pelapor Khusus PBB tentang hak atas pendidikan?", "options": ["Melaporkan hak atas pendidikan di seluruh dunia", "Mengelola sebuah sekolah dan mengawasi stafnya setiap hari", "Menjadi wasit pertandingan sepak bola di liga profesional", "Mengelola bank dan mengawasi operasinya"], "answer": 0, "explain": "Pelapor Khusus PBB melaporkan hak atas pendidikan di seluruh dunia.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 9, "q": "Apa yang terutama membentuk perkembangan otak pada tahun-tahun awal?", "options": ["Warna mainan yang dimiliki anak", "Pengalaman dan hubungan", "Jumlah bus sekolah yang beroperasi di kota", "Harga seragam sekolah yang dibeli setiap tahun"], "answer": 1, "explain": "Hubungan dan pengalaman membentuk perkembangan otak di masa awal kehidupan.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Mengapa kebijakan anak usia dini memerlukan koordinasi lintas sektor?", "options": ["Anak hanya membutuhkan pendidikan di kelas untuk belajar dengan baik", "Anak hanya membutuhkan perawatan kesehatan untuk berkembang", "Kebutuhan anak mencakup kesehatan, gizi, pengasuhan, dan pembelajaran", "Anak tidak membutuhkan apa pun dari layanan atau keluarga"], "answer": 2, "explain": "Koordinasi membantu memenuhi kebutuhan anak di berbagai layanan.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu indeks perkembangan anak usia dini?", "options": ["Ukuran gedung sekolah dan kondisinya saat ini", "Hitungan hewan peliharaan milik para guru di rumah", "Daftar seluruh hari libur nasional dan daerah tiap tahun", "Ukuran kesiapan anak di bidang-bidang utama"], "answer": 3, "explain": "Indeks perkembangan melacak kesiapan anak di berbagai bidang.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu interaksi kaya bahasa pada usia dini?", "options": ["Percakapan yang membangun kosakata dan pemahaman", "Bermain diam dengan mainan tanpa bicara sama sekali di ruangan", "Berteriak terus-menerus kepada anak sepanjang hari di rumah", "Hanya menonton televisi berjam-jam setiap hari"], "answer": 0, "explain": "Interaksi kaya bahasa mendukung membaca dan pembelajaran di kemudian hari.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu identifikasi dini dan rujukan?", "options": ["Mengabaikan anak yang membutuhkan bantuan di sekolah dan di rumah", "Menemukan anak yang membutuhkan bantuan dan menghubungkan mereka dengan layanan", "Memberi label permanen yang kaku kepada anak sejak dini", "Mengirim anak pulang setiap kali menunjukkan kebutuhan bantuan"], "answer": 1, "explain": "Sistem rujukan menghubungkan anak dengan dukungan yang tepat sejak dini.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Apa itu dukungan keluarga pada anak usia dini?", "options": ["Memisahkan anak dari keluarga dan rumah mereka", "Melarang kunjungan keluarga ke sekolah sepanjang tahun", "Bantuan bagi keluarga untuk merawat dan mendidik anak kecil", "Mengabaikan keluarga sepenuhnya dalam setiap keputusan sekolah"], "answer": 2, "explain": "Dukungan keluarga memperkuat pembelajaran di rumah dan kesejahteraan.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Bagaimana kesehatan anak berhubungan dengan pembelajaran?", "options": ["Kesehatan tidak berhubungan dengan pembelajaran di sekolah mana pun", "Anak yang sakit belajar lebih cepat daripada anak yang sehat di kelas", "Kesehatan hanya penting setelah jam sekolah berakhir selamanya", "Kesehatan yang baik mendukung kehadiran, perhatian, dan perkembangan"], "answer": 3, "explain": "Kesehatan anak sangat terkait dengan hasil pembelajaran.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "Apa itu literasi sepanjang hayat?", "options": ["Terus mengembangkan keterampilan membaca dan menulis sepanjang hidup", "Membaca hanya di masa kanak-kanak lalu tidak lagi setelahnya", "Membaca hanya di sekolah dan tidak pernah di rumah atau di luar", "Membaca hanya untuk pekerjaan dan tidak ada yang lain sepanjang hidup"], "answer": 0, "explain": "Literasi sepanjang hayat berarti terus membaca dan menulis di sepanjang hidup.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Apa itu keterampilan membaca untuk memperoleh informasi?", "options": ["Hanya membaca fiksi dan cerita rekaan", "Menemukan dan menggunakan fakta dalam teks", "Hanya membaca puisi dan karya sastra", "Membaca tanpa tujuan tertentu hanya karena kebiasaan"], "answer": 1, "explain": "Membaca untuk informasi membantu siswa menemukan fakta untuk mengambil keputusan.", "src": "UNESCO"}, {"ch": 10, "q": "Apa itu keterbacaan (readability) sebuah teks?", "options": ["Seberapa berat sebuah buku saat dipegang", "Berapa banyak halaman dan bab yang tepat dalam sebuah buku", "Seberapa mudah teks itu dibaca dan dipahami", "Berapa harga yang harus dibayar untuk membeli buku baru"], "answer": 2, "explain": "Keterbacaan bergantung pada bahasa, panjang kalimat, dan kosakata.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Apa itu kesenjangan gender dalam literasi?", "options": ["Perbedaan tinggi badan rata-rata antara anak perempuan dan laki-laki", "Perbedaan ukuran sepatu antara anak perempuan dan laki-laki", "Perbedaan warna favorit antara anak perempuan dan laki-laki", "Perbedaan keterampilan membaca antara anak perempuan dan laki-laki"], "answer": 3, "explain": "Kesenjangan gender dalam literasi bervariasi menurut negara dan memerlukan respons yang tepat sasaran.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 10, "q": "Apa itu akses bahan cetak di wilayah berketerbatasan sumber daya?", "options": ["Akses ke bahan cetak untuk dibaca", "Melarang sepenuhnya semua jenis pencetakan bahan tertulis", "Mencetak uang khusus untuk kebutuhan negara saja", "Mencetak peta permukaan Bulan yang sangat rinci saja"], "answer": 0, "explain": "Akses bahan cetak membantu siswa di wilayah terbatas untuk berlatih membaca.", "src": "UNESCO"}, {"ch": 10, "q": "Apa itu kebijakan literasi dalam bahasa ibu?", "options": ["Kebijakan untuk melarang bahasa ibu di semua sekolah di negeri ini", "Kebijakan untuk mengajarkan membaca awal dalam bahasa yang digunakan anak", "Kebijakan untuk mengajar hanya bahasa Inggris di semua kelas di setiap sekolah", "Kebijakan untuk mengajar hanya bahasa isyarat di semua kelas sejak usia enam tahun"], "answer": 1, "explain": "Literasi bahasa ibu mendukung membaca awal dan identitas.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Apa itu literasi untuk pembangunan?", "options": ["Literasi tanpa tujuan dalam kehidupan sehari-hari atau pekerjaan", "Literasi hanya untuk wisatawan yang berkunjung setiap tahun", "Menggunakan literasi untuk meningkatkan kesehatan, pekerjaan, dan kehidupan masyarakat", "Literasi yang berakhir ketika setiap anak berusia sepuluh tahun"], "answer": 2, "explain": "Literasi mendukung pembangunan di bidang kesehatan, pekerjaan, dan kehidupan warga.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Apa itu program membaca untuk kesenangan?", "options": ["Program yang melarang buku cerita anak sepenuhnya", "Program yang hanya menguji ejaan dan tata tulis", "Program yang berhenti mengajarkan membaca setelah usia sepuluh tahun", "Program yang mendorong anak membaca untuk bersenang-senang"], "answer": 3, "explain": "Membaca untuk kesenangan membangun motivasi dan kebiasaan yang mendukung literasi sepanjang hayat.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 11, "q": "Apa arti inklusi sebagai prinsip hak asasi manusia dalam pendidikan?", "options": ["Setiap siswa merasa diterima dan ikut serta", "Sebagian siswa dipisahkan dari yang lain", "Siswa dijauhkan berdasarkan kemampuan mereka", "Siswa dikeluarkan secara sengaja dari sistem"], "answer": 0, "explain": "Inklusi adalah prinsip hak asasi manusia yang memastikan rasa memiliki dan partisipasi.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu pendidikan guru yang inklusif?", "options": ["Melatih guru untuk mengajar hanya siswa terbaik", "Melatih guru untuk mengajar semua siswa", "Melatih guru untuk menghindari siswa penyandang disabilitas", "Melatih guru hanya dalam bidang olahraga"], "answer": 1, "explain": "Pelatihan guru inklusif menyiapkan guru untuk kelas yang beragam.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa arti dukungan individual di sekolah inklusif?", "options": ["Dukungan hanya untuk sekolah secara keseluruhan dan bukan untuk siswa", "Dukungan hanya untuk siswa terbaik di setiap tingkat kelas", "Bantuan yang disesuaikan dengan kebutuhan khusus setiap siswa", "Tidak ada dukungan sama sekali bagi siswa mana pun kapan pun"], "answer": 2, "explain": "Dukungan individual menyesuaikan bantuan untuk setiap siswa.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu inklusi disabilitas dalam kurikulum?", "options": ["Mengecualikan disabilitas dari setiap pelajaran yang diajarkan di kelas", "Mengajarkan disabilitas sebagai hukuman bagi siswa yang berperilaku buruk", "Mengajarkan disabilitas hanya di pelajaran olahraga setiap minggu", "Memasukkan disabilitas sebagai bagian dari pembelajaran tentang keberagaman"], "answer": 3, "explain": "Inklusi disabilitas dalam kurikulum mendorong rasa hormat dan pemahaman.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu penilaian partisipatif untuk inklusi?", "options": ["Melibatkan siswa dalam menilai kemajuan mereka sendiri", "Menilai siswa secara diam-diam tanpa memberi tahu mereka", "Mengabaikan pendapat siswa tentang kualitas pekerjaan mereka", "Menilai siswa hanya berdasarkan tinggi badan dan penampilan mereka"], "answer": 0, "explain": "Penilaian partisipatif membangun kesadaran diri dan inklusi.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Apa itu perekrutan guru yang inklusif?", "options": ["Hanya merekrut dari satu kelompok saja", "Merekrut guru dari berbagai kelompok", "Menolak semua pelamar yang mendaftar", "Merekrut hanya berdasarkan hubungan keluarga"], "answer": 1, "explain": "Perekrutan inklusif membantu sekolah mencerminkan komunitas yang mereka layani.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 11, "q": "Apa itu data inklusif tentang disabilitas?", "options": ["Data yang menyembunyikan disabilitas sepenuhnya dari publik", "Data tentang disabilitas hanya di olahraga dan permainan setiap musim", "Data yang mencakup penyandang disabilitas dan kebutuhan mereka", "Data yang tidak pernah dikumpulkan di sekolah atau distrik mana pun"], "answer": 2, "explain": "Data inklusif membantu kebijakan menanggapi disabilitas.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Mengapa hak atas pendidikan disebut hak pengganda (multiplier right)?", "options": ["Karena mengalikan harga buku pelajaran dan bahan ajar", "Karena menggandakan biaya sekolah yang dibayar keluarga", "Karena hanya berlaku untuk para guru", "Karena membantu orang mengakses hak-hak lain"], "answer": 3, "explain": "Pendidikan membantu orang mengakses kesehatan, pekerjaan, partisipasi politik, dan hak-hak lainnya.", "src": "UN Special Rapporteur on the Right to Education"}]};
